-- ============================================================
-- ARUR HUB RECODED BY XEN LOL — Arcade Basketball + Basketball Legends + Hoopz + Football Fusion 3 + Murder Mystery 2 + Blox Fruits + Practical Basketball
-- ============================================================

local _print, _warn = print, warn
print = function() end
warn = function() end

-- ============================================================
-- ARUR UI — custom interface built for ARUR HUB
-- Dark navy panels, electric-blue accents, pill tabs and a
-- two-column card layout. Works with mouse, keyboard and touch.
-- ============================================================
local RiftUI = (function()
    local TweenService = game:GetService("TweenService")
    local UIS          = game:GetService("UserInputService")
    local HttpService  = game:GetService("HttpService")
    local Players      = game:GetService("Players")
    local LocalPlayer  = Players.LocalPlayer

    local Lib = { Flags = {}, Windows = {}, Version = "1.0.0" }
    local TOUCH = UIS.TouchEnabled and not UIS.KeyboardEnabled
    Lib.Touch = TOUCH

    Lib.Assets = {
        Logo   = "rbxassetid://104266247868011",
        Shadow = "rbxassetid://6014261993",
    }

    local WHITE = Color3.new(1, 1, 1)
    -- Fatal Labs palette: pure black with the electric blue of the star logo
    local DEFAULT = {
        Background  = Color3.fromRGB(3,   3,   8),
        Surface     = Color3.fromRGB(7,   8,   18),
        Surface2    = Color3.fromRGB(11,  13,  30),
        Surface3    = Color3.fromRGB(18,  21,  48),
        Stroke      = Color3.fromRGB(22,  26,  62),
        StrokeHover = Color3.fromRGB(60,  76,  245),
        Accent      = Color3.fromRGB(62,  80,  255),
        AccentDark  = Color3.fromRGB(16,  22,  118),
        AccentLight = Color3.fromRGB(132, 146, 255),
        Text        = Color3.fromRGB(236, 238, 255),
        Muted       = Color3.fromRGB(116, 122, 168),
        Glow        = Color3.fromRGB(42,  58,  240),
        Warning     = Color3.fromRGB(240, 176, 108),
        Success     = Color3.fromRGB(120, 220, 170),
        Error       = Color3.fromRGB(240, 112, 120),
    }
    Lib.Themes = { Default = DEFAULT }
    local T = table.clone(DEFAULT)
    Lib.Theme = T

    local function applyTheme(theme)
        local src = (type(theme) == "string" and Lib.Themes[theme]) or (type(theme) == "table" and theme) or nil
        for k, v in pairs(DEFAULT) do T[k] = v end
        if src then
            for k, v in pairs(src) do if typeof(v) == "Color3" then T[k] = v end end
            if not src.AccentLight then T.AccentLight = T.Accent:Lerp(WHITE, 0.35) end
        end
    end

    -- Close windows left over from a previous run
    local env = (type(getgenv) == "function" and getgenv()) or _G
    if type(env.__RiftUIActive) == "table" then
        for _, w in ipairs(env.__RiftUIActive) do pcall(function() w:Destroy() end) end
    end
    env.__RiftUIActive = Lib.Windows

    -- ---------------------------------------------------------- fonts
    local function mkFont(family, weight)
        local ok, f = pcall(function() return Font.new(family, weight) end)
        if ok and f then return f end
        return Font.fromEnum(Enum.Font.GothamMedium)
    end
    local BUILDER = "rbxasset://fonts/families/BuilderSans.json"
    local MONT    = "rbxasset://fonts/families/Montserrat.json"
    Lib.Fonts = {
        Regular = mkFont(BUILDER, Enum.FontWeight.Regular),
        Medium  = mkFont(BUILDER, Enum.FontWeight.Medium),
        Bold    = mkFont(BUILDER, Enum.FontWeight.Bold),
        Title   = mkFont(MONT, Enum.FontWeight.Bold),
    }
    local FONTS = Lib.Fonts
    function Lib:LoadFont() return true end

    -- ---------------------------------------------------------- helpers
    local tweenCache = {}
    local function tween(obj, props, t, style, dir)
        t = t or 0.2
        if t <= 0 then
            for k, v in pairs(props) do obj[k] = v end
            return nil
        end
        style = style or Enum.EasingStyle.Quart
        dir = dir or Enum.EasingDirection.Out
        local key = tostring(t) .. style.Name .. dir.Name
        local info = tweenCache[key]
        if not info then info = TweenInfo.new(t, style, dir); tweenCache[key] = info end
        local tw = TweenService:Create(obj, info, props)
        tw:Play()
        return tw
    end

    local function new(class, props, children)
        local o = Instance.new(class)
        for k, v in pairs(props or {}) do
            if k ~= "Parent" then o[k] = v end
        end
        if children then for _, c in ipairs(children) do c.Parent = o end end
        if props and props.Parent then o.Parent = props.Parent end
        return o
    end
    local function corner(o, r)
        if type(r) == "number" then r = UDim.new(0, r) end
        return new("UICorner", { CornerRadius = r or UDim.new(0, 8), Parent = o })
    end
    local FULL = UDim.new(1, 0)
    local function stroke(o, color, tr, th)
        return new("UIStroke", {
            Color = color or T.Stroke, Transparency = tr or 0, Thickness = th or 1,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = o,
        })
    end
    local function padding(o, l, r, t, b)
        return new("UIPadding", {
            PaddingLeft = UDim.new(0, l or 0), PaddingRight = UDim.new(0, r or l or 0),
            PaddingTop = UDim.new(0, t or 0), PaddingBottom = UDim.new(0, b or t or 0), Parent = o,
        })
    end
    local function label(props)
        local d = {
            BackgroundTransparency = 1, BorderSizePixel = 0, FontFace = FONTS.Medium, TextSize = 13,
            TextColor3 = T.Text, TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd, Text = "",
        }
        for k, v in pairs(props) do d[k] = v end
        return new("TextLabel", d)
    end
    local function gradient(o, c1, c2, rot)
        return new("UIGradient", { Color = ColorSequence.new(c1, c2), Rotation = rot or 0, Parent = o })
    end
    local function safeCall(fn, ...)
        if type(fn) ~= "function" then return end
        local ok, err = pcall(fn, ...)
        if not ok then env.__RiftUILastError = tostring(err) end
    end
    local function isPress(i)
        return i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch
    end
    local function isMove(i)
        return i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch
    end

    -- Copies the options table and maps alternative option names onto the main ones.
    local function norm(o, aliases)
        local r = {}
        if type(o) == "string" then r.Name = o
        elseif type(o) == "table" then for k, v in pairs(o) do r[k] = v end end
        for from, to in pairs(aliases or {}) do
            if r[to] == nil and r[from] ~= nil then r[to] = r[from] end
        end
        if r.Name == nil and r.Title ~= nil then r.Name = r.Title end
        if r.Desc == nil and r.Description ~= nil then r.Desc = r.Description end
        if r.Desc == "" then r.Desc = nil end
        if type(r.Range) == "table" then r.Min = r.Min or r.Range[1]; r.Max = r.Max or r.Range[2] end
        return r
    end

    local KEYNAMES = {
        [Enum.KeyCode.LeftControl] = "LCtrl", [Enum.KeyCode.RightControl] = "RCtrl",
        [Enum.KeyCode.LeftShift] = "LShift", [Enum.KeyCode.RightShift] = "RShift",
        [Enum.KeyCode.LeftAlt] = "LAlt", [Enum.KeyCode.RightAlt] = "RAlt",
        [Enum.KeyCode.Return] = "Enter", [Enum.KeyCode.Escape] = "Esc",
        -- controller buttons
        [Enum.KeyCode.ButtonA] = "Pad A", [Enum.KeyCode.ButtonB] = "Pad B",
        [Enum.KeyCode.ButtonX] = "Pad X", [Enum.KeyCode.ButtonY] = "Pad Y",
        [Enum.KeyCode.ButtonL1] = "Pad L1", [Enum.KeyCode.ButtonR1] = "Pad R1",
        [Enum.KeyCode.ButtonL2] = "Pad L2", [Enum.KeyCode.ButtonR2] = "Pad R2",
        [Enum.KeyCode.ButtonL3] = "Pad L3", [Enum.KeyCode.ButtonR3] = "Pad R3",
        [Enum.KeyCode.ButtonSelect] = "Pad Select", [Enum.KeyCode.ButtonStart] = "Pad Start",
        [Enum.KeyCode.DPadUp] = "Pad Up", [Enum.KeyCode.DPadDown] = "Pad Down",
        [Enum.KeyCode.DPadLeft] = "Pad Left", [Enum.KeyCode.DPadRight] = "Pad Right",
    }
    local function keyName(k)
        if k == nil then return "None" end
        return KEYNAMES[k] or k.Name
    end
    -- keyboard keys and controller buttons both count as keybind input (thumbsticks are analog, so they don't)
    local function isBindInput(i)
        local t = i.UserInputType
        if t == Enum.UserInputType.Keyboard then return true end
        if t.Name:sub(1, 7) ~= "Gamepad" then return false end
        local k = i.KeyCode
        return k ~= Enum.KeyCode.Thumbstick1 and k ~= Enum.KeyCode.Thumbstick2 and k ~= Enum.KeyCode.Unknown
    end
    local function toKey(k)
        if typeof(k) == "EnumItem" then return k end
        if type(k) ~= "string" or k == "" or k == "None" then return nil end
        local ok, v = pcall(function() return Enum.KeyCode[k] end)
        if ok then return v end
        return nil
    end

    local function snapper(lo, hi, step)
        if hi < lo then lo, hi = hi, lo end
        if not step or step <= 0 then step = 1 end
        local dec = 0
        while dec < 6 do
            local s = step * 10 ^ dec
            if math.abs(s - math.floor(s + 0.5)) < 1e-9 then break end
            dec += 1
        end
        local fmt = "%." .. dec .. "f"
        return {
            snap = function(v)
                v = math.floor(v / step + 0.5) * step
                v = tonumber(string.format(fmt, v)) or v
                return math.clamp(v, lo, hi)
            end,
            format = function(v) return string.format(fmt, v) end,
        }
    end

    -- ---------------------------------------------------------- icons (lucide names or asset ids)
    local IconPack
    local function getIcons()
        if IconPack ~= nil then return IconPack end
        local ok, res = pcall(function()
            return loadstring(game:HttpGet("https://raw.githubusercontent.com/Footagesus/Icons/refs/heads/main/lucide/dist/Icons.lua"))()
        end)
        IconPack = (ok and type(res) == "table") and res or false
        return IconPack
    end
    local function resolveIcon(name)
        if typeof(name) == "table" then return name.Image, name.RectOffset, name.RectSize end
        if type(name) ~= "string" or name == "" then return nil end
        if name:find("^rbxassetid://") or name:find("^rbxasset://") or name:find("^http") then return name end
        local key = name:gsub("^lucide:", "")
        local pack = getIcons()
        if not pack then return nil end
        local ic = (pack.Icons and pack.Icons[key]) or pack[key]
        if ic == nil then -- lucide renamed home -> house; accept either name
            local alt = (key == "home" and "house") or (key == "house" and "home") or nil
            if alt then ic = (pack.Icons and pack.Icons[alt]) or pack[alt] end
        end
        if type(ic) == "table" then
            local img = ic.Image
            if type(img) == "number" then img = "rbxassetid://" .. tostring(img) end
            local sheet = (pack.Spritesheets and pack.Spritesheets[tostring(img)]) or img
            return sheet, ic.ImageRectPosition, ic.ImageRectSize
        elseif type(ic) == "string" then
            return ic
        end
        return nil
    end
    local function setIcon(img, name)
        local id, off, size = resolveIcon(name)
        if id then
            img.Image = id
            if off and size then
                img.ImageRectOffset = off; img.ImageRectSize = size
            else
                img.ImageRectOffset = Vector2.zero; img.ImageRectSize = Vector2.zero
            end
            img.Visible = true
        else
            img.Visible = false
        end
    end

    local function guiParent()
        local ok, h = pcall(function() return gethui and gethui() end)
        if ok and h then return h end
        local okCore, core = pcall(function()
            local cg = game:GetService("CoreGui")
            local probe = Instance.new("Folder"); probe.Parent = cg; probe:Destroy()
            return cg
        end)
        if okCore and core then return core end
        return LocalPlayer:WaitForChild("PlayerGui")
    end

    local function richTitle(name)
        local a, b = tostring(name):match("^(.-)(%..+)$")
        if not a then a, b = tostring(name):match("^(%S+)(%s.+)$") end
        if a and a ~= "" then
            return a .. '<font color="#' .. T.Accent:ToHex() .. '">' .. b .. "</font>"
        end
        return tostring(name)
    end

    -- ---------------------------------------------------------- classes
    local Window = {}; Window.__index = Window
    local Tab = {}; Tab.__index = Tab

    local W_W, W_H = 600, 420
    local HEADER_H, TABS_H = 54, 40

    -- Shared element plumbing: flags, config autosave, destroy/visible/lock helpers.
    local function finalize(tab, o, el, frame, kind, cbKey)
        el._type = kind
        el._name = o.Name
        el._frame = frame
        el._conns = el._conns or {}
        local win = tab and tab.Window
        if o.Flag then
            Lib.Flags[o.Flag] = el
            if win then
                win.Flags[o.Flag] = el
                cbKey = cbKey or "Callback"
                local orig = o[cbKey]
                o[cbKey] = function(...)
                    if type(orig) == "function" then orig(...) end
                    win:_autoSave()
                end
            end
        end
        function el:Destroy()
            if el._destroyed then return end
            el._destroyed = true
            for _, c in ipairs(el._conns) do pcall(function() c:Disconnect() end) end
            el._conns = {}
            if o.Flag then
                if Lib.Flags[o.Flag] == el then Lib.Flags[o.Flag] = nil end
                if win and win.Flags[o.Flag] == el then win.Flags[o.Flag] = nil end
            end
            if frame then frame:Destroy() end
        end
        if el.SetTitle == nil then
            function el:SetTitle(t)
                local x = frame and frame:FindFirstChild("Title", true)
                if x then x.Text = tostring(t) end
            end
        end
        if el.SetDesc == nil then
            function el:SetDesc(t)
                local x = frame and frame:FindFirstChild("Desc", true)
                if x then x.Text = tostring(t) end
            end
        end
        el.Visible = true
        function el:SetVisible(v)
            el.Visible = v ~= false
            if frame then frame.Visible = el.Visible end
        end
        el.Locked = false
        local overlay, overlayText
        function el:SetLocked(state, reason)
            el.Locked = state == true
            if el.Locked and type(el.SetOpen) == "function" then el:SetOpen(false) end
            if not frame then return end
            if not overlay then
                if not el.Locked then return end
                overlay = new("TextButton", {
                    Name = "Lock", Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.Surface,
                    BackgroundTransparency = 0.25, Text = "", AutoButtonColor = false, ZIndex = 20, Parent = frame,
                })
                corner(overlay, 6)
                overlayText = label({
                    Size = UDim2.new(1, -8, 1, 0), Text = "", TextSize = 11, TextColor3 = T.Muted,
                    TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 21, Parent = overlay,
                })
            end
            overlayText.Text = reason or "Locked"
            overlay.Visible = el.Locked
        end
        if o.Locked then el:SetLocked(true, o.LockedReason) end
        if o.Visible == false then el:SetVisible(false) end
        return el
    end

    local function listen(win, el, signal, fn)
        local c = UIS[signal]:Connect(fn)
        table.insert(win._connections, c)
        if el then el._conns = el._conns or {}; table.insert(el._conns, c) end
        return c
    end

    local function titleDesc(parent, name, desc, rightOffset, rightScale)
        local wScale = 1 - (rightScale or 0)
        local t, d
        if desc then
            t = label({ Name = "Title", Text = tostring(name), Position = UDim2.fromOffset(0, 3), Size = UDim2.new(wScale, -(rightOffset or 0), 0, 16), Parent = parent })
            d = label({ Name = "Desc", Text = tostring(desc), FontFace = FONTS.Regular, TextSize = 11, TextColor3 = T.Muted, Position = UDim2.fromOffset(0, 20), Size = UDim2.new(wScale, -(rightOffset or 0), 0, 14), Parent = parent })
        else
            t = label({ Name = "Title", Text = tostring(name), Size = UDim2.new(wScale, -(rightOffset or 0), 1, 0), Parent = parent })
        end
        return t, d
    end

    -- ========================================================== WINDOW
    -- Embedded audio-only copies of the four supplied clips; no external music hosting needed.
    local function RiftIntroAudio(index)
        local tracks = {
        "",
        "",
        "",
        ""
        }
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for i = 1, #alphabet do lookup[alphabet:byte(i)] = i - 1 end
        local data, out = tracks[index], {}
        for i = 1, #data, 4 do
            local a, b, c, d = data:byte(i, i + 3)
            local value = lookup[a] * 262144 + lookup[b] * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
            local chunk = string.char(bit32.extract(value, 16, 8))
            if c ~= 61 then chunk = chunk .. string.char(bit32.extract(value, 8, 8)) end
            if d ~= 61 then chunk = chunk .. string.char(bit32.extract(value, 0, 8)) end
            out[#out + 1] = chunk
        end
        return table.concat(out)
    end

    function Lib:CreateWindow(opts)
        opts = norm(opts, { Title = "Name", Subtitle = "LoadingSubtitle", Keybind = "ToggleUIKeybind" })
        applyTheme(opts.Theme)

        local W = setmetatable({}, Window)
        W.Name = tostring(opts.Name or "Arur Hub")
        W.Title = W.Name
        W.Author = tostring(opts.LoadingSubtitle or "")
        W.Flags, W.Tabs, W._connections = {}, {}, {}
        W.Open, W.Opened = false, false
        W.Keybind = toKey(opts.ToggleUIKeybind) or Enum.KeyCode.RightControl
        W._notifyOrder = 0
        W._fitScale = 1

        local cfg = opts.ConfigurationSaving
        if type(cfg) == "table" and cfg.Enabled ~= false then
            W.ConfigFolder = cfg.FolderName or "RiftWtf"
            W.ConfigName = cfg.FileName or "default"
            W._autoSaveEnabled = cfg.AutoSave == true
        else
            W.ConfigFolder, W.ConfigName, W._autoSaveEnabled = "RiftWtf", "default", false
        end

        local gui = new("ScreenGui", {
            Name = "RiftWtf_UI", ResetOnSpawn = false, IgnoreGuiInset = true,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 999,
        })
        pcall(function() if syn and syn.protect_gui then syn.protect_gui(gui) end end)
        gui.Parent = guiParent()
        W.Gui = gui

        -- root + shadow + body
        local root = new("Frame", {
            Name = "Root", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(W_W, W_H), BackgroundTransparency = 1, Visible = false, Parent = gui,
        })
        local scale = new("UIScale", { Scale = 1, Parent = root })
        local shadow = new("ImageLabel", {
            Name = "Shadow", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.new(1, 70, 1, 70), BackgroundTransparency = 1, Image = Lib.Assets.Shadow,
            ImageColor3 = T.Glow, ImageTransparency = 1, ScaleType = Enum.ScaleType.Slice,
            SliceCenter = Rect.new(49, 49, 450, 450), ZIndex = 0, Parent = root,
        })
        local body = new("CanvasGroup", {
            Name = "Body", Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.Background,
            BorderSizePixel = 0, GroupTransparency = 1, Parent = root,
        })
        corner(body, 12)
        local border = new("Frame", { Name = "Border", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 5, Parent = root })
        corner(border, 12)
        local bodyStroke = stroke(border, T.Stroke, 1)

        -- soft blue aura in the corner + accent line on top
        local aura = new("Frame", {
            Name = "Aura", Position = UDim2.fromOffset(-120, -160), Size = UDim2.fromOffset(420, 320),
            BackgroundColor3 = T.Glow, BorderSizePixel = 0, Visible = false, Parent = body,
        })
        corner(aura, FULL)
        new("UIGradient", {
            Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.86), NumberSequenceKeypoint.new(0.6, 0.97), NumberSequenceKeypoint.new(1, 1) }),
            Rotation = 35, Parent = aura,
        })
        local topLine = new("Frame", { Name = "TopLine", Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = T.Accent, BorderSizePixel = 0, Visible = false, Parent = body })
        new("UIGradient", {
            Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.1), NumberSequenceKeypoint.new(1, 1) }),
            Parent = topLine,
        })

        -- header
        local header = new("Frame", { Name = "Header", Size = UDim2.new(1, 0, 0, HEADER_H), BackgroundTransparency = 1, Parent = body })
        local logoHolder = new("Frame", {
            AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 16, 0.5, 0), Size = UDim2.fromOffset(32, 32),
            BackgroundColor3 = T.Surface2, BorderSizePixel = 0, Parent = header,
        })
        logoHolder.BackgroundTransparency = 1
        new("Frame", { Name = "HeaderLine", Position = UDim2.new(0, 0, 1, -1), Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = T.Stroke, BorderSizePixel = 0, Parent = header })
        local logo = new("ImageLabel", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -4, 1, -4),
            BackgroundTransparency = 1, Image = Lib.Assets.Logo, ScaleType = Enum.ScaleType.Fit, Parent = logoHolder,
        })
        corner(logo, 7)
        local titleLbl = label({
            RichText = true, Text = richTitle(W.Name), FontFace = FONTS.Title, TextSize = 16,
            Position = UDim2.fromOffset(58, 10), Size = UDim2.new(1, -190, 0, 18), Parent = header,
        })
        local subLbl = label({
            Text = W.Author, FontFace = FONTS.Regular, TextSize = 12, TextColor3 = T.Muted,
            Position = UDim2.fromOffset(58, 29), Size = UDim2.new(1, -190, 0, 14), Parent = header,
        })

        local controls = new("Frame", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(0, 28),
            AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, Parent = header,
        })
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right,
            VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 6),
            SortOrder = Enum.SortOrder.LayoutOrder, Parent = controls,
        })
        local keyChip = label({
            Size = UDim2.fromOffset(0, 24), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 0,
            BackgroundColor3 = T.Surface2, TextSize = 11, FontFace = FONTS.Bold, TextColor3 = T.Muted,
            TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.None,
            Text = keyName(W.Keybind), LayoutOrder = 1, Visible = not TOUCH, Parent = controls,
        })
        corner(keyChip, 6); stroke(keyChip, T.Stroke); padding(keyChip, 9, 9, 0, 0)
        local hideBtn = new("TextButton", {
            Size = UDim2.fromOffset(28, 28), BackgroundColor3 = T.Surface2, Text = "", AutoButtonColor = false,
            LayoutOrder = 2, Parent = controls,
        })
        corner(hideBtn, 7)
        local hideStroke = stroke(hideBtn, T.Stroke)
        local hideBar = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(10, 2),
            BackgroundColor3 = T.Muted, BorderSizePixel = 0, Parent = hideBtn,
        })
        corner(hideBar, FULL)
        hideBtn.MouseEnter:Connect(function() tween(hideStroke, { Color = T.StrokeHover }, 0.12); tween(hideBar, { BackgroundColor3 = T.Text }, 0.12) end)
        hideBtn.MouseLeave:Connect(function() tween(hideStroke, { Color = T.Stroke }, 0.2); tween(hideBar, { BackgroundColor3 = T.Muted }, 0.2) end)
        hideBtn.MouseButton1Click:Connect(function() W:Toggle(false) end)

        -- tab strip
        local tabBar = new("ScrollingFrame", {
            Name = "Tabs", Position = UDim2.fromOffset(0, HEADER_H), Size = UDim2.new(1, 0, 0, TABS_H),
            BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 0,
            ScrollingDirection = Enum.ScrollingDirection.X, CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.X, Parent = body,
        })
        padding(tabBar, 14, 14, 0, 0)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = tabBar,
        })
        new("Frame", {
            Name = "Separator", Position = UDim2.fromOffset(0, HEADER_H + TABS_H + 2), Size = UDim2.new(1, 0, 0, 1),
            BackgroundColor3 = T.Stroke, BackgroundTransparency = 1, BorderSizePixel = 0, Parent = body,
        })
        local pagesTop = HEADER_H + TABS_H + 3
        local pages = new("Frame", {
            Name = "Pages", Position = UDim2.fromOffset(0, pagesTop), Size = UDim2.new(1, 0, 1, -pagesTop),
            BackgroundTransparency = 1, ClipsDescendants = true, Parent = body,
        })

        -- notifications (live outside the window so they show while it is hidden)
        local notifyHolder = new("Frame", {
            Name = "Notifications", AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -16, 1, -16),
            Size = UDim2.new(0, 290, 1, -32), BackgroundTransparency = 1, Parent = gui,
        })
        local notifyScale = new("UIScale", { Scale = 1, Parent = notifyHolder })
        new("UIListLayout", {
            VerticalAlignment = Enum.VerticalAlignment.Bottom, HorizontalAlignment = Enum.HorizontalAlignment.Right,
            Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = notifyHolder,
        })

        -- floating logo button: tap to open/close, drag to move
        local fab = new("TextButton", {
            Name = "OpenButton", Size = UDim2.fromOffset(48, 48), Position = UDim2.new(0, 18, 0.5, -24),
            BackgroundColor3 = T.Surface, Text = "", AutoButtonColor = false, Visible = false, Parent = gui,
        })
        corner(fab, FULL)
        local fabStroke = stroke(fab, T.Accent, 0.15, 1.5)
        local fabLogo = new("ImageLabel", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -12, 1, -12),
            BackgroundTransparency = 1, Image = Lib.Assets.Logo, ScaleType = Enum.ScaleType.Fit, Parent = fab,
        })
        corner(fabLogo, FULL)

        W.Root, W.Scale, W.Body, W.BodyStroke, W.Shadow = root, scale, body, bodyStroke, shadow
        W.TabBar, W.Pages, W.NotifyHolder, W.OpenButton = tabBar, pages, notifyHolder, fab
        W._titleLabel, W._subtitleLabel, W._logo, W._keyChipLabel = titleLbl, subLbl, logo, keyChip

        -- drag window by the header
        do
            local dragging, startPos, startRoot
            header.InputBegan:Connect(function(i)
                if isPress(i) then
                    dragging, startPos, startRoot = true, i.Position, root.Position
                end
            end)
            listen(W, nil, "InputChanged", function(i)
                if dragging and isMove(i) then
                    local d = i.Position - startPos
                    root.Position = UDim2.new(startRoot.X.Scale, startRoot.X.Offset + d.X, startRoot.Y.Scale, startRoot.Y.Offset + d.Y)
                end
            end)
            listen(W, nil, "InputEnded", function(i)
                if dragging and isPress(i) then dragging = false end
            end)
        end
        -- drag / tap floating button
        do
            local down, moved, startPos, startFab
            fab.InputBegan:Connect(function(i)
                if isPress(i) then down, moved, startPos, startFab = true, false, i.Position, fab.Position end
            end)
            listen(W, nil, "InputChanged", function(i)
                if down and isMove(i) then
                    local d = i.Position - startPos
                    if d.Magnitude > 6 then moved = true end
                    if moved then
                        fab.Position = UDim2.new(startFab.X.Scale, startFab.X.Offset + d.X, startFab.Y.Scale, startFab.Y.Offset + d.Y)
                    end
                end
            end)
            listen(W, nil, "InputEnded", function(i)
                if down and isPress(i) then
                    down = false
                    if not moved then W:Toggle() end
                end
            end)
            fab.MouseEnter:Connect(function() tween(fabStroke, { Transparency = 0 }, 0.12) end)
            fab.MouseLeave:Connect(function() tween(fabStroke, { Transparency = 0.15 }, 0.2) end)
        end

        -- keep the window inside the screen on any device
        local function fit()
            local cam = workspace.CurrentCamera
            if not cam then return end
            local vs = cam.ViewportSize
            if vs.X <= 0 or vs.Y <= 0 then return end
            local s = math.min(1, (vs.X - 24) / W_W, (vs.Y - 24) / W_H)
            s = math.max(s, 0.45)
            W._fitScale = s
            if W.Open then scale.Scale = s end
            notifyScale.Scale = math.clamp(vs.X / 900, 0.72, 1)
        end
        pcall(fit)
        pcall(function()
            table.insert(W._connections, workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fit))
        end)

        -- toggle key
        listen(W, nil, "InputBegan", function(i, gp)
            if gp or not isBindInput(i) then return end
            if i.KeyCode ~= W.Keybind then return end
            task.defer(function()
                if W._consumedKey == i.KeyCode and os.clock() - (W._consumedAt or 0) < 0.3 then return end
                W:Toggle()
            end)
        end)

        table.insert(Lib.Windows, W)

        -- Arur Hub loading screen: glowing star logo, spinning ring, typed title,
        -- song progress bar. Music: choose one track, then open after playback ends.
        local loader = new("CanvasGroup", {
            Name = "RiftMusicIntro", Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.Background,
            BackgroundTransparency = 0.18, BorderSizePixel = 0, GroupTransparency = 1, Parent = gui,
        })
        new("UIGradient", {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, T.Background),
                ColorSequenceKeypoint.new(0.5, T.AccentDark:Lerp(T.Background, 0.55)),
                ColorSequenceKeypoint.new(1, T.Background),
            }),
            Rotation = 90, Parent = loader,
        })
        local stage = new("Frame", {
            Name = "Stage", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(420, 360), BackgroundTransparency = 1, Parent = loader,
        })
        local stageScale = new("UIScale", { Scale = 1, Parent = stage })
        pcall(function()
            local vp = workspace.CurrentCamera.ViewportSize
            stageScale.Scale = math.clamp(math.min(vp.X / 460, vp.Y / 420), 0.6, 1.15)
        end)

        -- logo with soft glow + spinning light ring
        local glow = new("ImageLabel", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0, 80), Size = UDim2.fromOffset(250, 250),
            BackgroundTransparency = 1, Image = Lib.Assets.Shadow, ImageColor3 = T.Glow, ImageTransparency = 0.35,
            ScaleType = Enum.ScaleType.Slice, SliceCenter = Rect.new(49, 49, 450, 450), Parent = stage,
        })
        local tile = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0, 80), Size = UDim2.fromOffset(124, 124),
            BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, Parent = stage,
        })
        corner(tile, 30)
        local tileScale = new("UIScale", { Scale = 0.6, Parent = tile })
        local ring = new("UIStroke", { Color = WHITE, Thickness = 2.5, Transparency = 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = tile })
        local ringGrad = new("UIGradient", {
            Color = ColorSequence.new(T.Accent, T.AccentLight),
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.35, 0.15),
                NumberSequenceKeypoint.new(0.5, 0.92), NumberSequenceKeypoint.new(1, 0.92),
            }),
            Parent = ring,
        })
        local introLogo = new("ImageLabel", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, -10, 1, -10),
            BackgroundTransparency = 1, Image = Lib.Assets.Logo, ScaleType = Enum.ScaleType.Fit, ImageTransparency = 1, Parent = tile,
        })
        corner(introLogo, 26)

        -- twinkling sparkles, like the ones around the star in the logo
        local sparkles = {}
        for idx, sp in ipairs({ {-92, 30, 9}, {94, 22, 6}, {-78, 132, 5}, {88, 128, 8}, {-118, 82, 4}, {120, 76, 4} }) do
            local d = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, sp[1], 0, sp[2]),
                Size = UDim2.fromOffset(sp[3], sp[3]), Rotation = 45, BackgroundColor3 = T.AccentLight,
                BackgroundTransparency = 1, BorderSizePixel = 0, Parent = stage,
            })
            sparkles[idx] = { frame = d, phase = idx * 1.7 }
        end

        local introTitle = label({
            Text = "", TextColor3 = WHITE, FontFace = FONTS.Title, TextSize = 44, TextTruncate = Enum.TextTruncate.None,
            TextXAlignment = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.new(0.5, 0, 0, 170), Size = UDim2.new(1, 0, 0, 52), Parent = stage,
        })
        new("UITextSizeConstraint", {MinTextSize = 24, MaxTextSize = 44, Parent = introTitle})
        local titleGrad = new("UIGradient", {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, T.Accent), ColorSequenceKeypoint.new(0.5, T.AccentLight),
                ColorSequenceKeypoint.new(1, T.Accent),
            }),
            Parent = introTitle,
        })
        local introGame = label({
            Text = string.upper(W.Author ~= "" and W.Author or "Loading"), FontFace = FONTS.Bold, TextSize = 12,
            TextColor3 = T.Muted, TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center,
            AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 224), Size = UDim2.new(1, 0, 0, 16), Parent = stage,
        })

        local lTrack = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 262),
            Size = UDim2.fromOffset(300, 6), BackgroundColor3 = T.Surface3, BorderSizePixel = 0, Parent = stage,
        })
        corner(lTrack, FULL)
        stroke(lTrack, T.Stroke, 0, 1)
        local lFill = new("Frame", {Size = UDim2.fromScale(0, 1), BackgroundColor3 = WHITE, BorderSizePixel = 0, Parent = lTrack})
        corner(lFill, FULL)
        gradient(lFill, T.AccentDark:Lerp(T.Accent, 0.4), T.AccentLight)
        local lHead = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(1, 0.5), Size = UDim2.fromOffset(12, 12),
            BackgroundColor3 = T.AccentLight, BorderSizePixel = 0, Parent = lFill,
        })
        corner(lHead, FULL)
        stroke(lHead, T.Accent, 0.3, 3)

        local introStatus = label({
            Text = "STARTING", FontFace = FONTS.Medium, TextSize = 11, TextColor3 = T.Muted,
            Position = UDim2.new(0.5, -150, 0, 276), Size = UDim2.fromOffset(220, 16), Parent = stage,
        })
        local introPct = label({
            Text = "0%", FontFace = FONTS.Bold, TextSize = 11, TextColor3 = T.AccentLight,
            TextXAlignment = Enum.TextXAlignment.Right, Position = UDim2.new(0.5, 70, 0, 276),
            Size = UDim2.fromOffset(80, 16), Parent = stage,
        })
        label({
            Text = TOUCH and "Tap the button to open the menu" or ("Press " .. keyName(W.Keybind) .. " to toggle the menu"),
            FontFace = FONTS.Regular, TextSize = 11, TextColor3 = T.Muted, TextTransparency = 0.35,
            TextXAlignment = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.new(0.5, 0, 0, 324), Size = UDim2.new(1, 0, 0, 16), Parent = stage,
        })
        local function setProgress(p)
            p = math.clamp(p, 0, 1)
            lFill.Size = UDim2.fromScale(p, 1)
            introPct.Text = tostring(math.floor(p * 100 + 0.5)) .. "%"
        end

        -- A real scene blur, not an opaque screen covering the game.
        local blur = new("BlurEffect", {
            Name = "RiftIntroBlur", Enabled = true, Size = 0,
            Parent = workspace.CurrentCamera or game:GetService("Lighting"),
        })
        local music
        local cleaned = false
        local animClock = 0
        local blurConnection = game:GetService("RunService").RenderStepped:Connect(function(dt)
            if cleaned then return end
            animClock += dt
            ringGrad.Rotation = (ringGrad.Rotation + dt * 160) % 360
            titleGrad.Offset = Vector2.new(math.sin(animClock * 1.4) * 0.6, 0)
            glow.ImageTransparency = 0.35 + math.sin(animClock * 2.2) * 0.15
            for _, sp in ipairs(sparkles) do
                sp.frame.BackgroundTransparency = 0.25 + (math.sin(animClock * 2.6 + sp.phase) * 0.5 + 0.5) * 0.75
            end
            -- Follow camera replacements and keep graphics presets from disabling the intro.
            local target = workspace.CurrentCamera or game:GetService("Lighting")
            if blur.Parent ~= target then blur.Parent = target end
            blur.Enabled = true
        end)
        local function cleanupIntro()
            if cleaned then return end
            cleaned = true
            blurConnection:Disconnect()
            if music then music:Stop(); music:Destroy() end
            blur:Destroy()
            loader:Destroy()
        end
        table.insert(W._connections, gui.Destroying:Connect(cleanupIntro))
        task.spawn(function()
            tween(loader, {GroupTransparency = 0}, 0.3)
            tween(blur, {Size = 24}, 0.4)
            tween(tileScale, {Scale = 1}, 0.6, Enum.EasingStyle.Back)
            tween(introLogo, {ImageTransparency = 0}, 0.5)
            task.spawn(function()
                task.wait(0.35)
                local title = "Arur Hub"
                for i = 1, #title do
                    if cleaned then return end
                    introTitle.Text = title:sub(1, i)
                    task.wait(0.09)
                end
                if cleaned then return end
                tween(introGame, {TextTransparency = 0}, 0.4)
            end)
            local track = Random.new():NextInteger(1, 4)
            local ok, err = pcall(function()
                local register = getcustomasset or getsynasset
                if type(writefile) ~= "function" or type(register) ~= "function" then
                    error("Music requires writefile and getcustomasset audio support")
                end
                local path = "RiftWtf_Intro_" .. track .. ".mp3"
                writefile(path, RiftIntroAudio(track))
                if cleaned then return end
                music = new("Sound", {Name = "RiftIntroMusic", SoundId = register(path), Volume = 0.65, Looped = false, Parent = game:GetService("SoundService")})
                local deadline = os.clock() + 20
                while not music.IsLoaded and not cleaned and os.clock() < deadline do task.wait(0.05) end
                if cleaned then return end
                if not music.IsLoaded then error("The selected intro song could not load") end
                local ended = false
                local endedConnection = music.Ended:Connect(function() ended = true end)
                music:Play()
                introStatus.Text = "NOW PLAYING  ·  TRACK " .. track
                local playbackDeadline = os.clock() + math.max(music.TimeLength + 5, 35)
                while not ended and not cleaned and os.clock() < playbackDeadline do
                    if music.TimeLength > 0 then
                        setProgress(music.TimePosition / music.TimeLength)
                    end
                    task.wait(0.05)
                end
                endedConnection:Disconnect()
                if not ended and not cleaned then error("Intro playback stopped before finishing") end
            end)
            if cleaned or W._destroyed then return end
            if not ok then
                env.__RiftUILastError = tostring(err)
                introStatus.Text = "MUSIC UNAVAILABLE"
                introStatus.TextColor3 = T.Warning
                _warn("[Arur Hub] Intro: " .. tostring(err))
                task.wait(2)
            end
            if cleaned or W._destroyed then return end
            setProgress(1)
            introStatus.Text = "READY"
            introStatus.TextColor3 = T.Success
            task.wait(0.25)
            if cleaned or W._destroyed then return end
            tween(tileScale, {Scale = 1.15}, 0.35)
            tween(loader, {GroupTransparency = 1}, 0.35)
            tween(blur, {Size = 0}, 0.35)
            task.wait(0.35)
            cleanupIntro()
            if W._destroyed then return end
            W._introDone = true
            fab.Visible = true
            W:Toggle(W._wantOpen ~= false)
        end)

        return W
    end
    Lib.Window = Lib.CreateWindow

    function Lib:Notify(d)
        local w = Lib.Windows[#Lib.Windows]
        if w then return w:Notify(d) end
    end

    function Window:Toggle(state)
        if state == nil then state = not self.Open end
        state = state == true
        if not self._introDone then self._wantOpen = state; return end
        if state == self.Open then return end
        self.Open, self.Opened = state, state
        local s = self._fitScale or 1
        if state then
            self.Root.Visible = true
            self.Scale.Scale = s * 0.94
            tween(self.Scale, { Scale = s }, 0.35, Enum.EasingStyle.Back)
            tween(self.Body, { GroupTransparency = 0 }, 0.22)
            tween(self.BodyStroke, { Transparency = 0 }, 0.22)
            tween(self.Shadow, { ImageTransparency = 0.82 }, 0.3)
        else
            tween(self.Scale, { Scale = s * 0.94 }, 0.18, Enum.EasingStyle.Quint)
            tween(self.Body, { GroupTransparency = 1 }, 0.16)
            tween(self.BodyStroke, { Transparency = 1 }, 0.12)
            tween(self.Shadow, { ImageTransparency = 1 }, 0.16)
            task.delay(0.2, function() if not self.Open then self.Root.Visible = false end end)
        end
    end
    function Window:IsOpen() return self.Open == true end
    function Window:SetKeybind(k)
        k = toKey(k)
        if not k then return end
        self.Keybind = k
        self._keyChipLabel.Text = keyName(k)
    end
    function Window:SetTitle(t) self.Name = tostring(t); self.Title = self.Name; self._titleLabel.Text = richTitle(t) end
    function Window:SetSubtitle(t) self.Author = tostring(t); self._subtitleLabel.Text = tostring(t) end
    function Window:SetIcon(id) setIcon(self._logo, id) end
    function Window:SetKeepOnScreen() end

    function Window:Destroy()
        if self._destroyed then return end
        self._destroyed = true
        for i, w in ipairs(Lib.Windows) do if w == self then table.remove(Lib.Windows, i) break end end
        for _, c in ipairs(self._connections) do pcall(function() c:Disconnect() end) end
        self._connections = {}
        for k, v in pairs(self.Flags) do if Lib.Flags[k] == v then Lib.Flags[k] = nil end end
        self.Flags = {}
        pcall(function() self.Gui:Destroy() end)
    end

    -- ---------------------------------------------------------- notifications
    function Window:Notify(d)
        if type(d) ~= "table" then d = { Content = tostring(d) } end
        local title = d.Title or d.title or d.Name or self.Name
        local content = d.Content or d.content or d.Text or d.text or d.Message or d.message or ""
        local dur = tonumber(d.Duration or d.duration) or 4
        local kind = d.Type or d.type
        local accent = (kind == "Success" and T.Success) or (kind == "Warning" and T.Warning) or (kind == "Error" and T.Error) or T.Accent
        self._notifyOrder += 1

        local slot = new("Frame", {
            Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
            LayoutOrder = self._notifyOrder, Parent = self.NotifyHolder,
        })
        local card = new("CanvasGroup", {
            Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Position = UDim2.fromOffset(330, 0),
            BackgroundColor3 = T.Surface, BorderSizePixel = 0, GroupTransparency = 1, Parent = slot,
        })
        corner(card, 10)
        local inner = new("Frame", {
            Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = card,
        })
        padding(inner, 14, 12, 11, 14)
        local bar = new("Frame", {
            Position = UDim2.fromOffset(0, 10), Size = UDim2.new(0, 3, 1, -20), BackgroundColor3 = accent,
            BorderSizePixel = 0, Parent = card,
        })
        corner(bar, FULL)
        local ic = new("ImageLabel", {
            Size = UDim2.fromOffset(22, 22), BackgroundTransparency = 1, Image = Lib.Assets.Logo,
            ScaleType = Enum.ScaleType.Fit, Parent = inner,
        })
        corner(ic, 6)
        if d.Icon or d.Image then pcall(setIcon, ic, d.Icon or d.Image) end
        label({ Text = tostring(title), FontFace = FONTS.Bold, TextSize = 13, Position = UDim2.fromOffset(32, 0), Size = UDim2.new(1, -32, 0, 16), Parent = inner })
        label({
            Text = tostring(content), FontFace = FONTS.Regular, TextSize = 12, TextColor3 = T.Muted, TextWrapped = true,
            TextTruncate = Enum.TextTruncate.None, TextYAlignment = Enum.TextYAlignment.Top,
            Position = UDim2.fromOffset(32, 18), Size = UDim2.new(1, -32, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = inner,
        })
        local progress = new("Frame", {
            AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.new(1, 0, 0, 2),
            BackgroundColor3 = accent, BackgroundTransparency = 0.2, BorderSizePixel = 0, Parent = card,
        })
        local border = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = card })
        corner(border, 10)
        stroke(border, T.Stroke, 0)
        local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 5, Parent = card })

        local gone = false
        local function dismiss()
            if gone then return end
            gone = true
            tween(card, { Position = UDim2.fromOffset(330, 0), GroupTransparency = 1 }, 0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
            task.delay(0.27, function() slot:Destroy() end)
        end
        hit.MouseButton1Click:Connect(dismiss)
        tween(card, { Position = UDim2.fromOffset(0, 0), GroupTransparency = 0 }, 0.35, Enum.EasingStyle.Quint)
        tween(progress, { Size = UDim2.new(0, 0, 0, 2) }, dur, Enum.EasingStyle.Linear)
        task.delay(dur, dismiss)
        return { Dismiss = dismiss }
    end

    -- ---------------------------------------------------------- keybind toasts (bottom-left)
    -- Small "<feature> ON/OFF" pop-up shown when a keybind flips a feature.
    -- Pressing the same key again updates the existing toast instead of stacking a new one.
    function Window:KeybindNotify(name, on)
        if self._kbDisabled or not self.Gui then return end
        name, on = tostring(name or "Feature"), on == true
        if not self._kbHolder or not self._kbHolder.Parent then
            local h = new("Frame", {
                Name = "KeybindToasts", AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 16, 1, -16),
                Size = UDim2.new(0, 250, 1, -32), BackgroundTransparency = 1, Parent = self.Gui,
            })
            new("UIListLayout", {
                VerticalAlignment = Enum.VerticalAlignment.Bottom, HorizontalAlignment = Enum.HorizontalAlignment.Left,
                Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = h,
            })
            self._kbHolder, self._kbToasts, self._kbOrder = h, {}, 0
        end
        local col = on and T.Accent or T.Muted
        local t = self._kbToasts[name]
        if t and t.slot.Parent then
            t.dot.BackgroundColor3 = col
            t.state.Text, t.state.TextColor3 = on and "ON" or "OFF", col
        else
            self._kbOrder += 1
            local slot = new("Frame", {
                Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1, LayoutOrder = self._kbOrder, Parent = self._kbHolder,
            })
            local card = new("CanvasGroup", {
                Size = UDim2.new(1, 0, 1, 0), Position = UDim2.fromOffset(-270, 0),
                BackgroundColor3 = T.Surface, BorderSizePixel = 0, GroupTransparency = 1, Parent = slot,
            })
            corner(card, 9)
            local dot = new("Frame", {
                AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 12, 0.5, 0), Size = UDim2.fromOffset(8, 8),
                BackgroundColor3 = col, BorderSizePixel = 0, Parent = card,
            })
            corner(dot, FULL)
            label({ Text = name, FontFace = FONTS.Bold, TextSize = 12, Position = UDim2.fromOffset(30, 0), Size = UDim2.new(1, -78, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd, Parent = card })
            local state = label({
                Text = on and "ON" or "OFF", FontFace = FONTS.Bold, TextSize = 12, TextColor3 = col, TextXAlignment = Enum.TextXAlignment.Right,
                AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 0), Size = UDim2.fromOffset(40, 34), Parent = card,
            })
            local border = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = card })
            corner(border, 9)
            stroke(border, T.Stroke, 0)
            t = { slot = slot, card = card, dot = dot, state = state, token = 0 }
            self._kbToasts[name] = t
            tween(card, { Position = UDim2.fromOffset(0, 0), GroupTransparency = 0 }, 0.3, Enum.EasingStyle.Quint)
        end
        t.token += 1
        local mine = t.token
        task.delay(2.2, function()
            if t.token ~= mine or not t.slot.Parent then return end
            if self._kbToasts[name] == t then self._kbToasts[name] = nil end
            tween(t.card, { Position = UDim2.fromOffset(-270, 0), GroupTransparency = 1 }, 0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
            task.delay(0.27, function() pcall(function() t.slot:Destroy() end) end)
        end)
    end

    function Lib:KeybindNotify(name, on)
        local w = Lib.Windows[#Lib.Windows]
        if w then return w:KeybindNotify(name, on) end
    end

    -- ---------------------------------------------------------- configs
    local function fileApi()
        return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
    end
    local function cfgPath(win, name)
        name = (tostring(name or ""):gsub("[^%w%-%_ ]", ""))
        if name == "" then return nil, "invalid config name" end
        return win.ConfigFolder .. "/" .. name .. ".json", name
    end
    local function encodeEl(el)
        local v = el:Get()
        if el._type == "Keybind" then return { Type = el._type, Value = v and v.Name or nil } end
        if el._type == "ColorPicker" then return { Type = el._type, Value = { v.R, v.G, v.B } } end
        return { Type = el._type, Value = v }
    end
    local function decodeEl(el, rec, silent)
        local v = rec.Value
        if el._type == "Keybind" then el:Set(toKey(v), silent)
        elseif el._type == "ColorPicker" then
            if type(v) == "table" then el:Set(Color3.new(v[1], v[2], v[3]), silent) end
        elseif v ~= nil then el:Set(v, silent) end
    end
    function Window:SaveConfig(name)
        if not fileApi() then return false, "file API unavailable" end
        local path, clean = cfgPath(self, name or self.ConfigName)
        if not path then return false, clean end
        local data = {}
        for flag, el in pairs(self.Flags) do
            if el._type and type(el.Get) == "function" then data[flag] = encodeEl(el) end
        end
        local ok, err = pcall(function()
            if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(self.ConfigFolder) then
                makefolder(self.ConfigFolder)
            end
            writefile(path, HttpService:JSONEncode(data))
        end)
        if ok then self.ConfigName = clean end
        return ok, err
    end
    function Window:LoadConfig(name, silent)
        if not fileApi() then return false, "file API unavailable" end
        local path, clean = cfgPath(self, name or self.ConfigName)
        if not path then return false, clean end
        if not isfile(path) then return false, "no config named " .. clean end
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
        if not ok or type(data) ~= "table" then return false, "config is not valid JSON" end
        local auto = self._autoSaveEnabled
        self._autoSaveEnabled = false
        for flag, rec in pairs(data) do
            local el = self.Flags[flag]
            if el and type(el.Set) == "function" and type(rec) == "table" and rec.Type == el._type then
                pcall(decodeEl, el, rec, silent == true)
            end
        end
        self._autoSaveEnabled = auto
        self._autoSaveReady = true
        self.ConfigName = clean
        return true
    end
    function Window:DeleteConfig(name)
        if not fileApi() or type(delfile) ~= "function" then return false, "file API unavailable" end
        local path, clean = cfgPath(self, name)
        if not path then return false, clean end
        if not isfile(path) then return false, "no config named " .. clean end
        return pcall(delfile, path)
    end
    function Window:ListConfigs()
        local out = {}
        if type(listfiles) ~= "function" or type(isfolder) ~= "function" or not isfolder(self.ConfigFolder) then return out end
        for _, p in ipairs(listfiles(self.ConfigFolder)) do
            local n = tostring(p):match("([^/\\]+)%.json$")
            if n then table.insert(out, n) end
        end
        table.sort(out)
        return out
    end
    function Window:SetAutoSave(v) self._autoSaveEnabled = v == true end
    function Window:_autoSave()
        if not self._autoSaveEnabled or self._destroyed or not self._autoSaveReady or self._autoSavePending then return end
        self._autoSavePending = true
        task.delay(0.5, function()
            self._autoSavePending = false
            pcall(function() self:SaveConfig(self.ConfigName) end)
        end)
    end

    -- ========================================================== TABS
    function Window:CreateTab(o, icon)
        o = norm(o, {})
        if icon ~= nil and o.Icon == nil then o.Icon = icon end
        local tab = setmetatable({ Name = tostring(o.Name or "Tab"), Window = self, _order = 0, _cols = {}, _colH = { 0, 0 } }, Tab)

        local btn = new("TextButton", {
            Size = UDim2.fromOffset(0, 30), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = T.Surface3,
            BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = #self.Tabs + 1, Parent = self.TabBar,
        })
        corner(btn, 7)
        local bStroke = stroke(btn, T.Stroke, 0)
        padding(btn, 12, 14, 0, 0)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 7), SortOrder = Enum.SortOrder.LayoutOrder, Parent = btn,
        })
        local ic = new("ImageLabel", {
            Size = UDim2.fromOffset(15, 15), BackgroundTransparency = 1, ImageColor3 = T.Muted,
            Visible = false, LayoutOrder = 1, Parent = btn,
        })
        task.spawn(setIcon, ic, o.Icon)
        local txt = label({
            Size = UDim2.fromOffset(0, 30), AutomaticSize = Enum.AutomaticSize.X, Text = tab.Name, TextSize = 13,
            TextColor3 = T.Muted, TextTruncate = Enum.TextTruncate.None, LayoutOrder = 2, Parent = btn,
        })

        local page = new("ScrollingFrame", {
            Name = tab.Name, Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0,
            ScrollBarThickness = 3, ScrollBarImageColor3 = T.Accent, ScrollBarImageTransparency = 0.35,
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y, Visible = false, Parent = self.Pages,
        })
        padding(page, 12, 12, 12, 14)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10),
            SortOrder = Enum.SortOrder.LayoutOrder, Parent = page,
        })
        for i = 1, 2 do
            local col = new("Frame", {
                Name = i == 1 and "Left" or "Right", Size = UDim2.new(0.5, -5, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1, LayoutOrder = i, Parent = page,
            })
            new("UIListLayout", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder, Parent = col })
            tab._cols[i] = col
        end

        tab._btn, tab._bstroke, tab._icon, tab._txt, tab._page = btn, bStroke, ic, txt, page
        btn.MouseEnter:Connect(function()
            if self.CurrentTab ~= tab then tween(btn, { BackgroundTransparency = 0.6 }, 0.12); tween(txt, { TextColor3 = T.Text }, 0.12) end
        end)
        btn.MouseLeave:Connect(function()
            if self.CurrentTab ~= tab then tween(btn, { BackgroundTransparency = 1 }, 0.2); tween(txt, { TextColor3 = T.Muted }, 0.2) end
        end)
        btn.MouseButton1Click:Connect(function() self:SelectTab(tab) end)

        table.insert(self.Tabs, tab)
        if #self.Tabs == 1 then
            task.defer(function() if not self.CurrentTab then self:SelectTab(tab) end end)
        end
        return tab
    end
    Window.Tab = Window.CreateTab

    function Window:SelectTab(tab)
        if type(tab) == "string" then
            for _, t in ipairs(self.Tabs) do if t.Name == tab then tab = t break end end
        end
        if type(tab) ~= "table" or self.CurrentTab == tab then return end
        self.CurrentTab = tab
        for _, t in ipairs(self.Tabs) do
            local on = t == tab
            tween(t._btn, { BackgroundTransparency = on and 0 or 1 }, 0.18)
            tween(t._bstroke, { Transparency = 0, Color = on and T.StrokeHover or T.Stroke }, 0.18)
            tween(t._txt, { TextColor3 = on and T.Text or T.Muted }, 0.18)
            tween(t._icon, { ImageColor3 = on and T.Accent or T.Muted }, 0.18)
            t._page.Visible = on
        end
        tab._page.Position = UDim2.fromOffset(0, 12)
        tween(tab._page, { Position = UDim2.fromOffset(0, 0) }, 0.28, Enum.EasingStyle.Quint)
    end

    function Tab:_next() self._order += 1; return self._order end
    function Tab:Select() self.Window:SelectTab(self) end

    -- A card is one rounded group; new cards go to whichever column is shorter.
    function Tab:_newCard(title)
        local idx = (self._colH[2] < self._colH[1]) and 2 or 1
        local card = new("Frame", {
            Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.Surface,
            BorderSizePixel = 0, LayoutOrder = self:_next(), Parent = self._cols[idx],
        })
        corner(card, 10)
        stroke(card, T.Stroke)
        padding(card, 12, 12, 10, 12)
        new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = card })
        local rec = { Frame = card, Col = idx, H = 22, Auto = title == nil, _order = 0 }
        self._colH[idx] += 32
        if title then
            local hdr = new("Frame", { Name = "Header", Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1, LayoutOrder = 0, Parent = card })
            local bar = new("Frame", {
                AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(3, 13),
                BackgroundColor3 = WHITE, BorderSizePixel = 0, Parent = hdr,
            })
            bar.Visible = false
            rec.Label = label({ Text = string.upper(title), FontFace = FONTS.Bold, TextSize = 11, TextColor3 = T.Muted, Position = UDim2.fromOffset(0, 0), Size = UDim2.new(1, 0, 1, 0), Parent = hdr })
            self._colH[idx] += 28
        end
        self._card = rec
        return rec
    end
    function Tab:_cardFor(h)
        local c = self._card
        if not c then
            c = self:_newCard(nil)
        elseif c.Auto and not self._hasSections and c.H > 300 then
            c = self:_newCard(nil)
        end
        c.H += h + 4
        self._colH[c.Col] += h + 4
        c._order += 1
        return c
    end
    function Tab:_row(h, class)
        local card = self:_cardFor(h)
        local f = new(class or "Frame", {
            Size = UDim2.new(1, 0, 0, h), BackgroundTransparency = 1, BorderSizePixel = 0,
            LayoutOrder = card._order, Parent = card.Frame,
        })
        if class == "TextButton" then f.Text = ""; f.AutoButtonColor = false end
        return f, card
    end

    -- ---------------------------------------------------------- Section / Divider / Label / Paragraph
    function Tab:Section(name)
        if type(name) == "table" then name = name.Name or name.Title or "" end
        name = tostring(name or "")
        self._hasSections = true
        local card = self:_newCard(name ~= "" and name or nil)
        card.Auto = false
        local obj = { _type = "Section" }
        function obj:Set(t) if card.Label then card.Label.Text = tostring(t) end end
        function obj:SetVisible(v) card.Frame.Visible = v ~= false end
        function obj:Destroy() card.Frame:Destroy() end
        return obj
    end

    function Tab:Divider()
        local f = self:_row(9)
        new("Frame", {
            AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.new(1, 0, 0, 1),
            BackgroundColor3 = T.Stroke, BorderSizePixel = 0, Parent = f,
        })
        return finalize(self, {}, {}, f, "Divider")
    end

    function Tab:Label(o)
        o = norm(o, {})
        local f = self:_row(18)
        f.AutomaticSize = Enum.AutomaticSize.Y
        local l = label({
            Name = "Title", Text = tostring(o.Text or o.Name or ""), FontFace = FONTS.Regular, TextSize = 12,
            TextColor3 = o.Color or T.Muted, TextWrapped = true, TextTruncate = Enum.TextTruncate.None,
            Size = UDim2.new(1, 0, 0, 18), AutomaticSize = Enum.AutomaticSize.Y, Parent = f,
        })
        local el = {}
        function el:Set(t) l.Text = tostring(t) end
        function el:Get() return l.Text end
        function el:SetColor(c) l.TextColor3 = c end
        return finalize(self, o, el, f, "Label")
    end

    function Tab:Paragraph(o)
        o = norm(o, {})
        local f = self:_row(52)
        f.Size = UDim2.new(1, 0, 0, 0)
        f.AutomaticSize = Enum.AutomaticSize.Y
        f.BackgroundColor3 = T.Surface2
        f.BackgroundTransparency = 0
        corner(f, 8)
        stroke(f, T.Stroke, 0.3)
        padding(f, 10, 10, 8, 9)
        new("UIListLayout", { Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder, Parent = f })
        local t = label({ Name = "Title", Text = tostring(o.Name or ""), FontFace = FONTS.Bold, TextSize = 13, Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 1, Parent = f })
        local c = label({
            Name = "Content", Text = tostring(o.Content or ""), FontFace = FONTS.Regular, TextSize = 12, TextColor3 = T.Muted,
            TextWrapped = true, TextTruncate = Enum.TextTruncate.None, TextYAlignment = Enum.TextYAlignment.Top,
            Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = f,
        })
        local el = {}
        function el:Set(v, b)
            if type(v) == "table" then
                if v.Title or v.Name then t.Text = tostring(v.Title or v.Name) end
                if v.Content then c.Text = tostring(v.Content) end
            elseif b ~= nil then
                t.Text = tostring(v); c.Text = tostring(b)
            else
                c.Text = tostring(v)
            end
        end
        function el:Get() return c.Text end
        return finalize(self, o, el, f, "Paragraph")
    end

    -- ---------------------------------------------------------- Button
    function Tab:Button(o)
        o = norm(o, {})
        local h = o.Desc and 44 or 32
        local f = self:_row(h, "TextButton")
        f.BackgroundColor3 = T.Accent
        f.BackgroundTransparency = 0
        corner(f, 6)
        local st = stroke(f, T.Accent)
        local inner = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = f })
        padding(inner, 12, 10, o.Desc and 4 or 0, o.Desc and 4 or 0)
        local title = titleDesc(inner, o.Name or "Button", o.Desc, 0)
        title.TextXAlignment = Enum.TextXAlignment.Center
        title.TextColor3 = T.Background
        title.FontFace = FONTS.Bold
        local arrow = label({
            Text = "›", FontFace = FONTS.Bold, TextSize = 20, TextColor3 = T.Muted, AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, 0, 0.5, -1), Size = UDim2.fromOffset(14, 22), TextXAlignment = Enum.TextXAlignment.Center,
            TextTruncate = Enum.TextTruncate.None, Visible = false, Parent = inner,
        })
        f.MouseEnter:Connect(function() tween(f, { BackgroundColor3 = T.AccentLight }, 0.12) end)
        f.MouseLeave:Connect(function() tween(f, { BackgroundColor3 = T.Accent }, 0.2) end)
        local el = {}
        f.MouseButton1Click:Connect(function()
            if el.Locked then return end
            f.BackgroundColor3 = T.AccentDark
            tween(f, { BackgroundColor3 = T.Accent }, 0.35)
            task.spawn(safeCall, o.Callback)
        end)
        function el:SetText(t) title.Text = tostring(t) end
        el.SetTitle = el.SetText
        return finalize(self, o, el, f, "Button")
    end

    -- ---------------------------------------------------------- Toggle
    function Tab:Toggle(o)
        o = norm(o, { CurrentValue = "Default", Value = "Default" })
        local h = o.Desc and 40 or 30
        local f = self:_row(h, "TextButton")
        titleDesc(f, o.Name or "Toggle", o.Desc, 50)
        local track = new("Frame", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(36, 18),
            BackgroundColor3 = T.Surface3, BorderSizePixel = 0, Parent = f,
        })
        corner(track, FULL)
        local tStroke = stroke(track, T.Stroke)
        local tGrad = gradient(track, T.AccentLight, T.AccentDark, 0)
        tGrad.Enabled = false
        local knob = new("Frame", {
            AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 3, 0.5, 0), Size = UDim2.fromOffset(12, 12),
            BackgroundColor3 = T.Muted, BorderSizePixel = 0, Parent = track,
        })
        corner(knob, FULL)
        local el = { Value = o.Default == true }
        local function render(anim)
            local on, t = el.Value, anim and 0.22 or 0
            tGrad.Enabled = on
            tGrad.Enabled = false
            tween(track, { BackgroundColor3 = on and T.AccentDark or T.Surface3 }, t)
            tween(tStroke, { Color = on and T.Accent or T.Stroke, Transparency = on and 0.35 or 0 }, t)
            tween(knob, { Position = on and UDim2.new(0, 21, 0.5, 0) or UDim2.new(0, 3, 0.5, 0), BackgroundColor3 = on and T.Accent or T.Muted }, t, Enum.EasingStyle.Back)
        end
        function el:Set(v, silent)
            v = v == true
            if v == el.Value then return end
            el.Value = v
            render(true)
            if not silent then safeCall(o.Callback, v) end
        end
        function el:Get() return el.Value end
        render(false)
        f.MouseButton1Click:Connect(function()
            if el.Locked then return end
            el:Set(not el.Value)
        end)
        local r = finalize(self, o, el, f, "Toggle")
        if el.Value then safeCall(o.Callback, true) end
        return r
    end

    -- ---------------------------------------------------------- Slider
    function Tab:Slider(o)
        o = norm(o, { CurrentValue = "Default", Value = "Default", Increment = "Step" })
        local lo = math.min(o.Min or 0, o.Max or 100)
        local hi = math.max(o.Min or 0, o.Max or 100)
        local sn = snapper(lo, hi, o.Step)
        local suffix = tostring(o.Suffix or "")
        local h = o.Desc and 54 or 40
        local f = self:_row(h)
        label({ Name = "Title", Text = tostring(o.Name or "Slider"), Position = UDim2.fromOffset(0, 2), Size = UDim2.new(1, -90, 0, 16), Parent = f })
        if o.Desc then
            label({ Name = "Desc", Text = tostring(o.Desc), FontFace = FONTS.Regular, TextSize = 11, TextColor3 = T.Muted, Position = UDim2.fromOffset(0, 19), Size = UDim2.new(1, 0, 0, 13), Parent = f })
        end
        local valBox = new("TextBox", {
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 1), Size = UDim2.fromOffset(84, 18),
            BackgroundTransparency = 1, FontFace = FONTS.Medium, TextSize = 12, TextColor3 = T.Muted,
            TextXAlignment = Enum.TextXAlignment.Right, ClearTextOnFocus = false, Text = "", Parent = f,
        })
        local trackY = o.Desc and 40 or 26
        local hit = new("TextButton", {
            Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Position = UDim2.fromOffset(0, trackY - 7),
            Size = UDim2.new(1, 0, 0, 18), Parent = f,
        })
        local track = new("Frame", {
            AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.new(1, 0, 0, 4),
            BackgroundColor3 = T.Surface3, BorderSizePixel = 0, Parent = hit,
        })
        corner(track, FULL)
        local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = WHITE, BorderSizePixel = 0, Parent = track })
        corner(fill, FULL)
        gradient(fill, T.AccentDark, T.AccentLight, 0)
        local knob = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.fromOffset(12, 12),
            BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 2, Parent = track,
        })
        corner(knob, FULL)
        stroke(knob, T.Accent, 0, 2)

        local dragging = false
        local el = { Value = sn.snap(tonumber(o.Default) or lo) }
        local function render(t)
            local p = (hi == lo) and 0 or (el.Value - lo) / (hi - lo)
            tween(fill, { Size = UDim2.fromScale(p, 1) }, t)
            tween(knob, { Position = UDim2.fromScale(p, 0.5) }, t)
            if not valBox:IsFocused() then valBox.Text = sn.format(el.Value) .. suffix end
        end
        function el:Set(v, silent)
            v = sn.snap(tonumber(v) or lo)
            if v == el.Value then return end
            el.Value = v
            render(dragging and 0.05 or 0.15)
            if not silent then safeCall(o.Callback, v) end
        end
        function el:Get() return el.Value end
        function el:SetRange(a, b)
            lo, hi = math.min(a, b), math.max(a, b)
            sn = snapper(lo, hi, o.Step)
            el.Value = sn.snap(el.Value)
            render(0.15)
        end
        local function fromX(x)
            local w = track.AbsoluteSize.X
            if w <= 0 then return end
            local p = math.clamp((x - track.AbsolutePosition.X) / w, 0, 1)
            el:Set(lo + (hi - lo) * p)
        end
        hit.InputBegan:Connect(function(i)
            if el.Locked or not isPress(i) then return end
            dragging = true
            tween(knob, { Size = UDim2.fromOffset(16, 16) }, 0.12, Enum.EasingStyle.Back)
            fromX(i.Position.X)
        end)
        listen(self.Window, el, "InputChanged", function(i)
            if dragging and isMove(i) then fromX(i.Position.X) end
        end)
        listen(self.Window, el, "InputEnded", function(i)
            if dragging and isPress(i) then
                dragging = false
                tween(knob, { Size = UDim2.fromOffset(12, 12) }, 0.18)
                safeCall(o.OnRelease, el.Value)
            end
        end)
        valBox.Focused:Connect(function() valBox.Text = sn.format(el.Value); valBox.TextColor3 = T.Text end)
        valBox.FocusLost:Connect(function()
            valBox.TextColor3 = T.Muted
            local n = tonumber((valBox.Text:gsub("[^%d%.%-]", "")))
            if n and not el.Locked then el:Set(n) end
            render(0.1)
        end)
        render(0)
        return finalize(self, o, el, f, "Slider")
    end

    -- ---------------------------------------------------------- Dropdown
    function Tab:Dropdown(o)
        o = norm(o, { CurrentOption = "Default", CurrentValue = "Default", Value = "Default", MultipleOptions = "Multi", Values = "Options" })
        local multi = o.Multi == true
        if multi and type(o.Default) ~= "table" and o.Default ~= nil then o.Default = { o.Default }
        elseif not multi and type(o.Default) == "table" then o.Default = o.Default[1] end
        local options = o.Options or {}
        local headH = o.Desc and 40 or 30
        local f = self:_row(headH)
        f.ClipsDescendants = true
        local head = new("Frame", { Size = UDim2.new(1, 0, 0, headH), BackgroundTransparency = 1, Parent = f })
        titleDesc(head, o.Name or "Dropdown", o.Desc, 8, 0.5)
        local sel = new("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0.5, 0, 0, 24),
            BackgroundColor3 = T.Surface2, Text = "", AutoButtonColor = false, Parent = head,
        })
        corner(sel, 6)
        local selStroke = stroke(sel, T.Stroke)
        local selText = label({ Text = "", TextSize = 12, Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -26, 1, 0), Parent = sel })
        local chev = label({
            Text = "›", FontFace = FONTS.Bold, TextSize = 16, TextColor3 = T.Muted, Rotation = 90,
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -6, 0.5, 0), Size = UDim2.fromOffset(12, 16),
            TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.None, Parent = sel,
        })

        local list = new("Frame", {
            Position = UDim2.fromOffset(0, headH + 4), Size = UDim2.new(1, 0, 0, 0), BackgroundColor3 = T.Surface2,
            BorderSizePixel = 0, ClipsDescendants = true, Visible = false, Parent = f,
        })
        corner(list, 7)
        stroke(list, T.Stroke)
        local search = new("TextBox", {
            Position = UDim2.fromOffset(6, 6), Size = UDim2.new(1, -12, 0, 24), BackgroundColor3 = T.Surface3,
            FontFace = FONTS.Regular, TextSize = 12, TextColor3 = T.Text, PlaceholderText = "Search...",
            PlaceholderColor3 = T.Muted, Text = "", ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left,
            Visible = false, Parent = list,
        })
        corner(search, 5)
        padding(search, 8, 8, 0, 0)
        local scroll = new("ScrollingFrame", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 2,
            ScrollBarImageColor3 = T.Accent, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = list,
        })
        padding(scroll, 4, 4, 4, 4)
        new("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder, Parent = scroll })

        local el = { Open = false }
        local selected = {}
        if multi then for _, v in ipairs(o.Default or {}) do selected[v] = true end
        elseif o.Default ~= nil then selected[o.Default] = true end
        local filter = ""
        local optBtns = {}

        local function getValue()
            if multi then
                local r = {}
                for _, v in ipairs(options) do if selected[v] then table.insert(r, v) end end
                return r
            end
            for _, v in ipairs(options) do if selected[v] then return v end end
            return nil
        end
        local function matches(v) return filter == "" or string.find(string.lower(tostring(v)), filter, 1, true) ~= nil end
        local function searchOn() return #options > 6 end
        local function listHeight()
            local n = 0
            for _, v in ipairs(options) do if matches(v) then n += 1 end end
            n = math.min(math.max(n, 1), 6)
            return (searchOn() and 30 or 0) + n * 26 + (n - 1) * 2 + 8
        end
        local function paint()
            local v = getValue()
            if multi then
                selText.Text = (#v > 0) and table.concat((function() local s = {} for _, x in ipairs(v) do table.insert(s, tostring(x)) end return s end)(), ", ") or "None"
            else
                selText.Text = v ~= nil and tostring(v) or tostring(o.Placeholder or "Select...")
            end
            selText.TextColor3 = (v ~= nil and (not multi or #v > 0)) and T.Text or (o.Placeholder and T.Text or T.Muted)
            for _, b in ipairs(optBtns) do
                local on = selected[b.Value] == true
                tween(b.Btn, { BackgroundTransparency = on and 0 or 1 }, 0.12)
                b.Text.TextColor3 = on and T.Accent or T.Text
                b.Mark.Visible = on
                b.Btn.Visible = matches(b.Value)
            end
        end
        local function layout(anim)
            local so = searchOn()
            search.Visible = so
            scroll.Position = UDim2.fromOffset(0, so and 30 or 0)
            scroll.Size = UDim2.new(1, 0, 1, so and -30 or 0)
            if el.Open then
                local lh = listHeight()
                tween(list, { Size = UDim2.new(1, 0, 0, lh) }, anim and 0.2 or 0)
                tween(f, { Size = UDim2.new(1, 0, 0, headH + lh + 6) }, anim and 0.2 or 0)
            end
        end
        local function rebuild()
            for _, b in ipairs(optBtns) do b.Btn:Destroy() end
            optBtns = {}
            for i, v in ipairs(options) do
                local b = new("TextButton", {
                    Size = UDim2.new(1, 0, 0, 26), BackgroundColor3 = T.Surface3, BackgroundTransparency = 1,
                    Text = "", AutoButtonColor = false, LayoutOrder = i, Parent = scroll,
                })
                corner(b, 5)
                local mark = new("Frame", {
                    AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 5, 0.5, 0), Size = UDim2.fromOffset(3, 12),
                    BackgroundColor3 = T.Accent, BorderSizePixel = 0, Visible = false, Parent = b,
                })
                corner(mark, FULL)
                local t = label({ Text = tostring(v), TextSize = 12, Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -18, 1, 0), Parent = b })
                b.MouseButton1Click:Connect(function()
                    if el.Locked then return end
                    if multi then
                        if selected[v] then selected[v] = nil else selected[v] = true end
                    else
                        selected = { [v] = true }
                    end
                    paint()
                    safeCall(o.Callback, getValue())
                    if not multi then el:SetOpen(false) end
                end)
                table.insert(optBtns, { Btn = b, Text = t, Mark = mark, Value = v })
            end
            paint()
        end

        function el:SetOpen(state)
            state = state == true
            el.Open = state
            if state then list.Visible = true end
            local lh = listHeight()
            tween(list, { Size = UDim2.new(1, 0, 0, state and lh or 0) }, 0.2)
            tween(f, { Size = UDim2.new(1, 0, 0, headH + (state and (lh + 6) or 0)) }, 0.2)
            tween(chev, { Rotation = state and 270 or 90 }, 0.2)
            selStroke.Color = state and T.Accent or T.Stroke
            if not state then task.delay(0.21, function() if not el.Open then list.Visible = false end end) end
        end
        function el:Set(v, silent)
            selected = {}
            if multi then
                for _, x in ipairs(type(v) == "table" and v or { v }) do selected[x] = true end
            elseif type(v) == "table" then
                if v[1] ~= nil then selected[v[1]] = true end
            elseif v ~= nil then
                selected[v] = true
            end
            paint()
            if not silent then safeCall(o.Callback, getValue()) end
        end
        function el:Get() return getValue() end
        function el:Refresh(newOptions, keep)
            options = newOptions or {}
            if not keep then selected = {} end
            rebuild()
            layout(true)
        end
        sel.MouseButton1Click:Connect(function()
            if el.Locked then return end
            el:SetOpen(not el.Open)
        end)
        sel.MouseEnter:Connect(function() if not el.Open then tween(selStroke, { Color = T.StrokeHover }, 0.12) end end)
        sel.MouseLeave:Connect(function() if not el.Open then tween(selStroke, { Color = T.Stroke }, 0.2) end end)
        search:GetPropertyChangedSignal("Text"):Connect(function()
            filter = string.lower(search.Text)
            paint()
            layout(true)
        end)
        rebuild()
        layout(false)
        return finalize(self, o, el, f, "Dropdown")
    end

    -- ---------------------------------------------------------- Input
    function Tab:Input(o)
        o = norm(o, { PlaceholderText = "Placeholder", CurrentValue = "Default", Value = "Default" })
        local stacked = o.Stacked == true
        local h = stacked and 58 or (o.Desc and 40 or 30)
        local f = self:_row(h)
        if stacked then
            label({ Name = "Title", Text = tostring(o.Name or "Input"), Size = UDim2.new(1, 0, 0, 16), Position = UDim2.fromOffset(0, 2), Parent = f })
        else
            titleDesc(f, o.Name or "Input", o.Desc, 8, 0.5)
        end
        local boxFrame = new("Frame", {
            AnchorPoint = stacked and Vector2.new(0, 1) or Vector2.new(1, 0.5),
            Position = stacked and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 0.5, 0),
            Size = stacked and UDim2.new(1, 0, 0, 30) or UDim2.new(0.5, 0, 0, 24),
            BackgroundColor3 = T.Surface2, BorderSizePixel = 0, ClipsDescendants = true, Parent = f,
        })
        corner(boxFrame, 6)
        local st = stroke(boxFrame, T.Stroke)
        local box = new("TextBox", {
            Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -16, 1, 0), BackgroundTransparency = 1,
            Text = o.Default ~= nil and tostring(o.Default) or "", PlaceholderText = tostring(o.Placeholder or ""),
            PlaceholderColor3 = T.Muted, TextColor3 = T.Text, FontFace = FONTS.Medium, TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, Parent = boxFrame,
        })
        local el = {}
        box.Focused:Connect(function() tween(st, { Color = T.Accent }, 0.15) end)
        box.FocusLost:Connect(function(enter)
            tween(st, { Color = T.Stroke }, 0.15)
            if el.Locked then return end
            if o.Numeric and box.Text ~= "" and not tonumber(box.Text) then box.Text = ""; return end
            local txt = box.Text
            safeCall(o.Callback, txt, enter)
            if o.RemoveTextAfterFocusLost then box.Text = "" end
        end)
        function el:Set(v, silent)
            box.Text = v ~= nil and tostring(v) or ""
            if not silent then safeCall(o.Callback, box.Text, false) end
        end
        function el:Get() return box.Text end
        function el:SetPlaceholder(t) box.PlaceholderText = tostring(t) end
        return finalize(self, o, el, f, "Input")
    end

    -- ---------------------------------------------------------- ButtonRow (several buttons side by side)
    -- o.Buttons = { { Name = "...", Callback = fn, Primary = true, Weight = 2.6 }, ... }
    function Tab:ButtonRow(o)
        o = norm(o, {})
        local f = self:_row(32)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8),
            SortOrder = Enum.SortOrder.LayoutOrder, Parent = f,
        })
        local list, total, gaps = o.Buttons or {}, 0, 8 * math.max(#(o.Buttons or {}) - 1, 0)
        for _, b in ipairs(list) do total += (b.Weight or 1) end
        local el = { Buttons = {} }
        for i, b in ipairs(list) do
            local primary = b.Primary == true
            local btn = new("TextButton", {
                Size = UDim2.new((b.Weight or 1) / math.max(total, 1), -gaps * (b.Weight or 1) / math.max(total, 1), 1, 0),
                BackgroundColor3 = primary and T.Accent or T.Surface2, Text = "", AutoButtonColor = false,
                BorderSizePixel = 0, LayoutOrder = i, Parent = f,
            })
            corner(btn, 6)
            stroke(btn, primary and T.Accent or T.Stroke)
            local t = label({
                Text = tostring(b.Name or "Button"), FontFace = primary and FONTS.Bold or FONTS.Medium, TextSize = 12,
                TextColor3 = primary and T.Background or T.Text, TextXAlignment = Enum.TextXAlignment.Center,
                Size = UDim2.fromScale(1, 1), Parent = btn,
            })
            local base = primary and T.Accent or T.Surface2
            local hover = primary and T.AccentLight or T.Surface3
            btn.MouseEnter:Connect(function() tween(btn, { BackgroundColor3 = hover }, 0.12) end)
            btn.MouseLeave:Connect(function() tween(btn, { BackgroundColor3 = base }, 0.2) end)
            btn.MouseButton1Click:Connect(function()
                if el.Locked then return end
                btn.BackgroundColor3 = primary and T.AccentDark or T.Surface3
                tween(btn, { BackgroundColor3 = base }, 0.35)
                task.spawn(safeCall, b.Callback)
            end)
            el.Buttons[i] = t
        end
        return finalize(self, o, el, f, "ButtonRow")
    end

    -- ---------------------------------------------------------- Keybind
    function Tab:Keybind(o)
        o = norm(o, { CurrentKeybind = "Default", CurrentValue = "Default", Value = "Default" })
        o.Default = toKey(o.Default)
        local hold = o.Mode == "Hold"
        local h = o.Desc and 40 or 30
        local f = self:_row(h)
        titleDesc(f, o.Name or "Keybind", o.Desc, 80)
        local chip = new("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(0, 22),
            AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = T.Surface2, Text = "", AutoButtonColor = false, Parent = f,
        })
        corner(chip, 6)
        local st = stroke(chip, T.Stroke)
        padding(chip, 9, 9, 0, 0)
        local ct = label({
            Size = UDim2.fromOffset(0, 22), AutomaticSize = Enum.AutomaticSize.X, TextSize = 11, FontFace = FONTS.Bold,
            TextColor3 = T.Muted, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.None, Parent = chip,
        })
        local el = { Value = o.Default, Listening = false, Held = false }
        local win = self.Window
        local function render()
            ct.Text = el.Listening and "..." or keyName(el.Value)
            st.Color = el.Listening and T.Accent or T.Stroke
            ct.TextColor3 = el.Listening and T.Accent or T.Muted
        end
        local function release()
            if el.Held then el.Held = false; safeCall(o.Callback, false) end
        end
        function el:Set(k, silent)
            release()
            k = toKey(k)
            el.Value = k
            el.Listening = false
            render()
            if not silent then safeCall(o.OnChanged, k) end
        end
        function el:Get() return el.Value end
        chip.MouseButton1Click:Connect(function()
            if el.Locked then return end
            el.Listening = not el.Listening
            render()
        end)
        listen(win, el, "InputBegan", function(i, gp)
            if not isBindInput(i) then return end
            if el.Listening then
                if UIS:GetFocusedTextBox() then el.Listening = false; render(); return end
                win._consumedKey, win._consumedAt = i.KeyCode, os.clock()
                if i.KeyCode == Enum.KeyCode.Escape then
                    el.Listening = false; render()
                elseif i.KeyCode == Enum.KeyCode.Backspace or i.KeyCode == Enum.KeyCode.Delete then
                    el:Set(nil)
                else
                    el:Set(i.KeyCode)
                end
                return
            end
            if gp or el.Locked or el.Value == nil or i.KeyCode ~= el.Value then return end
            if hold then
                el.Held = true
                safeCall(o.Callback, true)
            else
                safeCall(o.Callback, i.KeyCode)
            end
        end)
        if hold then
            listen(win, el, "InputEnded", function(i)
                if i.KeyCode == el.Value then release() end
            end)
        end
        render()
        return finalize(self, o, el, f, "Keybind", "OnChanged")
    end

    -- ---------------------------------------------------------- ColorPicker
    function Tab:ColorPicker(o)
        o = norm(o, { Color = "Default", CurrentValue = "Default", Value = "Default" })
        local col = typeof(o.Default) == "Color3" and o.Default or WHITE
        local headH = o.Desc and 40 or 30
        local f = self:_row(headH)
        f.ClipsDescendants = true
        local head = new("Frame", { Size = UDim2.new(1, 0, 0, headH), BackgroundTransparency = 1, Parent = f })
        titleDesc(head, o.Name or "Color", o.Desc, 56)
        local sw = new("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(40, 20),
            BackgroundColor3 = col, Text = "", AutoButtonColor = false, Parent = head,
        })
        corner(sw, 5)
        local swStroke = stroke(sw, T.Stroke)

        local PANEL_H = 104
        local panel = new("Frame", {
            Position = UDim2.fromOffset(0, headH + 4), Size = UDim2.new(1, 0, 0, PANEL_H), BackgroundColor3 = T.Surface2,
            BorderSizePixel = 0, Visible = false, Parent = f,
        })
        corner(panel, 7)
        stroke(panel, T.Stroke)
        padding(panel, 10, 10, 10, 10)

        local hue, sat, val = col:ToHSV()
        local el = { Value = col, Open = false }
        local channels = {}
        local hexLbl

        local function render()
            sw.BackgroundColor3 = el.Value
            channels.H.Grad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)), ColorSequenceKeypoint.new(0.17, Color3.fromHSV(0.17, 1, 1)),
                ColorSequenceKeypoint.new(0.33, Color3.fromHSV(0.33, 1, 1)), ColorSequenceKeypoint.new(0.5, Color3.fromHSV(0.5, 1, 1)),
                ColorSequenceKeypoint.new(0.67, Color3.fromHSV(0.67, 1, 1)), ColorSequenceKeypoint.new(0.83, Color3.fromHSV(0.83, 1, 1)),
                ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
            })
            channels.S.Grad.Color = ColorSequence.new(Color3.fromHSV(hue, 0, val), Color3.fromHSV(hue, 1, val))
            channels.V.Grad.Color = ColorSequence.new(Color3.new(0, 0, 0), Color3.fromHSV(hue, sat, 1))
            channels.H.Knob.Position = UDim2.fromScale(hue, 0.5)
            channels.S.Knob.Position = UDim2.fromScale(sat, 0.5)
            channels.V.Knob.Position = UDim2.fromScale(val, 0.5)
            hexLbl.Text = "#" .. string.upper(el.Value:ToHex())
        end
        local function commit()
            el.Value = Color3.fromHSV(hue, sat, val)
            render()
            safeCall(o.Callback, el.Value)
        end
        local order = { "H", "S", "V" }
        for idx, key in ipairs(order) do
            local y = (idx - 1) * 22
            label({ Text = key, FontFace = FONTS.Bold, TextSize = 11, TextColor3 = T.Muted, Position = UDim2.fromOffset(0, y), Size = UDim2.fromOffset(14, 14), Parent = panel })
            local hitBtn = new("TextButton", {
                Position = UDim2.fromOffset(20, y - 2), Size = UDim2.new(1, -20, 0, 18), BackgroundTransparency = 1,
                Text = "", AutoButtonColor = false, Parent = panel,
            })
            local bar = new("Frame", {
                AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.new(1, 0, 0, 8),
                BackgroundColor3 = WHITE, BorderSizePixel = 0, Parent = hitBtn,
            })
            corner(bar, FULL)
            local grad = new("UIGradient", { Parent = bar })
            local knob = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.fromOffset(12, 12),
                BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 2, Parent = bar,
            })
            corner(knob, FULL)
            stroke(knob, T.Background, 0, 2)
            channels[key] = { Grad = grad, Knob = knob, Bar = bar }
            local dragging = false
            local function fromX(x)
                local w = bar.AbsoluteSize.X
                if w <= 0 then return end
                local p = math.clamp((x - bar.AbsolutePosition.X) / w, 0, 1)
                if key == "H" then hue = math.min(p, 0.999) elseif key == "S" then sat = p else val = p end
                commit()
            end
            hitBtn.InputBegan:Connect(function(i)
                if el.Locked or not isPress(i) then return end
                dragging = true
                fromX(i.Position.X)
            end)
            listen(self.Window, el, "InputChanged", function(i) if dragging and isMove(i) then fromX(i.Position.X) end end)
            listen(self.Window, el, "InputEnded", function(i) if dragging and isPress(i) then dragging = false end end)
        end
        hexLbl = label({ Text = "", FontFace = FONTS.Medium, TextSize = 11, TextColor3 = T.Muted, Position = UDim2.fromOffset(0, 68), Size = UDim2.new(1, 0, 0, 14), Parent = panel })
        render()

        function el:SetOpen(state)
            state = state == true
            el.Open = state
            if state then panel.Visible = true end
            tween(f, { Size = UDim2.new(1, 0, 0, headH + (state and (PANEL_H + 6) or 0)) }, 0.2)
            swStroke.Color = state and T.Accent or T.Stroke
            if not state then task.delay(0.21, function() if not el.Open then panel.Visible = false end end) end
        end
        function el:Set(c, silent)
            if typeof(c) ~= "Color3" then return end
            hue, sat, val = c:ToHSV()
            el.Value = c
            render()
            if not silent then safeCall(o.Callback, c) end
        end
        function el:Get() return el.Value end
        sw.MouseButton1Click:Connect(function()
            if el.Locked then return end
            el:SetOpen(not el.Open)
        end)
        return finalize(self, o, el, f, "ColorPicker")
    end

    -- Every element can be created as Tab:Toggle(...) or Tab:CreateToggle(...)
    for k, v in pairs(table.clone(Tab)) do
        if type(v) == "function" and k:sub(1, 1) ~= "_" and k:sub(1, 6) ~= "Create" and k ~= "Select" then
            Tab["Create" .. k] = v
        end
    end

    return Lib
end)()

