    local function Notify(title, content, duration)
        pcall(function() Window:Notify({ title = title, content = content, duration = duration or 4 }) end)
    end

    -- // Ping tracking (makes the Release Point mean the real meter fill on every server)
    -- The server starts counting the shot before our meter does and only sees our release one trip
    -- later, so a release fired at "X% on screen" lands at X% + (ping x meter speed) on the server.
    -- Firing earlier by the round-trip ping makes 90% really 90% and 100% really 100%, on any ping.
    local Stats = game:GetService("Stats")
    local Ping  = 0

    local function ReadPing()
        local ok, v = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
        return ok and tonumber(v) or nil
    end

    local function CompSeconds()
        local c = Aural.Shooting.PingOffset / 1000
        if Aural.Shooting.PingComp and Ping > 0 then
            c += (Ping / 1000) * Aural.Shooting.LatencyMult
        end
        return math.clamp(c, -0.1, 0.35)
    end

    -- // Hip Height (same idea as the Hoopz HipHeight changer)
    -- Practical Basketball moves you with a custom character, so the value is applied to every
    -- Humanoid that belongs to you (your Character, the one in workspace.Characters, the proxy).
    local HipDefaults = setmetatable({}, { __mode = "k" })
    local function HipHumanoids()
        local list = {}
        local function add(model)
            local hum = model and model:FindFirstChildWhichIsA("Humanoid")
            if hum then table.insert(list, hum) end
        end
        add(LocalPlayer.Character)
        add(GetCharacter())
        add(workspace:FindFirstChild("ProxyCharacter"))
        return list
    end
    local function RestoreHip()
        for hum, def in pairs(HipDefaults) do
            if hum.Parent then pcall(function() hum.HipHeight = def end) end
        end
        table.clear(HipDefaults)
    end
    Connect(RunService.Heartbeat, function()
        if not Aural.Player.HipHeight then return end
        for _, hum in ipairs(HipHumanoids()) do
            if HipDefaults[hum] == nil then HipDefaults[hum] = hum.HipHeight end
            if hum.HipHeight ~= Aural.Player.HipHeightValue then
                hum.HipHeight = Aural.Player.HipHeightValue
            end
        end
    end)

