    autoBoost = AutomaticsTab:CreateToggle({
    Name = 'Auto Boost',
    Default = false,
    Tip = 'Automatically assists aerial movement near incoming footballs.',
})

targetClosestPlayer = AutomaticsTab:CreateToggle({
    Name = 'Target Player Closer To The Ball',
    Default = false,
    Tip = 'Prioritizes players closest to the football.',
})

boostStrength = AutomaticsTab:CreateSlider({
    Name = 'Boost Strength',
    Min = 0,
    Max = 3,
    Default = 1.5,
    Increment = 0.1,
    Suffix = '',
    Tip = 'Adjusts the strength of the boost effect.',
})

boostRadius = AutomaticsTab:CreateSlider({
    Name = 'Boost Radius',
    Min = 0,
    Max = 15,
    Default = 0,
    Increment = 0.1,
    Suffix = '',
    Tip = 'Sets the activation distance for boosting.',
})

boostPower = AutomaticsTab:CreateSlider({
    Name = 'Boost Power',
    Min = 50,
    Max = 70,
    Default = 50,
    Increment = 0.1,
    Suffix = '',
    Tip = 'Controls the upward force applied during a boost.',
})

task.spawn(function()
    local activeTween

    while true do
        task.wait()

        if not autoBoost.Value then
            if activeTween then
                activeTween:Cancel()
                activeTween = nil
            end

            continue
        end

        local char = player.Character
        if not char then continue end

        local hum = char:FindFirstChildOfClass('Humanoid')
        if not hum then continue end

        local hrp = char:FindFirstChild('HumanoidRootPart')
        if not hrp then continue end

        if hum:GetState() == Enum.HumanoidStateType.Landed then
            if activeTween then
                activeTween:Cancel()
                activeTween = nil
            end

            continue
        end

        local myHead = char:FindFirstChild('Head')
        if not myHead then continue end

        local targetPlayer

        if targetClosestPlayer.Value then
            local nearestBall
            local nearestBallDist = math.huge

            for _, ball in next, workspace:GetChildren() do
                if not ball:IsA('BasePart') then continue end
                if not ball.Name:lower():find('ball') then continue end

                local dist = (ball.Position - myHead.Position).Magnitude

                if dist < nearestBallDist then
                    nearestBallDist = dist
                    nearestBall = ball
                end
            end

            if not nearestBall then continue end

            local closestDist = math.huge

            for _, v in next, players:GetPlayers() do
                if v == player then continue end

                local character = v.Character
                if not character then continue end

                local head = character:FindFirstChild('Head')
                if not head then continue end

                local dist = (head.Position - nearestBall.Position).Magnitude

                if dist < closestDist then
                    closestDist = dist
                    targetPlayer = v
                end
            end
        else
            local closestDist = math.huge

            for _, v in next, players:GetPlayers() do
                if v == player then continue end

                local character = v.Character
                if not character then continue end

                local head = character:FindFirstChild('Head')
                if not head then continue end

                local dist = (head.Position - myHead.Position).Magnitude

                if dist < closestDist then
                    closestDist = dist
                    targetPlayer = v
                end
            end
        end

        if not targetPlayer then continue end

        local character = targetPlayer.Character
        if not character then continue end

        local head = character:FindFirstChild('Head')
        if not head then continue end

        local targetHumanoid = character:FindFirstChildOfClass('Humanoid')
        if not targetHumanoid then continue end

        local myState = hum:GetState()
        local targetState = targetHumanoid:GetState()

        local distance = (head.Position - myHead.Position).Magnitude

        if distance > boostRadius.Value then
            continue
        end

        if myState ~= Enum.HumanoidStateType.Jumping
            and myState ~= Enum.HumanoidStateType.Freefall then
            continue
        end

        if targetState ~= Enum.HumanoidStateType.Jumping
            and targetState ~= Enum.HumanoidStateType.Freefall then
            continue
        end

        local speed = math.max(hum.WalkSpeed * boostStrength.Value, 1)
        local targetPos = head.Position

        local duration = math.max((hrp.Position - targetPos).Magnitude / speed, 0.01)

        if activeTween then
            activeTween:Cancel()
        end

        activeTween = tweenService:Create(
            hrp,
            TweenInfo.new(duration, Enum.EasingStyle.Linear),
            {
                CFrame = CFrame.new(targetPos)
            }
        )

        activeTween:Play()

        activeTween.Completed:Once(function(state)
            if state ~= Enum.PlaybackState.Completed then
                return
            end

            hrp.AssemblyLinearVelocity = Vector3.new(
                hrp.AssemblyLinearVelocity.X,
                boostPower.Value,
                hrp.AssemblyLinearVelocity.Z
            )
        end)
    end
end)

local MiscTab = Window:CreateTab({ Name = 'Misc', Icon = 'rbxassetid://129082556946713' })

-- ---------------------------------------------------------------
-- DOMED (remake of Football Fusion 3): checks which FF3 hooks exist
-- in this game and offers a scan report so the rest can be tuned.
-- ---------------------------------------------------------------
if ffIsDomed then
    local function domedMissing()
        local RS = game:GetService('ReplicatedStorage')
        local missing = {}
        local remotes = RS:FindFirstChild('Remotes')
        if not (remotes and remotes:FindFirstChild('CharacterSoundEvent')) then missing[#missing + 1] = 'Remotes.CharacterSoundEvent' end
        local flags = RS:FindFirstChild('Flags')
        for _, n in ipairs({ 'PossessionTag', 'Status', 'StatusTag' }) do
            if not (flags and flags:FindFirstChild(n)) then missing[#missing + 1] = 'Flags.' .. n end
        end
        local anims = RS:FindFirstChild('Animations')
        if not (anims and anims:FindFirstChild('Throw')) then missing[#missing + 1] = 'Animations.Throw' end
        if not workspace:FindFirstChild('Models') then missing[#missing + 1] = 'workspace.Models' end
        return missing
    end

    task.spawn(function()
        task.wait(4)
        local ok, missing = pcall(domedMissing)
        if not ok then return end
        if #missing == 0 then
            pcall(function() RealWindow:Notify({ title = 'Domed', content = 'All FF3 game hooks were found.', duration = 5 }) end)
        else
            pcall(function()
                RealWindow:Notify({
                    title = 'Domed', duration = 9,
                    content = 'Not found in this game: ' .. table.concat(missing, ', ') .. '. Features that use them may not work - use Misc > Domed scan.',
                })
            end)
        end
    end)

    local function domedReport()
        local out = {}
        local function add(s) out[#out + 1] = s end
        local function val(c) local ok, v = pcall(function() return c.Value end); return ok and tostring(v) or '?' end
        add('== Domed scan ==  PlaceId ' .. tostring(game.PlaceId) .. '  GameId ' .. tostring(game.GameId))

        local function tree(inst, depth, maxDepth, indent, budget)
            for _, c in ipairs(inst:GetChildren()) do
                if budget.n <= 0 then return end
                budget.n = budget.n - 1
                local extra = c:IsA('ValueBase') and (' = ' .. val(c)) or ''
                add(indent .. c.Name .. ' [' .. c.ClassName .. ']' .. extra)
                if depth < maxDepth then tree(c, depth + 1, maxDepth, indent .. '  ', budget) end
            end
        end

        local RS = game:GetService('ReplicatedStorage')
        add('\n-- ReplicatedStorage (depth 3)')
        pcall(tree, RS, 1, 3, '  ', { n = 300 })

        add('\n-- Remotes in ReplicatedStorage')
        pcall(function()
            local n = 0
            for _, d in ipairs(RS:GetDescendants()) do
                if d:IsA('RemoteEvent') or d:IsA('RemoteFunction') or d:IsA('UnreliableRemoteEvent') then
                    n = n + 1; if n > 150 then break end
                    add('  ' .. d:GetFullName() .. ' [' .. d.ClassName .. ']')
                end
            end
        end)

        add('\n-- workspace children')
        pcall(tree, workspace, 1, 1, '  ', { n = 80 })

        add('\n-- ball candidates (names containing "ball")')
        pcall(function()
            local n = 0
            for _, d in ipairs(workspace:GetDescendants()) do
                if d.Name:lower():find('ball', 1, true) then
                    n = n + 1; if n > 20 then break end
                    add('  ' .. d:GetFullName() .. ' [' .. d.ClassName .. ']')
                end
            end
        end)

        add('\n-- your character')
        pcall(function() tree(game:GetService('Players').LocalPlayer.Character, 1, 1, '  ', { n = 60 }) end)
        add('\n-- PlayerGui')
        pcall(function() tree(game:GetService('Players').LocalPlayer.PlayerGui, 1, 2, '  ', { n = 80 }) end)

        add('\n-- FF3 hooks')
        local okm, missing = pcall(domedMissing)
        add('  missing: ' .. ((okm and #missing > 0) and table.concat(missing, ', ') or 'none'))
        return table.concat(out, '\n'), #out
    end

    MiscTab:CreateButton({
        Name = 'Domed scan (copy report)',
        Tip = 'Copies a list of Domed remotes, flags and ball objects to your clipboard (and saves RiftWtf/domed_scan.txt).',
        Callback = function()
            local ok, text, lines = pcall(domedReport)
            if not ok then
                pcall(function() RealWindow:Notify({ title = 'Domed', content = 'Scan failed: ' .. tostring(text), duration = 5 }) end)
                return
            end
            local copied = false
            if type(setclipboard) == 'function' then copied = pcall(setclipboard, text) end
            if type(writefile) == 'function' then
                pcall(function() if type(makefolder) == 'function' then makefolder('RiftWtf') end end)
                pcall(writefile, 'RiftWtf/domed_scan.txt', text)
            end
            pcall(function()
                RealWindow:Notify({
                    title = 'Domed', duration = 6,
                    content = (copied and 'Report copied' or 'Report built') .. ' (' .. tostring(lines) .. ' lines).' .. (copied and ' Paste it to finish tuning Domed.' or ' Saved to RiftWtf/domed_scan.txt.'),
                })
            end)
        end,
    })
end


