-- Services
HttpService = game:GetService("HttpService")
local UserInputService = game:GetService("UserInputService")

AutoLoadConfig = "default"
AutoLoadEnabled = false
AutoSaveEnabled = false
ConfigListDropdown = nil
AutoSaveConnection = nil

function FileExists(path)
    if isfile then
        return pcall(readfile, path)
    end
    return false
end

function WriteFile(path, content)
    if writefile then
        return pcall(writefile, path, content)
    end
    return false
end

function ReadFile(path)
    if readfile then
        local success, content = pcall(readfile, path)
        if success then
            return content
        end
    end
    return ""
end

function loadAutoLoadSettings()
    local autoLoadFile = "RiftWtf/AutoLoad/Game/Murder-Mystery-2(Normal-Mode)/AutoLoad.json"
    
    if FileExists(autoLoadFile) then
        local content = ReadFile(autoLoadFile)
        
        if content ~= "" then
            local success, data = pcall(function()
                return HttpService:JSONDecode(content)
            end)
            
            if success and data then
                AutoLoadConfig = data.configName or "default"
                AutoLoadEnabled = data.enabled or false
                return true
            end
        end
    end
    
    AutoLoadConfig = "default"
    AutoLoadEnabled = false
    return false
end

function saveAutoLoadSettings()
    local autoLoadFile = "RiftWtf/AutoLoad/Game/Murder-Mystery-2(Normal-Mode)/AutoLoad.json"
    
    local success = WriteFile(autoLoadFile, "")
    if not success then
        if makefolder then
            pcall(function() makefolder("RiftWtf") end)
            pcall(function() makefolder("RiftWtf/AutoLoad") end)
            pcall(function() makefolder("RiftWtf/AutoLoad/Game") end)
            pcall(function() makefolder("RiftWtf/AutoLoad/Game/Murder-Mystery-2(Normal-Mode)") end)
        end
    end
    
    local data = {
        enabled = AutoLoadEnabled,
        configName = AutoLoadConfig
    }
    
    local success, json = pcall(function()
        return HttpService:JSONEncode(data)
    end)
    
    if success then
        WriteFile(autoLoadFile, json)
    end
end

