    for _, data in ipairs(Spooky.ToggleCopies[name] or {}) do
    if data.btn and data.btn.Parent then
        TweenService:Create(data.btn, TweenInfo.new(0.18), {
            BackgroundColor3 = active and Color3.fromRGB(65, 43, 100) or Color3.fromRGB(41, 41, 41)
        }):Play()
        if data.txtLbl then
            TweenService:Create(data.txtLbl, TweenInfo.new(0.18), {
                TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(200, 200, 215)
            }):Play()
        end
        if data.spookyIcon then
            TweenService:Create(data.spookyIcon, TweenInfo.new(0.18), {
                ImageColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(140, 140, 160)
            }):Play()
        end
        if data.iconStk then
            TweenService:Create(data.iconStk, TweenInfo.new(0.18), {
                Color = active and Color3.fromRGB(240, 240, 255) or Color3.fromRGB(44, 44, 44)
            }):Play()
        end
        local curAccent = _G.CurrentAccentColor or (_G.SpookyThemeAccents and CurrentTheme and _G.SpookyThemeAccents[CurrentTheme] and _G.SpookyThemeAccents[CurrentTheme].accent) or Color3.fromRGB(110, 180, 255)
        if data.btnStk then
            TweenService:Create(data.btnStk, TweenInfo.new(0.18), {
                Color = active and curAccent or Color3.fromRGB(30, 30, 30)
            }):Play()
        end
        if data.switchPill then
            TweenService:Create(data.switchPill, TweenInfo.new(0.18), {
