    aStk.Color = Color3.fromRGB(39, 39, 39)
    aStk.Thickness = 1

    local txtLbl = Instance.new("TextLabel", btn)
    txtLbl.Size = UDim2.new(1, -10, 1, 0)
    txtLbl.Position = UDim2.new(0, 5, 0, 0)
    txtLbl.BackgroundTransparency = 1
    txtLbl.Font = Enum.Font.GothamBold
    txtLbl.Text = translateTerm and translateTerm(textEN, textES, CurrentLang) or ((CurrentLang == "EN") and textEN or textES)
    txtLbl.TextSize = 11.5
    txtLbl.TextColor3 = Color3.fromRGB(235, 235, 245)
    txtLbl.TextXAlignment = Enum.TextXAlignment.Center
    txtLbl.ZIndex = 3
    txtLbl.Active = false

    local isClearingBtnText = false
    btn:GetPropertyChangedSignal("Text"):Connect(function()
        if isClearingBtnText then return end
        if btn.Text ~= "" then
            isClearingBtnText = true
            txtLbl.Text = btn.Text
            btn.Text = ""
            isClearingBtnText = false
        end
    end)

    btn.MouseEnter:Connect(function()
        local curAccent = _G.CurrentAccentColor or Color3.fromRGB(110, 180, 255)
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(23, 23, 23) }):Play()
        TweenService:Create(aStk, TweenInfo.new(0.12), { Color = curAccent }):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(18, 18, 18) }):Play()
        TweenService:Create(aStk, TweenInfo.new(0.12), { Color = Color3.fromRGB(39, 39, 39) }):Play()
    end)
    if onClick then
        local lastActionClick = 0
        local function onActionActivated()
            local now = os.clock()
            if now - lastActionClick < 0.12 then return end
            lastActionClick = now
            onClick()
        end
        Spooky.RegisterControl(btn,nil,textEN,textES,onActionActivated)
        btn.Activated:Connect(onActionActivated)
    end
    table.insert(TranslatableUI, {
        txtLbl = txtLbl,
        btn = btn,
        en = textEN,
        es = textES
    })
    table.insert(AllUIButtons, btn)
    return btn
end

local function createSlider(parent, textEN, textES, minV, maxV, defV, isFloat, step, suffix, callback, pos)
    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(1, -12, 0, 38)
    frame.Position = pos or UDim2.new(0, 6, 0, 26)
    frame.BackgroundTransparency = 1
    frame.Parent = parent

    local titleLbl = Instance.new("TextLabel", frame)
    titleLbl.Size = UDim2.new(0.65, 0, 0, 16)
    titleLbl.Position = UDim2.new(0, 4, 0, 0)
    titleLbl.BackgroundTransparency = 1
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.Text = translateTerm and translateTerm(textEN, textES, CurrentLang) or ((CurrentLang == "EN") and textEN or textES)
    titleLbl.TextSize = 11
    titleLbl.TextColor3 = Color3.fromRGB(210, 210, 225)
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left

    local sfx = suffix or ""
    local valLbl = Instance.new("TextLabel", frame)
    valLbl.Size = UDim2.new(0.35, -4, 0, 16)
    valLbl.Position = UDim2.new(0.65, 0, 0, 0)
    valLbl.BackgroundTransparency = 1
    valLbl.Font = Enum.Font.GothamBold
    valLbl.Text = isFloat and string.format("%.2f%s", defV, sfx) or string.format("%d%s", math.floor(defV), sfx)
    valLbl.TextSize = 11
    valLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    valLbl.TextXAlignment = Enum.TextXAlignment.Right

    local track = Instance.new("Frame", frame)
    track.Size = UDim2.new(1, -8, 0, 6)
    track.Position = UDim2.new(0, 4, 0, 24)
    track.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
    track.BorderSizePixel = 0
    Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)
    local trStk = Instance.new("UIStroke", track)
    trStk.Color = Color3.fromRGB(37, 37, 37)
    trStk.Thickness = 1

    local fill = Instance.new("Frame", track)
    local curPct = math.clamp((defV - minV) / (maxV - minV), 0, 1)
    fill.Size = UDim2.new(curPct, 0, 1, 0)
    fill.BackgroundColor3 = Color3.fromRGB(195, 205, 230)
    fill.BorderSizePixel = 0
    Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)

    local knob = Instance.new("ImageButton", track)
    knob.Size = UDim2.new(0, 18, 0, 18)
    knob.Position = UDim2.new(curPct, -9, 0.5, -9)
    knob.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
    knob.Image = "rbxassetid://76495748586157"
    knob.BorderSizePixel = 0
    knob.ZIndex = 5
    Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
    local knStk = Instance.new("UIStroke", knob)
    knStk.Color = Color3.fromRGB(240, 240, 255)
    knStk.Thickness = 1.5

    local isDragging = false
    local function updateValue(inputX)
        local absPos = track.AbsolutePosition.X
        local absSize = track.AbsoluteSize.X
        if absSize <= 0 then return end
        local pct = math.clamp((inputX - absPos) / absSize, 0, 1)
        local rawVal = minV + pct * (maxV - minV)
        if step and step > 0 then
            rawVal = math.floor(rawVal / step + 0.5) * step
        end
        rawVal = math.clamp(rawVal, minV, maxV)
        pct = (rawVal - minV) / (maxV - minV)
        fill.Size = UDim2.new(pct, 0, 1, 0)
        knob.Position = UDim2.new(pct, -9, 0.5, -9)
        valLbl.Text = isFloat and string.format("%.2f%s", rawVal, sfx) or string.format("%d%s", math.floor(rawVal), sfx)
        if callback then callback(rawVal) end
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isDragging = true
            updateValue(input.Position.X)
        end
    end)
    track.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isDragging = true
            updateValue(input.Position.X)
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if isDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            updateValue(input.Position.X)
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isDragging = false
        end
    end)

    table.insert(TranslatableUI, {
        label = titleLbl,
        en = textEN,
        es = textES
    })
    return frame
end
local function createCycleButton(parent, prefixEN, prefixES, choices, defaultIdx, size, pos, onChange)
    local currentIdx = defaultIdx or 1
    local btn = Instance.new("TextButton")
    btn.Size = size
    btn.Position = pos
    btn.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
    btn.Font = Enum.Font.GothamBold
    local pre = translateTerm and translateTerm(prefixEN, prefixES, CurrentLang) or ((CurrentLang == "EN") and prefixEN or prefixES)
    btn.Text = ""
    btn.AutoButtonColor = true
    btn.Parent = parent
    btn.ClipsDescendants = true
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 7)
    local cStk = Instance.new("UIStroke", btn)
    cStk.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    cStk.Color = Color3.fromRGB(37, 37, 37)
    cStk.Thickness = 1

    local txtLbl = Instance.new("TextLabel", btn)
    txtLbl.Name = "CycleText"
    txtLbl.Size = UDim2.new(1, -26, 1, 0)
    txtLbl.Position = UDim2.new(0, 8, 0, 0)
    txtLbl.BackgroundTransparency = 1
    txtLbl.Font = Enum.Font.GothamBold
    txtLbl.Text = string.format("%s: %s", pre, tostring(choices[currentIdx]))
    txtLbl.TextSize = 11
    txtLbl.TextColor3 = Color3.fromRGB(225, 225, 240)
    txtLbl.TextXAlignment = Enum.TextXAlignment.Left
    txtLbl.TextTruncate = Enum.TextTruncate.AtEnd
    txtLbl.ZIndex = 3

    local arrowLbl = Instance.new("TextLabel", btn)
    arrowLbl.Name = "ArrowIndicator"
    arrowLbl.Size = UDim2.new(0, 16, 1, 0)
    arrowLbl.Position = UDim2.new(1, -18, 0, 0)
    arrowLbl.BackgroundTransparency = 1
    arrowLbl.Font = Enum.Font.GothamBold
    arrowLbl.Text = "v"
    arrowLbl.TextSize = 8.5
    arrowLbl.TextColor3 = Color3.fromRGB(130, 135, 155)
    arrowLbl.ZIndex = 3

    btn.MouseEnter:Connect(function()
        local curAccent = _G.CurrentAccentColor or Color3.fromRGB(110, 180, 255)
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(23, 23, 23) }):Play()
        TweenService:Create(cStk, TweenInfo.new(0.12), { Color = curAccent }):Play()
        TweenService:Create(arrowLbl, TweenInfo.new(0.12), { TextColor3 = Color3.fromRGB(240, 245, 255) }):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = Color3.fromRGB(14, 14, 14) }):Play()
        TweenService:Create(cStk, TweenInfo.new(0.12), { Color = Color3.fromRGB(37, 37, 37) }):Play()
        TweenService:Create(arrowLbl, TweenInfo.new(0.12), { TextColor3 = Color3.fromRGB(130, 135, 155) }):Play()
    end)

    table.insert(TranslatableUI, {
        btn = btn,
        txtLbl = txtLbl,
        prefixEN = prefixEN,
        prefixES = prefixES,
        getChoice = function() return tostring(choices[currentIdx]) end,
        isCycle = true
    })
    table.insert(AllUIButtons, btn)
    if isSpookyTransparentActive then
        btn.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
        btn.BackgroundTransparency = _G.SpookyGlassAlpha
    end
    local lastCycleClick = 0
    local function onCycleActivated()
        local now = os.clock()
        if now - lastCycleClick < 0.12 then return end
        lastCycleClick = now
        currentIdx = (currentIdx % #choices) + 1
        local choice = choices[currentIdx]
        local p = translateTerm and translateTerm(prefixEN, prefixES, CurrentLang) or ((CurrentLang == "EN") and prefixEN or prefixES)
        txtLbl.Text = string.format("%s: %s", p, tostring(choice))
        if onChange then onChange(choice, currentIdx) end
    end
    btn.Activated:Connect(onCycleActivated)
    btn.MouseButton1Click:Connect(onCycleActivated)
    return btn
end

-- ============================================================
-- Arur Hub UI ADAPTER
-- Every card / toggle / button / slider / cycle the legacy script creates is
-- mirrored into the Rift (RiftUI) window. The legacy ScreenGui stays alive
-- but hidden, so all of the original state logic keeps working untouched.
-- ============================================================
do
    local AF = { pageByInst = {}, cardByInst = {}, pages = {}, toggles = {}, state = {}, seenToggle = {}, custom = {}, flagN = 0, guard = false }
    Spooky.AF = AF
    local O = {
        makeCard = makeCard, toggle = createToggleButton, action = createActionButton,
        slider = createSlider, cycle = createCycleButton, scroll = createScrollPage,
    }

    local PAGE_META = {
        Combat_Page     = { "Combat",    "swords" },
        AutoBounty_Page = { "Bounty",    "target" },
        Dungeons_Page   = { "Dungeons",  "map" },
        TPIslands_Page  = { "Teleport",  "navigation" },
        Glitches_Page   = { "Glitches",  "zap" },
        Visual_Page     = { "Visuals",   "eye" },
        SacredVFX_Page  = { "VFX",       "sparkles" },
        FFlags_Page     = { "FastFlags", "flag" },
        HUD_Page        = { "HUD",       "layout-grid" },
        Misc_Page       = { "Misc",      "star" },
    }
    local PAGE_ORDER = { "Combat_Page", "AutoBounty_Page", "Dungeons_Page", "TPIslands_Page", "Glitches_Page", "Visual_Page", "SacredVFX_Page", "FFlags_Page", "HUD_Page", "Misc_Page" }
    local SKIP_CARDS = { ["Language"] = true }

    local function pageOf(inst)
        local n = 0
        while inst and n < 60 do
            local pg = AF.pageByInst[inst]
            if pg then return pg end
            inst = inst.Parent
            n = n + 1
        end
    end

    local function targetOf(parent)
        local inst, n = parent, 0
        while inst and n < 60 do
            local c = AF.cardByInst[inst]
            if c ~= nil then return c or nil end -- false = skipped card
            local pg = AF.pageByInst[inst]
            if pg then
                if not pg.loose then
                    pg.loose = { title = nil, ops = {} }
                    table.insert(pg.cards, pg.loose)
                end
                return pg.loose
            end
            inst = inst.Parent
            n = n + 1
        end
    end

    createScrollPage = function(pageName, canvasHeight)
        local sf = O.scroll(pageName, canvasHeight)
        pcall(function()
            local meta = PAGE_META[pageName]
            if meta and sf then
                local pg = { key = pageName, meta = meta, cards = {} }
                AF.pageByInst[sf] = pg
                AF.pages[pageName] = pg
            end
        end)
        return sf
    end

    makeCard = function(parent, titleEN, titleES, h, y)
        local card = O.makeCard(parent, titleEN, titleES, h, y)
        pcall(function()
            local pg = pageOf(parent)
            if pg then
                if SKIP_CARDS[titleEN] then
                    AF.cardByInst[card] = false
                else
                    local rec = { title = titleEN, ops = {} }
                    AF.cardByInst[card] = rec
                    table.insert(pg.cards, rec)
                end
            end
        end)
        return card
    end

    createToggleButton = function(parent, name, textEN, textES, size, pos, isSub)
        local btn = O.toggle(parent, name, textEN, textES, size, pos, isSub)
        pcall(function()
            local tgt = targetOf(parent)
            if tgt and not AF.seenToggle[name] then
                AF.seenToggle[name] = true
                table.insert(tgt.ops, { k = "toggle", name = name, text = textEN })
            end
        end)
        return btn
    end

    createActionButton = function(parent, textEN, textES, size, pos, onClick)
        local btn = O.action(parent, textEN, textES, size, pos, onClick)
        pcall(function()
            local tgt = targetOf(parent)
            if tgt and onClick then
                table.insert(tgt.ops, { k = "button", text = textEN, fn = onClick })
            end
        end)
        return btn
    end

    createSlider = function(parent, textEN, textES, minV, maxV, defV, isFloat, step, suffix, callback, pos)
        local frame = O.slider(parent, textEN, textES, minV, maxV, defV, isFloat, step, suffix, callback, pos)
        pcall(function()
            local tgt = targetOf(parent)
            if tgt and callback then
                table.insert(tgt.ops, {
                    k = "slider", text = textEN, min = minV, max = maxV, def = defV,
                    step = step or (isFloat and 0.1 or 1), suffix = suffix, fn = callback,
                })
            end
        end)
        return frame
    end

    createCycleButton = function(parent, prefixEN, prefixES, choices, defaultIdx, size, pos, onChange)
        local btn = O.cycle(parent, prefixEN, prefixES, choices, defaultIdx, size, pos, onChange)
        pcall(function()
            local tgt = targetOf(parent)
            if tgt and choices and #choices > 0 then
                table.insert(tgt.ops, { k = "cycle", text = prefixEN, choices = choices, idx = defaultIdx or 1, fn = onChange })
            end
        end)
        return btn
    end

    -- called from updateToggleVisual: keeps the RiftUI switch in step with the legacy state
    Spooky.AFSync = function(name, active)
        local el = AF.toggles[name]
        active = active and true or false
        if not el or AF.state[name] == active then return end
        AF.state[name] = active
        if el.Set then
            AF.guard = true
            pcall(el.Set, el, active)
            AF.guard = false
        end
    end

    local function addOp(tab, op)
        local ok, err = pcall(function()
            if op.k == "toggle" then
                local name = op.name
                AF.state[name] = FeatureStates[name] and true or false
                AF.toggles[name] = tab:CreateToggle({
                    Name = op.text,
                    Flag = "BF_T_" .. tostring(name):gsub("[^%w]", ""),
                    CurrentValue = AF.state[name],
                    Callback = function(v)
                        if AF.guard then return end
                        v = v and true or false
                        AF.state[name] = v
                        if (FeatureStates[name] or false) ~= v then
                            local f = _G.setFeatureState
                            if f then pcall(f, name, v) end
                        end
                    end,
                })
            elseif op.k == "button" then
                tab:CreateButton({
                    Name = op.text,
                    Callback = function() task.spawn(function() pcall(op.fn) end) end,
                })
            elseif op.k == "slider" then
                AF.flagN = AF.flagN + 1
                local lo, hi = tonumber(op.min) or 0, tonumber(op.max) or 100
                local def = math.clamp(tonumber(op.def) or lo, lo, hi)
                tab:CreateSlider({
                    Name = op.suffix and op.suffix ~= "" and (op.text .. " (" .. tostring(op.suffix) .. ")") or op.text,
                    Flag = "BF_S" .. AF.flagN,
                    Range = { lo, hi },
                    Increment = tonumber(op.step) or 1,
                    CurrentValue = def,
                    Callback = function(v) pcall(op.fn, v) end,
                })
            elseif op.k == "cycle" then
                AF.flagN = AF.flagN + 1
                local strs = {}
                for i, c in ipairs(op.choices) do strs[i] = tostring(c) end
                tab:CreateDropdown({
                    Name = op.text,
                    Flag = "BF_D" .. AF.flagN,
                    Options = strs,
                    CurrentValue = strs[op.idx] or strs[1],
                    Callback = function(v)
                        if type(v) == "table" then v = v[1] end
                        local i = table.find(strs, tostring(v)) or 1
                        if op.fn then pcall(op.fn, op.choices[i], i) end
                    end,
                })
            end
        end)
        if not ok then
            AF.errors = AF.errors or {}
            table.insert(AF.errors, tostring(op.text) .. ": " .. tostring(err))
        end
    end

    Spooky.AFFlush = function()
        local RiftUI = Spooky.AFLib
        if not RiftUI then return end
        local Window = RiftUI:CreateWindow({
            Name = "Arur Hub",
            LoadingSubtitle = "Blox Fruits",
            Theme = "RiftBlue",
            ToggleUIKeybind = "RightControl",
            ConfigurationSaving = { Enabled = true, FolderName = "RiftWtf", FileName = "BloxFruits" },
        })
        AF.Window = Window

        for _, key in ipairs(PAGE_ORDER) do
            local pg = AF.pages[key]
            local custom = AF.custom[key]
            if pg then
                local has = custom ~= nil
                for _, c in ipairs(pg.cards) do if #c.ops > 0 then has = true break end end
                if has then
                    local tab = Window:CreateTab({ Name = pg.meta[1], Icon = pg.meta[2] })
                    for _, c in ipairs(pg.cards) do
                        if #c.ops > 0 then
                            if c.title then pcall(function() tab:CreateSection(c.title) end) end
                            for _, op in ipairs(c.ops) do addOp(tab, op) end
                        end
                    end
                    if custom then
                        local ok, err = pcall(custom, tab)
                        if not ok then
                            AF.errors = AF.errors or {}
                            table.insert(AF.errors, key .. ": " .. tostring(err))
                        end
                    end
                end
            end
        end

        local settings = Window:CreateTab({ Name = "Settings", Icon = "settings" })
        settings:CreateSection("Config")
        settings:CreateButton({
            Name = "Save Config", Desc = "Save current settings to 'default'", Icon = "save",
            Callback = function()
                local ok = pcall(function() Window:SaveConfig("default") end)
                pcall(function() Window:Notify({ title = "Config", content = ok and "Saved 'default'" or "Failed to save", duration = 3 }) end)
            end,
        })
        settings:CreateButton({
            Name = "Load Config", Desc = "Load settings from 'default'", Icon = "folder-open",
            Callback = function()
                local ok = pcall(function() Window:LoadConfig("default") end)
                pcall(function() Window:Notify({ title = "Config", content = ok and "Loaded 'default'" or "No saved config found", duration = 3 }) end)
            end,
        })
        local info = Window:CreateTab({ Name = "Info", Icon = "info" })
        info:CreateSection("Discord")
        info:CreateButton({
            Name = "Copy Discord Link", Desc = "Copies https://discord.gg/kA3V23ry7K", Icon = "link",
            Callback = function()
                pcall(function() setclipboard("https://discord.gg/kA3V23ry7K") end)
                pcall(function() Window:Notify({ title = "Discord", content = "Link copied to clipboard!", duration = 3 }) end)
            end,
        })
        info:CreateSection("Credits")
        pcall(function()
            info:CreateParagraph({ Title = "Blox Fruits module", Content = "Based on Project Lumi by Darling (open source), rebranded for Arur Hub." })
        end)
        pcall(function() Window:Notify({ title = "Arur", content = "Blox Fruits loaded.", duration = 4 }) end)
    end
end

local function styleSpookyTextBox(box)
    if not box or not box:IsA("TextBox") then return end
    if box.Text == "TextBox" or box.Text == "textbox" then
        box.Text = ""
    end
    box.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
    box.TextColor3 = Color3.fromRGB(240, 240, 250)
    box.PlaceholderColor3 = Color3.fromRGB(125, 130, 150)
    box.Font = Enum.Font.GothamMedium
    if not box:FindFirstChildOfClass("UICorner") then
        Instance.new("UICorner", box).CornerRadius = UDim.new(0, 6)
    end
    local stk = box:FindFirstChildOfClass("UIStroke")
    if not stk then
        stk = Instance.new("UIStroke", box)
    end
    stk.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stk.Color = Color3.fromRGB(39, 39, 39)
    stk.Thickness = 1

    if not box:FindFirstChild("SpookyBoxEmblem") and not box.MultiLine then
        local emblem = Instance.new("ImageLabel", box)
        emblem.Name = "SpookyBoxEmblem"
        emblem.Size = UDim2.new(0, 16, 0, 16)
        emblem.Position = UDim2.new(1, -22, 0.5, -8)
        emblem.BackgroundTransparency = 1
        emblem.Image = "rbxassetid://104266247868011"
        emblem.ImageColor3 = Color3.fromRGB(130, 135, 155)
        emblem.ZIndex = box.ZIndex + 1
        Instance.new("UICorner", emblem).CornerRadius = UDim.new(1, 0)

        box.Focused:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(180, 195, 230) }):Play()
            TweenService:Create(emblem, TweenInfo.new(0.15), { ImageColor3 = Color3.fromRGB(255, 255, 255) }):Play()
        end)
        box.FocusLost:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(39, 39, 39) }):Play()
            TweenService:Create(emblem, TweenInfo.new(0.15), { ImageColor3 = Color3.fromRGB(130, 135, 155) }):Play()
        end)
    else
        box.Focused:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(180, 195, 230) }):Play()
        end)
        box.FocusLost:Connect(function()
            TweenService:Create(stk, TweenInfo.new(0.15), { Color = Color3.fromRGB(39, 39, 39) }):Play()
        end)
    end
end

