                            pcall(function() c:Destroy() end)
                        end
                    end
                end
            end
            Settings.walkSpeed = 16
            Settings.dashDist = 50
            Settings.flySpeed = 100
            Settings.superJumpHeight = 500
            resetUISettingsOnly()
            pcall(function()
                if delfile and isfile then
                    if isfile("RiftWtf_BF_QuickToggles.json") then delfile("RiftWtf_BF_QuickToggles.json") end
                    if isfile("RiftWtf_BF_PCKeybinds.json") then delfile("RiftWtf_BF_PCKeybinds.json") end
                    if isfile("RiftWtf_BF_ESPConfig.json") then delfile("RiftWtf_BF_ESPConfig.json") end
                    if isfile("RiftWtf_BF_ui_config.txt") then delfile("RiftWtf_BF_ui_config.txt") end
                    if isfile("RiftWtf_BF_theme.txt") then delfile("RiftWtf_BF_theme.txt") end
                    if isfile("RiftWtf_BF_config.txt") then delfile("RiftWtf_BF_config.txt") end
                end
            end)
            notifyToggle("ALL SETTINGS & UI RESET TO FACTORY DEFAULTS!", true)
        end)
