    local function updateAnimButtonsVisual(activeName)
        local curAccent = _G.CurrentAccentColor or Color3.fromRGB(110, 180, 255)
        local curBright = _G.CurrentAccentColorBright or Color3.fromRGB(245, 245, 245)
        for name, btn in pairs(animButtons) do
            local isSel = (name == activeName)
            btn.BackgroundColor3 = isSel and Color3.fromRGB(33, 33, 33) or Color3.fromRGB(18, 18, 18)
            local st = btn:FindFirstChildOfClass("UIStroke")
            if st then
                st.Color = isSel and curAccent or Color3.fromRGB(42, 42, 42)
                st.Thickness = isSel and 1.4 or 1
            end
            btn.TextColor3 = isSel and curBright or Color3.fromRGB(175, 175, 195)
        end
    end
