    local pApplyBtn = createActionButton(cAvatar, "CLONE OUTFIT", "CLONAR OUTFIT", UDim2.new(0, 96, 0, 26), UDim2.new(1, -102, 0, 68), function()
        local ok, msg = cloneOutfitByUserIdOrName(pBox.Text)
