    createActionButton(cAvatar, "Clone Nearest Player", "Clonar Mas Cercano", UDim2.new(0.48, -4, 0, 26), UDim2.new(0, 6, 0, 102), function()
        pcall(function()
            local myChar = LocalPlayer.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHrp then return end

            local closestP = nil
            local closestDist = math.huge
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local d = (hrp.Position - myHrp.Position).Magnitude
                        if d < closestDist then
                            closestDist = d
                            closestP = p
                        end
                    end
                end
            end
            if not closestP then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer then closestP = p; break end
                end
            end

            if closestP and closestP.Character then
                applyAvatarFromSource(closestP.Character)
                notifyToggle("Cloned outfit: " .. closestP.DisplayName .. " (" .. math.floor(closestDist == math.huge and 0 or closestDist) .. " studs)", true)
            else
                notifyToggle("No other players found in server", false)
            end
        end)
    end)

    createActionButton(cAvatar, "Restore Original Outfit", "Restablecer Original", UDim2.new(0.48, -4, 0, 26), UDim2.new(0.5, 4, 0, 102), function()
        pcall(function()
            local ok = restoreMyOriginalSkin()
            if ok then
                notifyToggle("Outfit restored to original", true)
            else
                notifyToggle("No original outfit saved", false)
            end
        end)
    end)

end
do
    local SacredVFXPage = createScrollPage("SacredVFX_Page", 590)

    local VFXSettings = {
        Enabled = false,
        Preset = "Purple",
        CustomAccent = Color3.fromRGB(165, 75, 230),
        AffectSkills = true,
        AffectSwords = true,
        AffectTransform = true,
        AffectEnvironment = true
    }
    Spooky.VFX = VFXSettings

    local VFXPresets = {

        ["Purple"]        = Color3.fromRGB(165, 75, 230),
        ["Red"]           = Color3.fromRGB(220, 50, 50),
        ["Blue"]          = Color3.fromRGB(65, 145, 255),
        ["Cyan"]          = Color3.fromRGB(55, 210, 225),
        ["Green"]         = Color3.fromRGB(50, 190, 100),
        ["Gold"]          = Color3.fromRGB(238, 190, 40),
        ["Pink"]          = Color3.fromRGB(235, 85, 150),
        ["Magenta"]       = Color3.fromRGB(190, 0, 205),
        ["White"]         = Color3.fromRGB(245, 245, 248),
        ["Black"]         = Color3.fromRGB(20, 20, 20),
        ["Midnight"]      = Color3.fromRGB(12, 12, 12),
        ["Rainbow"]       = Color3.fromRGB(255, 50, 100),

        ["Violet"]        = Color3.fromRGB(220, 50, 230),
        ["Lime"]          = Color3.fromRGB(80, 255, 60),
        ["Orange"]        = Color3.fromRGB(255, 120, 20),
        ["Silver"]        = Color3.fromRGB(215, 225, 245),
        ["Crimson"]       = Color3.fromRGB(220, 15, 45),
        ["Black & White"] = Color3.fromRGB(255, 255, 255),
        ["Yellow"]        = Color3.fromRGB(255, 235, 30),
        ["Teal"]          = Color3.fromRGB(0, 210, 190),
        ["Ice Blue"]      = Color3.fromRGB(160, 225, 255),

        ["Shadow Blood (Black + Red)"]     = Color3.fromRGB(220, 50, 50),
        ["Void Purple (Black + Violet)"]    = Color3.fromRGB(165, 75, 230),
        ["Abyssal Cyan (Black + Cyan)"]     = Color3.fromRGB(55, 210, 225),
        ["Rainbow Void (Black + Rainbow)"]  = Color3.fromRGB(255, 50, 100)
    }

    local function getActiveAccentColor()
        if VFXSettings.Preset == "Rainbow" or VFXSettings.Preset == "Rainbow Void (Black + Rainbow)" then
            return Color3.fromHSV((tick() * 0.18) % 1, 0.85, 1)
        elseif VFXSettings.Preset == "Custom Color (Black + Picker)" then
            return VFXSettings.CustomAccent
        end
        return VFXPresets[VFXSettings.Preset] or Color3.fromRGB(165, 75, 230)
    end

    local function blendColor(baseColor, targetColor)
        if typeof(baseColor) ~= "Color3" then
            return targetColor
        end
        local h, s, v = targetColor:ToHSV()
        local lum = math.clamp(baseColor.R * 0.2126 + baseColor.G * 0.7152 + baseColor.B * 0.0722, 0, 1)
        local val = v * (0.12 + 0.88 * math.sqrt(lum))
        local recolored = Color3.fromHSV(h, s, math.clamp(val, 0, 1))
        return baseColor:Lerp(recolored, 1.0)
    end

    local function blendColorSequence(origSeq, targetColor)
        if typeof(origSeq) ~= "ColorSequence" then
            return ColorSequence.new(targetColor)
        end
        local keypoints = {}
        for _, kp in ipairs(origSeq.Keypoints) do
            table.insert(keypoints, ColorSequenceKeypoint.new(kp.Time, blendColor(kp.Value, targetColor)))
        end
        return ColorSequence.new(keypoints)
    end

    local originals = setmetatable({}, { __mode = "k" })

    local function recordOriginal(inst, prop)
        local tbl = originals[inst]
        if not tbl then
            tbl = {}
            originals[inst] = tbl
        end
        if tbl[prop] == nil then
            local ok, val = pcall(function() return inst[prop] end)
            if ok and val ~= nil then
                tbl[prop] = val
            end
        end
    end

    local function resetOriginalVFX()
        for inst, props in pairs(originals) do
            if inst and inst.Parent then
                for prop, val in pairs(props) do
                    pcall(function()
                        inst[prop] = val
                    end)
                end
            end
        end
        originals = setmetatable({}, { __mode = "k" })
    end

    local bodyParts = {
        Head = true, Torso = true, UpperTorso = true, LowerTorso = true, HumanoidRootPart = true,
        ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
        LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
        RightUpperArm = true, RightLowerArm = true, RightHand = true,
        LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
        RightUpperLeg = true, RightLowerLeg = true, RightFoot = true
    }
    local hakiKeywords = { "haki", "buso", "hasbuso", "haki_effect" }

    local function isExcludedPart(part)
        if not part or not part:IsA("BasePart") then return true end
        if bodyParts[part.Name] then return true end
        if part:FindFirstAncestorWhichIsA("Accessory") then return true end
        local map = workspace:FindFirstChild("Map")
        if map and part:IsDescendantOf(map) then return true end
        if part:IsDescendantOf(workspace.Terrain) then return true end
        local p = part
        while p and p ~= workspace do
            local n = string.lower(p.Name)
            for _, kw in ipairs(hakiKeywords) do
                if string.find(n, kw, 1, true) then
                    return true
                end
            end
            p = p.Parent
        end
        return false
    end

    local function applyVisualColor(inst, targetColor)
        if not VFXSettings.Enabled or not inst then return end
        targetColor = targetColor or getActiveAccentColor()
        pcall(function()
            if inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam") or inst:IsA("UIGradient") then
                recordOriginal(inst, "Color")
                local orig = (originals[inst] and originals[inst].Color) or inst.Color
                inst.Color = blendColorSequence(orig, targetColor)
            elseif inst:IsA("Light") or inst:IsA("Smoke") or inst:IsA("Decal") or inst:IsA("Texture") then
                recordOriginal(inst, "Color")
                local orig = (originals[inst] and originals[inst].Color) or inst.Color
                inst.Color = blendColor(orig, targetColor)
            elseif inst:IsA("Fire") then
                recordOriginal(inst, "Color")
                recordOriginal(inst, "SecondaryColor")
                local origC = (originals[inst] and originals[inst].Color) or inst.Color
                local origSC = (originals[inst] and originals[inst].SecondaryColor) or inst.SecondaryColor
                inst.Color = blendColor(origC, targetColor)
                inst.SecondaryColor = blendColor(origSC, targetColor)
            elseif inst:IsA("Sparkles") then
                recordOriginal(inst, "SparkleColor")
                local orig = (originals[inst] and originals[inst].SparkleColor) or inst.SparkleColor
                inst.SparkleColor = blendColor(orig, targetColor)
            elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
                recordOriginal(inst, "ImageColor3")
                local orig = (originals[inst] and originals[inst].ImageColor3) or inst.ImageColor3
                inst.ImageColor3 = blendColor(orig, targetColor)
            elseif inst:IsA("Highlight") then
                recordOriginal(inst, "FillColor")
                recordOriginal(inst, "OutlineColor")
                local origF = (originals[inst] and originals[inst].FillColor) or inst.FillColor
                local origO = (originals[inst] and originals[inst].OutlineColor) or inst.OutlineColor
                inst.FillColor = blendColor(origF, targetColor)
                inst.OutlineColor = blendColor(origO, targetColor)
            elseif inst:IsA("SurfaceAppearance") or inst:IsA("UIStroke") then
                recordOriginal(inst, "Color")
                local orig = (originals[inst] and originals[inst].Color) or inst.Color
                inst.Color = blendColor(orig, targetColor)
            elseif inst:IsA("SelectionBox") then
                recordOriginal(inst, "SurfaceColor3")
                local orig = (originals[inst] and originals[inst].SurfaceColor3) or inst.SurfaceColor3
                inst.SurfaceColor3 = blendColor(orig, targetColor)
            elseif inst:IsA("SpecialMesh") then
                recordOriginal(inst, "VertexColor")
                local orig = (originals[inst] and originals[inst].VertexColor) or inst.VertexColor
                local origCol = (typeof(orig) == "Vector3" and Color3.new(orig.X, orig.Y, orig.Z)) or Color3.new(1, 1, 1)
                local blended = blendColor(origCol, targetColor)
                inst.VertexColor = Vector3.new(blended.R, blended.G, blended.B)
                local p = inst.Parent
                if p and p:IsA("BasePart") and not isExcludedPart(p) then
                    recordOriginal(p, "Color")
                    local pOrig = (originals[p] and originals[p].Color) or p.Color
                    p.Color = blendColor(pOrig, targetColor)
                end
            elseif inst:IsA("BasePart") and not isExcludedPart(inst) then
                recordOriginal(inst, "Color")
                local orig = (originals[inst] and originals[inst].Color) or inst.Color
                inst.Color = blendColor(orig, targetColor)
            end
        end)
    end

    local function scanAndApply(root, targetColor)
        if not root then return end
        applyVisualColor(root, targetColor)
        for _, descendant in ipairs(root:GetDescendants()) do
            applyVisualColor(descendant, targetColor)
        end
    end

    local function refreshAllVFX()
        task.spawn(function()
            if not VFXSettings.Enabled then return end
            local accent = getActiveAccentColor()
            for inst, _ in pairs(originals) do
                if inst and inst.Parent then
                    applyVisualColor(inst, accent)
                end
            end
            local myChar = LocalPlayer.Character
            if myChar then
                scanAndApply(myChar, accent)
            end
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
            if bp then
                scanAndApply(bp, accent)
            end
            local worldOrigin = workspace:FindFirstChild("_WorldOrigin")
            if worldOrigin then
                scanAndApply(worldOrigin, accent)
            end
            local fxFolder = workspace:FindFirstChild("Effects") or workspace:FindFirstChild("FX")
            if fxFolder then
                scanAndApply(fxFolder, accent)
            end
        end)
    end

    local vfxConnections = {}

    local function stopVFXWatchers()
        for _, conn in ipairs(vfxConnections) do
            pcall(function() conn:Disconnect() end)
        end
        table.clear(vfxConnections)
    end

    local function startVFXWatchers()
        stopVFXWatchers()

        local function bindWorldOrigin(wo)
            if not wo then return end
            table.insert(vfxConnections, wo.DescendantAdded:Connect(function(child)
                if VFXSettings.Enabled then
                    task.defer(applyVisualColor, child)
                end
            end))
        end

        local function bindCharacter(char)
            if not char then return end
            table.insert(vfxConnections, char.DescendantAdded:Connect(function(child)
                if VFXSettings.Enabled then
                    task.defer(applyVisualColor, child)
                end
            end))
        end

        local wo = workspace:FindFirstChild("_WorldOrigin")
        if wo then bindWorldOrigin(wo) end
        table.insert(vfxConnections, workspace.ChildAdded:Connect(function(child)
            if child.Name == "_WorldOrigin" then
                bindWorldOrigin(child)
                if VFXSettings.Enabled then scanAndApply(child) end
            end
        end))

        local char = LocalPlayer.Character
        if char then bindCharacter(char) end
        table.insert(vfxConnections, LocalPlayer.CharacterAdded:Connect(function(newChar)
            bindCharacter(newChar)
            if VFXSettings.Enabled then
                task.delay(0.2, function()
                    if LocalPlayer.Character == newChar and VFXSettings.Enabled then
                        scanAndApply(newChar)
                    end
                end)
            end
        end))

        local fx = workspace:FindFirstChild("Effects") or workspace:FindFirstChild("FX")
        if fx then
            table.insert(vfxConnections, fx.DescendantAdded:Connect(function(child)
                if VFXSettings.Enabled then task.defer(applyVisualColor, child) end
            end))
        end
    end

    local activeRainbowVisuals = {}
    local lastRainbowFilterTime = 0

    local function rebuildActiveRainbowVisuals()
        local list = {}
        for inst, _ in pairs(originals) do
            if inst and inst.Parent then
                local active = true
                pcall(function()
                    if inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam") or inst:IsA("Light") then
                        active = (inst.Enabled ~= false)
                    elseif inst:IsA("BasePart") then
                        active = (inst.Transparency < 0.98 and inst.LocalTransparencyModifier < 0.98)
                    elseif inst:IsA("Highlight") then
                        active = (inst.Enabled ~= false and (inst.FillTransparency < 1 or inst.OutlineTransparency < 1))
                    elseif inst:IsA("Decal") or inst:IsA("Texture") then
                        active = (inst.Transparency < 0.98)
                    elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
                        active = (inst.Visible and inst.ImageTransparency < 0.98)
                    end
                end)
                if active then
                    table.insert(list, inst)
                end
            end
        end
        activeRainbowVisuals = list
    end

    local function cleanupVFX()
        VFXSettings.Enabled = false
        resetOriginalVFX()
        stopVFXWatchers()
        table.clear(activeRainbowVisuals)
    end
    getgenv().SpookyColorVFX_Cleanup = cleanupVFX

    task.spawn(function()
        while isCurrentSession() do
            task.wait(0.07)
            if VFXSettings.Enabled and (VFXSettings.Preset == "Rainbow" or VFXSettings.Preset == "Rainbow Void (Black + Rainbow)") then
                local now = tick()
                if now - lastRainbowFilterTime > 1.5 or #activeRainbowVisuals == 0 then
                    lastRainbowFilterTime = now
                    rebuildActiveRainbowVisuals()
                end
                local currentRgb = Color3.fromHSV((now * 0.18) % 1, 0.85, 1)
                for i = 1, #activeRainbowVisuals do
                    local inst = activeRainbowVisuals[i]
                    if inst and inst.Parent then
                        applyVisualColor(inst, currentRgb)
                    end
                end
            end
        end
    end)

