    local function cancelPortalHotbarRainbow()
        if portalHotbarRainbowThread then
            task.cancel(portalHotbarRainbowThread)
            portalHotbarRainbowThread = nil
        end
    end

    local cachedPortalImages = {}
    local lastHotbarScanTime = 0

    local function getPortalHotbarImages(forceScan)
        local now = tick()
        if not forceScan and #cachedPortalImages > 0 and (now - lastHotbarScanTime < 1.5) then
            return cachedPortalImages
        end
        local results = {}
        local pGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        local backpack = pGui and pGui:FindFirstChild("Backpack")
        local hotbar = backpack and backpack:FindFirstChild("Hotbar")
        local container = hotbar and hotbar:FindFirstChild("Container")
        if not container then
            cachedPortalImages = results
            lastHotbarScanTime = now
            return results
        end
        for _, descendant in ipairs(container:GetDescendants()) do
            local itemName = descendant:IsA("GuiObject") and descendant:GetAttribute("ItemName")
            if type(itemName) == "string" and string.find(string.lower(itemName), "portal", 1, true) then
                local img = descendant:FindFirstChild("Image", true)
                if img and (img:IsA("ImageLabel") or img:IsA("ImageButton")) and not table.find(results, img) then
                    table.insert(results, img)
                end
            end
        end
        cachedPortalImages = results
        lastHotbarScanTime = now
        return results
    end

    local function getActivePortalColorRGB()
        local preset = VFXSettings.Preset or "Purple"
        local rgb = CB_NAMED_COLOR_RGB[preset]
        if not rgb then
            if preset == "Crimson" then rgb = CB_NAMED_COLOR_RGB.Red
            elseif preset == "Lime" then rgb = CB_NAMED_COLOR_RGB.Green
            elseif preset == "Yellow" then rgb = CB_NAMED_COLOR_RGB.Gold
            elseif preset == "Ice Blue" or preset == "Teal" then rgb = CB_NAMED_COLOR_RGB.Cyan
            elseif preset == "Violet" then rgb = CB_NAMED_COLOR_RGB.Purple
            elseif preset == "Black & White" then rgb = CB_NAMED_COLOR_RGB.White
            else rgb = CB_NAMED_COLOR_RGB.Purple
            end
        end
        return rgb
    end

    local function syncPortalHotbar(enable)
        cancelPortalHotbarRainbow()
        if not enable then
            for img, orig in pairs(hotbarOriginals) do
                if img and img.Parent then
                    pcall(function()
                        img.Image = orig.Image
                        img.ImageColor3 = orig.ImageColor3
                        img.ImageRectOffset = orig.ImageRectOffset
                        img.ImageRectSize = orig.ImageRectSize
                    end)
                end
            end
            hotbarOriginals = {}
            return
        end

        local preset = VFXSettings.Preset or "Purple"
        local images = getPortalHotbarImages(true)

        for _, img in ipairs(images) do
            if hotbarOriginals[img] == nil then
                hotbarOriginals[img] = {
                    Image = img.Image,
                    ImageColor3 = img.ImageColor3,
                    ImageRectOffset = img.ImageRectOffset,
                    ImageRectSize = img.ImageRectSize
                }
            end
        end

        if preset == "Rainbow" or preset == "Rainbow Void (Black + Rainbow)" then
            for _, img in ipairs(images) do
                pcall(function()
                    img.Image = "rbxassetid://89070145545737"
                    img.ImageColor3 = Color3.fromHSV((tick() * 0.18) % 1, 0.85, 1)
                    img.ImageRectOffset = Vector2.new(0, 0)
                    img.ImageRectSize = Vector2.new(0, 0)
                end)
            end
            portalHotbarRainbowThread = task.spawn(function()
                while portalHotbarActive and (VFXSettings.Preset == "Rainbow" or VFXSettings.Preset == "Rainbow Void (Black + Rainbow)") and isCurrentSession() do
                    local currentRgbColor = Color3.fromHSV((tick() * 0.18) % 1, 0.85, 1)
                    for i = #cachedPortalImages, 1, -1 do
                        local img = cachedPortalImages[i]
                        if img and img.Parent then
                            img.ImageColor3 = currentRgbColor
                        else
                            table.remove(cachedPortalImages, i)
                        end
                    end
                    task.wait(0.05)
                end
            end)
        else
            local rgb = getActivePortalColorRGB()
            local key = string.format("%d,%d,%d", math.floor(rgb[1]), math.floor(rgb[2]), math.floor(rgb[3]))
            local assetId = PORTAL_HOTBAR_ICONS[key] or PORTAL_HOTBAR_ICONS["default"] or "rbxassetid://89070145545737"
            for _, img in ipairs(images) do
                pcall(function()
                    img.Image = assetId
                    if key == "0,0,0" then
                        img.ImageColor3 = Color3.fromRGB(25, 25, 25)
                    elseif key == "10,12,24" then
                        img.ImageColor3 = Color3.fromRGB(24, 24, 24)
                    else
                        img.ImageColor3 = Color3.new(1, 1, 1)
                    end
                    img.ImageRectOffset = Vector2.new(0, 0)
                    img.ImageRectSize = Vector2.new(0, 0)
                end)
            end
        end
    end

    local function syncPortalPalette(enable)
        local char = LocalPlayer.Character
        local portalVFX = char and char:FindFirstChild("PortalFruitVFXColor")
        local defaultNode = portalVFX and portalVFX:FindFirstChild("Default")
        local shiftedNode = portalVFX and portalVFX:FindFirstChild("Shifted")
        if not (defaultNode and shiftedNode) then return end
        if not enable then
            for i = 1, 32 do
                local defCol = defaultNode:GetAttribute("Default_Color" .. i)
                if typeof(defCol) == "Color3" then
                    pcall(function() shiftedNode:SetAttribute("Shifted_Color" .. i, defCol) end)
                end
            end
            return
        end
        local rgb = getActivePortalColorRGB()
        local targetCol = Color3.fromRGB(rgb[1], rgb[2], rgb[3])
        local h, s, v = targetCol:ToHSV()
        for i = 1, 32 do
            local defCol = defaultNode:GetAttribute("Default_Color" .. i)
            if typeof(defCol) ~= "Color3" then break end
            local lum = math.clamp(defCol.R * 0.2126 + defCol.G * 0.7152 + defCol.B * 0.0722, 0, 1)
            local val = v * (0.12 + 0.88 * math.sqrt(lum))
            local blended = Color3.fromHSV(h, s, math.clamp(val, 0, 1))
            local finalCol = defCol:Lerp(blended, 1.0)
            pcall(function()
                shiftedNode:SetAttribute("Shifted_Color" .. i, finalCol)
            end)
        end
    end

    local function syncPortalVSceneRGB(enable)
        local lighting = game:GetService("Lighting")
        local fxName = "SpookyPortalVRGB"
        local fx = lighting:FindFirstChild(fxName)
        if not enable then
            if fx then pcall(function() fx:Destroy() end) end
            return
        end
        if not (fx and fx:IsA("ColorCorrectionEffect")) then
            if fx then pcall(function() fx:Destroy() end) end
            fx = Instance.new("ColorCorrectionEffect")
            fx.Name = fxName
            fx.Brightness = 0
            fx.Contrast = 0
            fx.Saturation = 0
            fx.Parent = lighting
        end
        local rgb = getActivePortalColorRGB()
        local targetCol = Color3.fromRGB(rgb[1], rgb[2], rgb[3])
        pcall(function()
            fx.Enabled = true
            fx.TintColor = Color3.new(1, 1, 1):Lerp(targetCol, 0.46)
        end)
    end

    local function refreshAllPortalSkin()
        if portalHotbarActive then syncPortalHotbar(true) end
        if portalPaletteActive then syncPortalPalette(true) end
        if portalVRGBActive then syncPortalVSceneRGB(true) end
    end
    _G.SpookyRefreshPortalSkin = refreshAllPortalSkin

    task.spawn(function()
        local pGui = LocalPlayer:WaitForChild("PlayerGui", 5)
        local backpack = pGui and pGui:WaitForChild("Backpack", 5)
        local hotbar = backpack and backpack:WaitForChild("Hotbar", 5)
        local container = hotbar and hotbar:WaitForChild("Container", 5)
        if container then
            container.DescendantAdded:Connect(function()
                if portalHotbarActive then
                    task.delay(0.05, function() syncPortalHotbar(true) end)
                end
            end)
        end
    end)

    local sc4BW = UDim2.new(0, 124, 0, 30)
    createToggleButton(sc4, "PortalHotbar", "Color Hotbar", "Icono Hotbar", sc4BW, UDim2.new(0, X1, 0, 26))
    createToggleButton(sc4, "PortalPalette", "VFX Palette", "Paleta VFX", sc4BW, UDim2.new(0, X2, 0, 26))
    createToggleButton(sc4, "PortalVRGB", "V Dimension", "Dimensión V", sc4BW, UDim2.new(0, X3, 0, 26))

    createActionButton(sc4, "Sync Portal Color Now", "Sincronizar Color Portal", UDim2.new(1, -12, 0, 28), UDim2.new(0, 6, 0, 66), function()
        refreshAllPortalSkin()
        notifyToggle("Portal Color Synchronized: " .. (VFXSettings.Preset or "Purple"), true)
    end)

    FeatureCallbacks["PortalHotbar"] = function(v)
        portalHotbarActive = v
        syncPortalHotbar(v)
        notifyToggle("Portal Hotbar Coloring: " .. (v and "ENABLED" or "DISABLED"), v)
    end
    FeatureCallbacks["PortalPalette"] = function(v)
        portalPaletteActive = v
        syncPortalPalette(v)
        notifyToggle("Portal Palette Shift: " .. (v and "ENABLED" or "DISABLED"), v)
    end
    FeatureCallbacks["PortalVRGB"] = function(v)
        portalVRGBActive = v
        syncPortalVSceneRGB(v)
        notifyToggle("Portal V Scene Color: " .. (v and "ENABLED" or "DISABLED"), v)
    end

    print("[Fatal Labs]: Fatal Color VFX y Fatal Skin Changer cargados exitosamente.")
end
do
    local DungeonsPage = createScrollPage("Dungeons_Page", 450)
    local autoDungeonActive = false
    local dungeonEpoch = 0
    local dungeonCollision = setmetatable({}, {__mode="k"})
    local attackHeight = 40
    local selectedWeapon = "Sword"
    local weaponOptions = { "Sword", "Melee", "Blox Fruit" }
    local currentWeaponIndex = 1
    local justDied = false
    local currentTarget = nil
    local lastTarget = nil
    local dungeonStatusLbl = nil
    local dungeonHeightChoiceLbl = nil
    local function updateDungeonStatus(text)
        if dungeonStatusLbl then
            dungeonStatusLbl.Text = (CurrentLang == "EN")
                and string.format("Status: %s | Height: %d | %s", text, attackHeight, selectedWeapon)
                or string.format("Estado: %s | Altura: %d | %s", text, attackHeight, selectedWeapon)
        end
    end
    local function resolveDungeonRemotes()
        local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
        local regAttack = (net and net:FindFirstChild("RE/RegisterAttack"))
            or ReplicatedStorage:FindFirstChild("RegisterAttack", true)
            or ReplicatedStorage:FindFirstChild("RE/RegisterAttack", true)
        local regHit = (net and net:FindFirstChild("RE/RegisterHit"))
            or ReplicatedStorage:FindFirstChild("RegisterHit", true)
            or ReplicatedStorage:FindFirstChild("RE/RegisterHit", true)
        return regAttack, regHit
    end
    local function resolveCommF()
        return (ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("CommF_"))
            or ReplicatedStorage:FindFirstChild("CommF_", true)
    end
    local function GetWeaponInBackpack(targetCat)
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if not bp then return nil end
        for _, tool in ipairs(bp:GetChildren()) do
            if tool:IsA("Tool") and getToolCategory(tool) == targetCat then
                return tool
            end
        end
        return nil
    end
    local function EquipSelectedWeapon()
        local char = LocalPlayer.Character
        if not char or not autoDungeonActive then return end
        local targetCat = (selectedWeapon == "Blox Fruit" and "Fruit") or selectedWeapon
        local currentTool = char:FindFirstChildOfClass("Tool")
        if currentTool and getToolCategory(currentTool) == targetCat then
            return
        end
        local toolToEquip = GetWeaponInBackpack(targetCat)
        if toolToEquip then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then hum:EquipTool(toolToEquip) end
        end
    end
    local function ForceActivateHaki()
        local char = LocalPlayer.Character
        if not char or not autoDungeonActive then return end
        if not char:FindFirstChild("HasBuso") then
            pcall(function()
                local cf = resolveCommF()
                if cf then cf:InvokeServer("Buso") end
            end)
        end
    end
    local function StartAutoBuffs()
        local epoch = dungeonEpoch
        task.spawn(function()
            while autoDungeonActive and epoch == dungeonEpoch and isCurrentSession() do
                task.wait(0.5)

            end
        end)
        task.spawn(function()
            while autoDungeonActive and epoch == dungeonEpoch and isCurrentSession() do
                EquipSelectedWeapon()
                task.wait(0.4)
            end
        end)
        task.spawn(function()
            while autoDungeonActive and epoch == dungeonEpoch and isCurrentSession() do
                ForceActivateHaki()
                task.wait(0.2)
            end
        end)
    end
    local function ensureDungeonFloat(hrp)
        if not hrp then return nil end
        local bv = hrp:FindFirstChild("DungeonFloat")
        if not bv then
            bv = Instance.new("BodyVelocity")
            bv.Name = "DungeonFloat"
            bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
            bv.Velocity = Vector3.zero
            bv.Parent = hrp
        else
            bv.Velocity = Vector3.zero
            bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
        end
        return bv
    end
    local function removeDungeonFloat(hrp)
        if hrp then
            local bv = hrp:FindFirstChild("DungeonFloat")
            if bv then bv:Destroy() end
        end
    end
    local function setCharacterNoclip(char)
        if char then
            for _, p in ipairs(char:GetChildren()) do
                if p:IsA("BasePart") and p.CanCollide then
                    dungeonCollision[p] = true
                    p.CanCollide = false
                end
            end
        end
    end
    local function GetClosestEnemy()
        local enemiesFolder = workspace:FindFirstChild("Enemies")
        if not enemiesFolder then return nil end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local myPos = hrp.Position
        local bossAlive = false
        for _, obj in ipairs(enemiesFolder:GetChildren()) do
            if obj:IsA("Model") and not Players:GetPlayerFromCharacter(obj) then
                local nl = string.lower(obj.Name)
                if string.find(nl, "gas knight") or string.find(nl, "kitsune") or string.find(nl, "captain") then
                    local hum = obj:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        bossAlive = true
                        break
                    end
                end
            end
        end
        local closestEnemy = nil
        local shortestDistance = math.huge
        for _, obj in ipairs(enemiesFolder:GetChildren()) do
            if obj:IsA("Model") and obj ~= char and not Players:GetPlayerFromCharacter(obj) then
                local isPlaceholder = (obj.Name == "PropHitboxPlaceholder" and not bossAlive)
                local isBuddy = (obj.Name == "Blank Buddy" or obj.Name == "Sombra" or obj.Name == "Shadow")
                if not isPlaceholder and not isBuddy then
                    local hum = obj:FindFirstChildOfClass("Humanoid")
                    local root = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Head") or obj:FindFirstChildOfClass("BasePart")
                    if hum and hum.Health > 0 and root and obj.Parent then
                        local dist = (root.Position - myPos).Magnitude
                        local nl = string.lower(obj.Name)
                        if string.find(nl, "gas knight") or string.find(nl, "kitsune") or string.find(nl, "captain") then
                            dist = dist - 1000
                        end
                        if dist < shortestDistance then
                            shortestDistance = dist
                            closestEnemy = obj
                        end
                    end
                end
            end
        end
        if closestPlayerObj then
            Spooky.Diagnostics.statuses.Target = closestPlayerObj.Name
        else
            local reasons={}
            for reason,count in pairs(rejected) do table.insert(reasons,reason .. "=" .. count) end
            table.sort(reasons)
            Spooky.Diagnostics.statuses.Target="No target: " .. table.concat(reasons,", ")
        end
        return closestEnemy
    end
    local function AttackEnemy(enemy)
        if not enemy or not enemy.Parent then return end
        local char = LocalPlayer.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local enemyRoot = enemy:FindFirstChild("HumanoidRootPart") or enemy:FindFirstChild("Head") or enemy:FindFirstChildOfClass("BasePart")
        local enemyHum = enemy:FindFirstChildOfClass("Humanoid")
        if not enemyRoot or not enemyHum or enemyHum.Health <= 0 then return end
        ensureDungeonFloat(hrp)
        hrp.CFrame = CFrame.new(enemyRoot.Position + Vector3.new(0, attackHeight, 0), enemyRoot.Position)
        hrp.AssemblyLinearVelocity = Vector3.zero
        setCharacterNoclip(char)
        local tool = char:FindFirstChildOfClass("Tool")
        if tool then tool:Activate() end
        local regAttack, regHit = resolveDungeonRemotes()
        if regAttack and regHit then
            pcall(function()
                regAttack:FireServer(0)
                regHit:FireServer(enemyRoot, { { enemy, enemyRoot } })
            end)
        end
    end
    local function AutoPassRoom()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        removeDungeonFloat(hrp)

        local wo = workspace:FindFirstChild("_WorldOrigin")
        local locs = wo and wo:FindFirstChild("Locations")
        if locs then
            local myPos = hrp.Position
            local islands = {}
            for i = 1, 5 do
                local isl = locs:FindFirstChild("Island " .. tostring(i)) or locs:FindFirstChild("Island" .. tostring(i))
                if isl then
                    local pos = (isl:IsA("BasePart") and isl.Position) or (isl:FindFirstChildOfClass("BasePart") and isl:FindFirstChildOfClass("BasePart").Position)
                    if pos then
                        table.insert(islands, { index = i, object = isl, position = pos })
                    end
                end
            end
            if #islands > 0 then
                table.sort(islands, function(a, b) return a.index < b.index end)
                local currentIdx = 1
                local minDist = math.huge
                for _, isl in ipairs(islands) do
                    local d = (isl.position - myPos).Magnitude
                    if d < minDist then
                        minDist = d
                        currentIdx = isl.index
                    end
                end
                local nextIdx = currentIdx + 1
                if nextIdx <= 5 then
                    local nextIsland = nil
                    for _, isl in ipairs(islands) do
                        if isl.index == nextIdx then
                            nextIsland = isl
                            break
                        end
                    end
                    if nextIsland then
                        local targetCF = CFrame.new(nextIsland.position + Vector3.new(0, (attackHeight or 40) + 15, 0))
                        hrp.CFrame = targetCF
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        ensureDungeonFloat(hrp)
                        setCharacterNoclip(char)
                        return true, "Island " .. tostring(nextIdx)
                    end
                else
                    return true, "Final Stage"
                end
            end
        end

        local mapFolder = workspace:FindFirstChild("Map")
        local dungeonFolder = mapFolder and mapFolder:FindFirstChild("Dungeon")
        if dungeonFolder then
            local nearest, roomName, best = nil, nil, math.huge
            for _, room in ipairs(dungeonFolder:GetChildren()) do
                local exit = room:FindFirstChild("ExitTeleporter") or room:FindFirstChild("Teleporter")
                local part = exit and ((exit:IsA("BasePart") and exit) or exit:FindFirstChild("Root") or exit:FindFirstChildWhichIsA("BasePart", true))
                if part and part:IsA("BasePart") and part:FindFirstChildOfClass("TouchTransmitter") then
                    local distance = (part.Position - hrp.Position).Magnitude
                    if distance < best then nearest, roomName, best = part, room.Name, distance end
                end
            end
            if nearest then
                local epoch = dungeonEpoch
                hrp.CFrame = nearest.CFrame + Vector3.new(0, 1.5, 0)
                hrp.AssemblyLinearVelocity = Vector3.zero
                if firetouchinterest then
                    pcall(firetouchinterest, hrp, nearest, 0)
                    task.wait(0.1)
                    if hrp.Parent and nearest.Parent then pcall(firetouchinterest, hrp, nearest, 1) end
                end
                if epoch ~= dungeonEpoch then return false end
                return true, "Room " .. tostring(roomName) .. " Exit"
            end
        end

        return false
    end

    local isDungeonRoomTransitioning = false
    local lastDungeonPassTick = 0
    local emptyWaveCheckCount = 0

    local function RotateTargets()
        local epoch = dungeonEpoch
        isDungeonRoomTransitioning = false
        lastDungeonPassTick = 0
        emptyWaveCheckCount = 0
        while autoDungeonActive and epoch == dungeonEpoch and isCurrentSession() do
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not hrp or not hum or hum.Health <= 0 then
                task.wait(0.5)
            else
                local enemy = GetClosestEnemy()
                if enemy then
                    emptyWaveCheckCount = 0
                    currentTarget = enemy
                    local enemyHum = enemy:FindFirstChildOfClass("Humanoid")
                    local targetName = enemy.Name
                    local attackTimer = 0
                    while autoDungeonActive and epoch == dungeonEpoch and isCurrentSession() and enemy.Parent and enemyHum and enemyHum.Health > 0 and attackTimer < 15 do
                        local c = LocalPlayer.Character
                        local h = c and c:FindFirstChild("HumanoidRootPart")
                        local hm = c and c:FindFirstChildOfClass("Humanoid")
                        if not c or not h or not hm or hm.Health <= 0 then break end
                        updateDungeonStatus("Hunting: " .. targetName .. " [" .. math.floor(enemyHum.Health) .. " HP]")
                        AttackEnemy(enemy)
                        task.wait(0.08)
                        attackTimer = attackTimer + 0.08
                    end
                    removeDungeonFloat(hrp)
                else
                    currentTarget = nil
                    removeDungeonFloat(hrp)
                    emptyWaveCheckCount = emptyWaveCheckCount + 1

                    if emptyWaveCheckCount < 3 then
                        updateDungeonStatus("Wave Cleared! Waiting for mob spawn (" .. tostring(emptyWaveCheckCount) .. "/3)...")
                        task.wait(0.8)
                    else
                        local now = tick()
                        if not isDungeonRoomTransitioning and (now - lastDungeonPassTick > 3.0) then
                            updateDungeonStatus("Advancing to Next Room / Stage...")
                            local passed, stageInfo = AutoPassRoom()
                            if passed then
                                isDungeonRoomTransitioning = true
                                lastDungeonPassTick = now
                                emptyWaveCheckCount = 0
                                updateDungeonStatus("Advancing: " .. (stageInfo or "Next Stage") .. "! Loading new room...")
                                task.wait(2.5)
                                isDungeonRoomTransitioning = false
                            else
                                task.wait(1.0)
                            end
                        else
                            task.wait(0.6)
                        end
                    end
                end
            end
        end
        if epoch ~= dungeonEpoch then return end
        pcall(function()
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            removeDungeonFloat(hrp)
        end)
        updateDungeonStatus("Idle (Dungeon Stopped)")
    end
    LocalPlayer.CharacterAdded:Connect(function()
        if autoDungeonActive then
            justDied = true
            task.spawn(function()
                task.wait(0.8)
                justDied = false
            end)
        end
    end)
    local c1 = makeCard(DungeonsPage, "Auto Dungeon", "Auto Mazmorra", 136, 2)
    local BW = UDim2.new(0, 124, 0, 30)
