    dungeonHeightChoiceLbl = createCycleButton(c1, "Attack Height", "Altura", { "15 studs", "25 studs", "35 studs", "40 studs (Def)", "50 studs", "60 studs", "80 studs", "100 studs" }, 4, BW, UDim2.new(0, X3, 0, 26), function(choice)
        attackHeight = tonumber(string.match(choice, "%d+")) or 40
