    createToggleButton(c1, "AutoV4Dungeon", "Auto V4", "Auto V4", BW, UDim2.new(0, X1, 0, 62))
    createActionButton(c1, "Pass Room / Next", "Siguiente Isla / Sala", BW, UDim2.new(0, X2, 0, 62), function()
        local success, stage = AutoPassRoom()
