    dungeonStatusLbl.Text = "Status: Idle (Dungeon Stopped) | Height: 40 | Weapon: Sword"
        local v4DungeonConn = nil
    FeatureCallbacks["AutoV4Dungeon"] = function(papuxx)
        autoV4Dungeon = papuxx
        if papuxx then
            if v4DungeonConn then task.cancel(v4DungeonConn) end
            v4DungeonConn = task.spawn(function()
                while autoV4Dungeon and isCurrentSession() do
                    task.wait(0.5)
                    local char = LocalPlayer.Character
                    if char then
                        local energy = char:FindFirstChild("RaceEnergy")
                        local transformed = char:FindFirstChild("RaceTransformed")
                        local stun = char:FindFirstChild("Stun")
                        local busy = char:FindFirstChild("Busy")

                        local hasEnergy = energy and tonumber(energy.Value) and tonumber(energy.Value) >= 1
                        local notTransformed = not transformed or (transformed.Value ~= true)
                        local notStunned = not stun or (tonumber(stun.Value) or 0) <= 0
                        local notBusy = not busy or (busy.Value ~= true)

                        if hasEnergy and notTransformed and notStunned and notBusy then
                            if _G.SpookyTriggerAwakeningV4 then
                                _G.SpookyTriggerAwakeningV4(true)
                            else
                                pcall(function()
                                    local rem = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                                    local commE = rem and rem:FindFirstChild("CommE")
                                    if commE then commE:FireServer("ActivateAwakening", true) end
                                    local bp = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
                                    local awk = (bp and bp:FindFirstChild("Awakening")) or (char and char:FindFirstChild("Awakening"))
                                    if awk then
                                        local hum = char and char:FindFirstChildOfClass("Humanoid")
                                        if awk.Parent == bp and hum then pcall(function() hum:EquipTool(awk) end) end
                                        pcall(function() awk:Activate() end)
                                        local rf = awk:FindFirstChild("RemoteFunction")
                                        if rf and rf:IsA("RemoteFunction") then pcall(function() rf:InvokeServer(true) end) end
                                        local re = awk:FindFirstChild("RemoteEvent")
                                        if re and re:IsA("RemoteEvent") then pcall(function() re:FireServer(true) end) end
                                    end
                                end)
                            end
                            task.wait(2.0)
                        end
                    end
                end
            end)
        else
            if v4DungeonConn then task.cancel(v4DungeonConn); v4DungeonConn = nil end
        end
    end
    FeatureCallbacks["AutoDungeon"] = function(state)
        if state == autoDungeonActive then return end
        dungeonEpoch += 1
        autoDungeonActive = state
        if not state then
            for part, collision in pairs(dungeonCollision) do
                if part.Parent then part.CanCollide = collision end
            end
            table.clear(dungeonCollision)
        end
        if state then
            justDied = false
            StartAutoBuffs()
            task.spawn(RotateTargets)
            notifyToggle("Auto Dungeon: ON", true)
            updateDungeonStatus("Running")
        else
            currentTarget = nil
            lastTarget = nil
            justDied = false
            pcall(function()
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                removeDungeonFloat(hrp)
            end)
            notifyToggle("Auto Dungeon: OFF", false)
            updateDungeonStatus("Idle")
        end
    end
end
