    statusLbl.TextColor3 = Color3.fromRGB(195, 195, 215)
    statusLbl.TextXAlignment = Enum.TextXAlignment.Left
    statusLbl.TextTruncate = Enum.TextTruncate.AtEnd
    statusLbl.TextWrapped = false
    statusLbl.Text = "Estado: Inactivo (Haz clic en Iniciar) | Frutas: 0"

    task.spawn(function()
        local function GetCommF()
            return ReplicatedStorage:WaitForChild("Remotes", 9):WaitForChild("CommF_", 9)
        end
        local function GetFruitHandle(fruitModel)
            if not fruitModel then return nil end
            if fruitModel:IsA("Tool") then
                return fruitModel:FindFirstChild("Handle") or fruitModel:FindFirstChildWhichIsA("BasePart")
            elseif fruitModel:IsA("Model") then
                return fruitModel:FindFirstChild("Handle") or fruitModel.PrimaryPart or fruitModel:FindFirstChildWhichIsA("BasePart")
            end
            return nil
        end
        local function isStillSpawned(fruitObj)
            if not fruitObj or not fruitObj.Parent then return false end
            local p = fruitObj.Parent
            if p == workspace then return true end
            while p and p ~= game do
                if p == workspace then return true end
                if p:IsA("Model") and Players:GetPlayerFromCharacter(p) then return false end
                p = p.Parent
            end
            return false
        end
        local function GetSpawnedFruits()
            local fruits = {}
            for _, obj in ipairs(workspace:GetChildren()) do
                if (obj:IsA("Tool") or obj:IsA("Model")) and string.find(obj.Name, "Fruit") then
                    local handle = GetFruitHandle(obj)
                    if handle and isStillSpawned(obj) then
                        table.insert(fruits, { Object = obj, Handle = handle })
                    end
                end
            end
            return fruits
        end
        local function FlyToFruit(handle)
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hrp or not handle then return end
            if hum then hum.Sit = false end
            local targetCF = handle.CFrame * CFrame.new(0, 3, 0)
            local distance = (hrp.Position - handle.Position).Magnitude
            local flySpeed = _G.FlySpeed or 280

            local bv = Instance.new("BodyVelocity")
            bv.Name = "SpookyFruitBV"
            bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
            bv.Velocity = Vector3.zero
            bv.Parent = hrp

            local bg = Instance.new("BodyGyro")
            bg.Name = "SpookyFruitBG"
            bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
            bg.CFrame = hrp.CFrame
            bg.Parent = hrp

            local noclipConn = nil
            noclipConn = RunService.Stepped:Connect(function()
                local c = LocalPlayer.Character
                if c then
                    local h = c:FindFirstChildOfClass("Humanoid")
                    if h then h.Sit = false end
                    for _, part in ipairs(c:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.CanCollide = false
                        end
                    end
                end
            end)
            pcall(function()
                hrp.Velocity = Vector3.zero
                hrp.AssemblyLinearVelocity = Vector3.zero
            end)
            if distance <= 80 then
                pcall(function() char:PivotTo(targetCF) end)
                hrp.CFrame = targetCF
            else
                local flyTime = math.max(distance / flySpeed, 0.2)
                local tweenInfo = TweenInfo.new(flyTime, Enum.EasingStyle.Linear)
                local tween = TweenService:Create(hrp, tweenInfo, { CFrame = targetCF })
                tween:Play()
                local startT = tick()
                while (tick() - startT) < flyTime and handle and handle.Parent and _G.AutoCollectHop do
                    if (hrp.Position - handle.Position).Magnitude <= 12 then
                        tween:Cancel()
                        break
                    end
                    task.wait(0.04)
                end
                pcall(function() tween:Cancel() end)
            end
            if noclipConn then noclipConn:Disconnect() end
            if bv and bv.Parent then bv:Destroy() end
            if bg and bg.Parent then bg:Destroy() end

            if hrp and handle and handle.Parent then
                pcall(function() char:PivotTo(targetCF) end)
                hrp.CFrame = targetCF
                if firetouchinterest then
                    pcall(function()
                        firetouchinterest(hrp, handle, 0)
                        task.wait(0.05)
                        firetouchinterest(hrp, handle, 1)
                    end)
                end
            end
        end
        local fruitESPMap = {}
        local function UpdateFruitESP()
            pcall(function()
                local char = LocalPlayer.Character
                local head = char and char:FindFirstChild("Head")
                local fruits = GetSpawnedFruits()
                local currentHandles = {}
                if _G.FruitESP then
                    for _, fruitData in ipairs(fruits) do
                        local handle = fruitData.Handle
                        local v = fruitData.Object
                        if handle and v and isStillSpawned(v) then
                            currentHandles[handle] = true
                            local espName = "FruitESP_" .. fruitSessionID
                            local bill = handle:FindFirstChild(espName)
                            local dist = head and math.floor((head.Position - handle.Position).Magnitude) or 0
                            if not bill then
                                bill = Instance.new("BillboardGui")
                                bill.Name = espName
                                bill.Size = UDim2.new(0, 200, 0, 45)
                                bill.ExtentsOffset = Vector3.new(0, 2.5, 0)
                                bill.AlwaysOnTop = true
                                bill.Adornee = handle
                                bill.Parent = handle
                                local text = Instance.new("TextLabel", bill)
                                text.Name = "ESPLabel"
                                text.Size = UDim2.new(1, 0, 1, 0)
                                text.BackgroundTransparency = 1
                                text.TextSize = 13
                                text.Font = Enum.Font.GothamBold
                                text.TextColor3 = Color3.fromRGB(240, 240, 255)
                                text.TextStrokeTransparency = 0
                                fruitESPMap[handle] = bill
                            end
                            local lbl = bill:FindFirstChild("ESPLabel")
                            if lbl then
                                lbl.Text = string.format("[Fruit] %s\n[%d studs / %dm]", v.Name, dist, math.floor(dist / 3))
                            end
                        end
                    end
                end
                for handle, bill in pairs(fruitESPMap) do
                    if not currentHandles[handle] or not _G.FruitESP then
                        pcall(function() if bill then bill:Destroy() end end)
                        fruitESPMap[handle] = nil
                    end
                end
            end)
        end
        task.spawn(function()
            while isCurrentSession() do
                task.wait(0.5)
                if _G.FruitESP then
                    UpdateFruitESP()
                elseif next(fruitESPMap) ~= nil then
                    for handle, bill in pairs(fruitESPMap) do
                        pcall(function() if bill then bill:Destroy() end end)
                        fruitESPMap[handle] = nil
                    end
                end
            end
        end)

        workspace.ChildAdded:Connect(function(child)
            if not isCurrentSession() then return end
            if (child:IsA("Tool") or child:IsA("Model")) and string.find(child.Name, "Fruit") then
                task.spawn(function()
                    task.wait(0.4)
                    if child and child.Parent and isStillSpawned(child) then
                        if _G.FruitESP then
                            UpdateFruitESP()
                        end
                    end
                end)
            end
        end)

        local function IsPhysicalFruit(tool)
            if not (tool and tool:IsA("Tool")) then return false end
            return string.find(tool.Name, "Fruit") ~= nil
        end
        local function HasFruitInInventory()
            if LocalPlayer.Character then
                for _, item in ipairs(LocalPlayer.Character:GetChildren()) do
                    if IsPhysicalFruit(item) then return true, item end
                end
            end
            local bp = LocalPlayer:FindFirstChild("Backpack")
            if bp then
                for _, item in ipairs(bp:GetChildren()) do
                    if IsPhysicalFruit(item) then return true, item end
                end
            end
            return false, nil
        end
        local function StoreFruit(fruitTool)
            if not fruitTool then return false end
            local ok, res = pcall(function()
                local commF = GetCommF()
                if not commF then return false end
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")

                if fruitTool.Parent ~= char and hum then
                    hum:EquipTool(fruitTool)
                    task.wait(0.18)
                end
                local origName = fruitTool:GetAttribute("OriginalName") or fruitTool.Name
                local r = commF:InvokeServer("StoreFruit", origName, fruitTool)
                if not r then
                    commF:InvokeServer("StoreFruit", fruitTool.Name, fruitTool)
                end
                notifyToggle("Auto Store: " .. tostring(fruitTool.Name), true)
                return true
            end)
            return ok and res
        end
        task.spawn(function()
            while isCurrentSession() do
                task.wait(0.5)
                if _G.AutoStoreFruit and HasFruitInInventory() then
                    local has, fruitTool = HasFruitInInventory()
                    if has and fruitTool then
                        StoreFruit(fruitTool)
                    end
                end
            end
        end)
        collectorThread = task.spawn(function()
            local initialWait = 3.0
            while isCurrentSession() do
                task.wait(0.5)
                if _G.AutoCollectHop and not isHopping then
                    if initialWait > 0 then
                        currentStatusText = (CurrentLang == "ES") and "Buscando frutas en el servidor..." or "Checking server for fruits..."
                        task.wait(initialWait)
                        initialWait = 0
                    end
                    local fruits = GetSpawnedFruits()
                    if #fruits > 0 then
                        for _, fData in ipairs(fruits) do
                            if not _G.AutoCollectHop then break end
                            local fObj = fData.Object
                            local fName = resolveRealFruitName(fObj)
                            currentStatusText = (CurrentLang == "ES") and ("Recogiendo: " .. fName) or ("Collecting: " .. fName)
                            FlyToFruit(fData.Handle)
                            task.wait(0.5)
                            local has, fTool = HasFruitInInventory()
                            if has and fTool then
                                StoreFruit(fTool)
                                _G.TotalFruitsCollected = (_G.TotalFruitsCollected or 0) + 1
                            end
                        end
                    else
                        if _G.HopEnabled and not isHopping then
                            currentStatusText = (CurrentLang == "ES") and "Buscando servidor con frutas..." or "Searching server with fruits..."
                            isHopping = true
                            executeFruitHop()
                            task.wait(35)
                            isHopping = false
                        else
                            currentStatusText = (CurrentLang == "ES") and "Sin frutas (Esperando fruta / Job ID en Discord)..." or "No fruits (Waiting for fruit / Discord Job ID)..."
                        end
                    end
                else
                    initialWait = 0
                    currentStatusText = _G.AutoCollectHop and ((CurrentLang == "ES") and "Ejecutando" or "Running") or ((CurrentLang == "ES") and "Inactivo (Haz clic en Iniciar)" or "Idle (Click Start)")
                end
            end
        end)
        task.spawn(function()
            while isCurrentSession() do
                task.wait(0.5)
                if statusLbl and statusLbl.Parent then
                    statusLbl.Text = string.format("%s: %s | %s: %d", (CurrentLang == "ES") and "Estado" or "Status", currentStatusText, (CurrentLang == "ES") and "Frutas" or "Fruits", _G.TotalFruitsCollected or 0)
                end
            end
        end)
    end)
end
do
    local abToggleBtnRef = nil
    local abStatusLblRef = nil
    local abToggleBtnStroke = nil
    local function autoBusoAndPvPRespawn()
        if not (FeatureStates["AutoBuso"] or Settings.autoBuso) then return end
        pcall(function()
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            local commF = remotes and remotes:FindFirstChild("CommF_")
            if commF then
                local char = LocalPlayer.Character
                if char and not char:FindFirstChild("HasBuso") and char:GetAttribute("HasBuso") ~= true then
                    commF:InvokeServer("Buso")
                end
            end
        end)
    end
    LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.spawn(function()
            task.wait(1.2)
            if FeatureStates["AutoBuso"] or Settings.autoBuso then autoBusoAndPvPRespawn() end
            task.wait(2.0)
            if FeatureStates["AutoBuso"] or Settings.autoBuso then autoBusoAndPvPRespawn() end
        end)
    end)
    local bountyEpoch = 0
    local bountyConnections = {}
    local function disconnectBounty()
        bountyEpoch += 1
        for _, conn in ipairs(bountyConnections) do pcall(function() conn:Disconnect() end) end
        table.clear(bountyConnections)
    end
    local function stopSpookyAutoBountyExact()
        disconnectBounty()
        getgenv().SpookyAutoBountyRunning = false
        getgenv().targ = nil
        pcall(function()
            if tween then
                tween:Cancel()
            end
        end)
        pcall(function()
            local lp = game:GetService("Players").LocalPlayer
            local char = lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp and hrp:FindFirstChild("Hold") then
                hrp.Hold:Destroy()
            end
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                workspace.CurrentCamera.CameraSubject = hum
            end
        end)
        pcall(function()
            if DisableESP then
                DisableESP()
            end
        end)
        pcall(function()
            local pGui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
            local existing = pGui and pGui:FindFirstChild("Spooky_AutoBounty")
            if existing then
                existing.Enabled = false
                existing:Destroy()
            end
        end)
        pcall(function()
            if _G.CleanupAutoBountyTweenAndPart then
                _G.CleanupAutoBountyTweenAndPart()
            end
        end)
        pcall(function()
            if _G.StopAutoBountyNoclip then
                _G.StopAutoBountyNoclip()
            end
        end)
        pcall(function()
            local waterPlane = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("WaterBase-Plane")
            if waterPlane and not (FeatureStates and FeatureStates["WalkOnWater"]) then
                waterPlane.CanCollide = false
                waterPlane.Size = Vector3.new(1000, 80, 1000)
            end
        end)
        if abToggleBtnRef then
            abToggleBtnRef.Text = (CurrentLang == "ES") and "Iniciar Auto Bounty" or "Start Auto Bounty"
            abToggleBtnRef.BackgroundColor3 = Color3.fromRGB(21, 21, 21)
            if abToggleBtnStroke then
                abToggleBtnStroke.Color = Color3.fromRGB(47, 47, 47)
            end
        end
        if abStatusLblRef then
            abStatusLblRef.Text = (CurrentLang == "ES") and "Estado: Inactivo / Detenido" or "Status: Inactive / Stopped"
            abStatusLblRef.TextColor3 = Color3.fromRGB(190, 190, 205)
        end
        notifyToggle("Fatal Auto Bounty Stopped!", false)
    end
    _G.stopSpookyAutoBountyExact = stopSpookyAutoBountyExact
    getgenv().StopSpookyAutoBountyExact = stopSpookyAutoBountyExact
    local function runSpookyAutoBountyExact()
        if getgenv().SpookyAutoBountyRunning then
            notifyToggle("Auto Bounty is already running!", true)
            return
        end
        disconnectBounty()
        local runEpoch = bountyEpoch
        getgenv().SpookyAutoBountyRunning = true
        getgenv().checked = {}
        getgenv().targ = nil
        getgenv().target = nil
        getgenv().HealingInSky = false
        getgenv().CancelHealing = false
        getgenv().NoDamageRunning = false
        getgenv().AutoBountyReachedTarget = false
        getgenv().safeZoneWaitRetries = 0
        local function isBountyCurrent()
            return isCurrentSession() and bountyEpoch == runEpoch and getgenv().SpookyAutoBountyRunning == true
        end
        local function bountyConnect(signal, callback)
            if not isBountyCurrent() then return nil end
            local conn = signal:Connect(function(...)
                if isBountyCurrent() then callback(...) end
            end)
            table.insert(bountyConnections, conn)
            return conn
        end
        task.spawn(function() if isBountyCurrent() then autoBusoAndPvPRespawn() end end)
        if abToggleBtnRef then
            abToggleBtnRef.Text = (CurrentLang == "ES") and "Detener Auto Bounty" or "Stop Auto Bounty"
            abToggleBtnRef.BackgroundColor3 = Color3.fromRGB(27, 27, 27)
            if abToggleBtnStroke then
                abToggleBtnStroke.Color = Color3.fromRGB(95, 42, 56)
            end
        end
        if abStatusLblRef then
            abStatusLblRef.Text = (CurrentLang == "ES") and "Estado: Cazando Objetivos..." or "Status: Hunting Targets..."
            abStatusLblRef.TextColor3 = Color3.fromRGB(245, 245, 255)
        end
        task.spawn(function()
    if not isBountyCurrent() then return end
    local initialized,initError=pcall(function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")
local Workspace = game:GetService("Workspace")
local Camera = Workspace.CurrentCamera
local LocalPlayer = Players.LocalPlayer
local lp = LocalPlayer
local tween = nil
getgenv().checked = getgenv().checked or {}
function hasValue(array, targetString)
    if not array then return false end
    for _, value in ipairs(array) do
        if value == targetString then
            return true
        end
    end
    return false
end
getgenv().hasValue = hasValue
local function AX_ReadPvPState(target)
    if _G.SpookyPvPAllowed then return _G.SpookyPvPAllowed(target) end
    if not target then return false end
    local ok, pvpOn = pcall(function()
        if target:IsA("Player") and target:GetAttribute("PvpDisabled") == true then
            return false
        end
        local char = target.Character or (target:IsA("Model") and target)
        if char then
            if char:FindFirstChildOfClass("ForceField") then
                return false
            end
            if char:GetAttribute("PvpDisabled") == true then
                return false
            end
        end
        return true
    end)
    return ok and pvpOn
end
local function isTargetProtected(targetPlayer)
    if not targetPlayer then return true end
    return not AX_ReadPvPState(targetPlayer)
end
local function AX_InSafeZone(target)
    if _G.SpookyInSafeZone then return _G.SpookyInSafeZone(target) end
    if not target then return false end
    local ok, inZone = pcall(function()
        local char = target.Character or (target:IsA("Model") and target)
        if not char then return false end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local hum = char:FindFirstChild("Humanoid")
        if hum and hum.Sit == true then return true end
        if char:FindFirstChildOfClass("ForceField") then return true end
        if char:GetAttribute("SafeZone") == true then return true end
        if target:IsA("Player") and target:GetAttribute("SafeZone") == true then return true end
        local wo = workspace:FindFirstChild("_WorldOrigin")
        if not wo then return false end
        local safeZones = wo:FindFirstChild("SafeZones")
        if safeZones then
            for _, zone in pairs(safeZones:GetChildren()) do
                if zone:IsA("BasePart") then
                    local mesh = zone:FindFirstChild("Mesh")
                    local radius = 0
                    if mesh and mesh:IsA("SpecialMesh") then
                        radius = (zone.Size.X * mesh.Scale.X) / 2
                    else
                        radius = math.min(zone.Size.X, zone.Size.Z) / 2
                    end
                    if radius > 500 then radius = 350 end
                    if radius <= 0 then radius = 350 end
                    if (zone.Position - hrp.Position).Magnitude <= radius then
                        return true
                    end
                end
            end
        end
        return false
    end)
    return ok and inZone
end
local function isAllyWithMe(targetplayer)
    local myGui = LocalPlayer:FindFirstChild("PlayerGui")
    if not myGui then return false end
    local scrolling = myGui:FindFirstChild("Main") and myGui.Main:FindFirstChild("Allies")
        and myGui.Main.Allies:FindFirstChild("Container") and myGui.Main.Allies.Container:FindFirstChild("Allies")
        and myGui.Main.Allies.Container.Allies:FindFirstChild("ScrollingFrame")
    if scrolling then
        for _, frame in pairs(scrolling:GetDescendants()) do
            if frame:IsA("ImageButton") and frame.Name == targetplayer.Name then return true end
        end
    end
    return false
end
local function isEnemy(targetplayer)
    if _G.SpookyIsEnemy then return _G.SpookyIsEnemy(targetplayer) end
    if not targetplayer or targetplayer == LocalPlayer then return false end
    local myTeam = LocalPlayer.Team
    local targetTeam = targetplayer.Team
    if myTeam and targetTeam then
        if myTeam.Name == "Pirates" and targetTeam.Name == "Marines" then return true
        elseif myTeam.Name == "Marines" and targetTeam.Name == "Pirates" then return true end
        if myTeam.Name == "Pirates" and targetTeam.Name == "Pirates" then return not isAllyWithMe(targetplayer) end
        if myTeam.Name == "Marines" and targetTeam.Name == "Marines" then return false end
    end
    return true
end
local function isLocalPvpDisabled()
    local ok, dis = pcall(function()
        if LocalPlayer:GetAttribute("PvpDisabled") == true then return true end
        local main = LocalPlayer.PlayerGui:FindFirstChild("Main")
        if not main then return false end
        local bList = main:FindFirstChild("BottomHUDList")
        if bList and bList:FindFirstChild("PvpDisabled") and bList.PvpDisabled.Visible == true then
            return true
        end
        if main:FindFirstChild("PvpDisabled") and main.PvpDisabled.Visible == true then
            return true
        end
        return false
    end)
    return ok and dis
end
