    local function answerAnyQuestionLocally(query)
        local q = string.lower(query or "")
        local ans = ""
        local code = ""

        local n1, op, n2 = string.match(q, "(%d+%.?%d*)%s*([%+%-%*%/%^])%s*(%d+%.?%d*)")
        if n1 and op and n2 then
            local num1 = tonumber(n1)
            local num2 = tonumber(n2)
            if num1 and num2 then
                local res = 0
                if op == "+" then res = num1 + num2
                elseif op == "-" then res = num1 - num2
                elseif op == "*" then res = num1 * num2
                elseif op == "/" then res = (num2 ~= 0) and (num1 / num2) or 0
                elseif op == "^" then res = num1 ^ num2
                end
                ans = (CurrentLang == "ES") and string.format("Calculo: %s %s %s = %s", n1, op, n2, tostring(res)) or string.format("Calculation: %s %s %s = %s", n1, op, n2, tostring(res))
                return ans, code
            end
        end

        local sqrtNum = string.match(q, "raiz%s+cuadrada%s+de%s+(%d+%.?%d*)") or string.match(q, "sqrt%s*%(?(%d+%.?%d*)%)?") or string.match(q, "square%s+root%s+of%s+(%d+%.?%d*)")
        if sqrtNum and tonumber(sqrtNum) then
            local val = math.sqrt(tonumber(sqrtNum))
            ans = (CurrentLang == "ES") and string.format("La raiz cuadrada de %s es %s", sqrtNum, tostring(val)) or string.format("The square root of %s is %s", sqrtNum, tostring(val))
            return ans, code
        end

        local pct, total = string.match(q, "(%d+%.?%d*)%%%s+de%s+(%d+%.?%d*)") or string.match(q, "(%d+%.?%d*)%%%s+of%s+(%d+%.?%d*)")
        if pct and total and tonumber(pct) and tonumber(total) then
            local val = (tonumber(pct) / 100) * tonumber(total)
            ans = (CurrentLang == "ES") and string.format("El %s%% de %s es %s", pct, total, tostring(val)) or string.format("%s%% of %s is %s", pct, total, tostring(val))
            return ans, code
        end

        if string.find(q, "fly") or string.find(q, "volar") or string.find(q, "vuelo") then
            code = [===[local lp = game:GetService("Players").LocalPlayer
local mouse = lp:GetMouse()
local flying = true
local speed = 65
local bv = Instance.new("BodyVelocity")
bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
bv.Velocity = Vector3.zero
local bg = Instance.new("BodyGyro")
bg.MaxTorque = Vector3.new(1e5, 1e5, 1e5)
local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
if hrp then bv.Parent = hrp; bg.Parent = hrp end
local conn = game:GetService("RunService").RenderStepped:Connect(function()
    if flying and hrp and bv and bg then
        local cam = workspace.CurrentCamera
        bg.CFrame = cam.CFrame
        local dir = Vector3.zero
        local uis = game:GetService("UserInputService")
        if uis:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
        if uis:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
        if uis:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
        if uis:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
        if uis:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0, 1, 0) end
        if uis:IsKeyDown(Enum.KeyCode.LeftShift) then dir = dir - Vector3.new(0, 1, 0) end
        bv.Velocity = dir.Unit * speed
    end
end)
mouse.KeyDown:Connect(function(k)
    if k == "e" then
        flying = not flying
        if not flying then bv.Velocity = Vector3.zero end
    end
end)]===]
            ans = (CurrentLang == "ES") and ("Aqui tienes un script de Fly completo con velocidad ajustable y tecla E para activar/desactivar:\n\n```lua\n" .. code .. "\n```\n\nPresiona 'Execute Code' para probarlo de inmediato!") or ("Here is a complete Fly script with adjustable speed and E keybind toggle:\n\n```lua\n" .. code .. "\n```\n\nClick 'Execute Code' to run it immediately!")
            return ans, code
