    local ignoredHUDNames = {
        "health", "energy", "stamina", "level", "beli", "fragment", "stat",
        "compass", "quest", "menu", "dialogue", "top", "topbar", "bar",
        "characteravatar", "profile", "avatar", "crew", "leaderboard"
    }

    local function isAllowedHUDButton(btn)
        if not btn or not btn:IsA("GuiObject") then return false end
        local n = string.lower(btn.Name)
        for _, ign in ipairs(ignoredHUDNames) do
            if string.find(n, ign) then return false end
        end
        return true
    end

    local function getBloxFruitsControlButtons()
        local btns = {}
        local seen = {}
        local pGui = LocalPlayer:FindFirstChild("PlayerGui")
        if not pGui then return btns end

        local function addBtn(b, customName)
            if not b or not b:IsA("GuiObject") then return end
            local key = customName or b.Name
            if seen[key] or seen[b] then return end
            seen[key] = true
            seen[b] = true
            table.insert(btns, b)
        end

        local main = pGui:FindFirstChild("Main")
        if main then
            local skills = main:FindFirstChild("Skills")
            if skills then
                addBtn(skills, "PC_SkillsBar")
                for _, sChild in ipairs(skills:GetChildren()) do
                    if sChild:IsA("GuiObject") and (sChild.Name == "Z" or sChild.Name == "X" or sChild.Name == "C" or sChild.Name == "V" or sChild.Name == "F") then
                        addBtn(sChild, "Skill_" .. sChild.Name)
                    end
                end
            end
            local hotbar = main:FindFirstChild("Hotbar")
            if hotbar then addBtn(hotbar, "PC_Hotbar") end
            local hp = main:FindFirstChild("Health")
            if hp then addBtn(hp, "PC_Health") end
            local ep = main:FindFirstChild("Energy")
            if ep then addBtn(ep, "PC_Energy") end
            local compass = main:FindFirstChild("Compass")
            if compass then addBtn(compass, "PC_Compass") end
            local bounty = main:FindFirstChild("Bounty")
            if bounty then addBtn(bounty, "PC_Bounty") end
        end

        local backpackGui = pGui:FindFirstChild("Backpack")
        if backpackGui then
            local hb = backpackGui:FindFirstChild("Hotbar") or backpackGui:FindFirstChild("Container")
            if hb and hb:IsA("GuiObject") then addBtn(hb, "Backpack_Hotbar") end
        end

        local touchGui = pGui:FindFirstChild("TouchGui")
        if touchGui then
            local tcFrame = touchGui:FindFirstChild("TouchControlFrame")
            if tcFrame then
                local jBtn = tcFrame:FindFirstChild("JumpButton")
                if jBtn and isAllowedHUDButton(jBtn) then addBtn(jBtn, "Jump") end
            end
        end

        local cag = pGui:FindFirstChild("ContextActionGui")
        if cag then
            local cbf = cag:FindFirstChild("ContextButtonFrame")
            if cbf then
                for _, ch in ipairs(cbf:GetChildren()) do
                    if ch:IsA("GuiObject") and isAllowedHUDButton(ch) then
                        addBtn(ch)
                    end
                end
            end
        end

        local mcb = pGui:FindFirstChild("MobileContextButtons")
        if mcb then
            local cbf = mcb:FindFirstChild("ContextButtonFrame") or mcb
            for _, ch in ipairs(cbf:GetChildren()) do
                if ch:IsA("GuiObject") and isAllowedHUDButton(ch) then
                    addBtn(ch)
                end
            end
        end

        if main then
            for _, ch in ipairs(main:GetChildren()) do
                local nm = string.lower(ch.Name)
                if (nm:find("dash") or nm:find("jump") or nm:find("skill") or nm:find("mobilebutton") or nm:find("combatbutton")) and ch:IsA("GuiObject") then
                    if isAllowedHUDButton(ch) then addBtn(ch) end
                end
            end
        end

        return btns
    end    local function cleanupHudOverlays()
    _G.cleanupHudOverlays = cleanupHudOverlays
        _G.Spooky_CleanupHudOverlays = cleanupHudOverlays
        for _, ov in ipairs(hudOverlays) do
            if ov and ov.Parent then pcall(function() ov:Destroy() end) end
        end
        table.clear(hudOverlays)
        for _, c in ipairs(activeDragConns) do
            if c and c.Disconnect then pcall(function() c:Disconnect() end) end
        end
        table.clear(activeDragConns)
    end

    local function saveControlsLayoutToFile()
        pcall(function()
            if writefile then
                local json = HttpService:JSONEncode(_G.Spooky_ControlsLayout)
                writefile("RiftWtf_BF_ControlsLayout.json", json)
            end
        end)
    end

    local function loadControlsLayoutFromFile()
        pcall(function()
            local json = nil
            if isfile and isfile("RiftWtf_BF_ControlsLayout.json") and readfile then
                json = readfile("RiftWtf_BF_ControlsLayout.json")
            end
            if json and json ~= "" then
                local ok, data = pcall(function() return HttpService:JSONDecode(json) end)
                if ok and type(data) == "table" then
                    _G.Spooky_ControlsLayout = data
                    for _, btn in ipairs(getBloxFruitsControlButtons()) do
                        local saved = _G.Spooky_ControlsLayout[btn.Name]
                        if saved then
                            if saved.scaleX and saved.scaleY then
                                btn.Position = UDim2.new(saved.scaleX, saved.offsetX or 0, saved.scaleY, saved.offsetY or 0)
                            end
                            if saved.scale then
                                local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
                                s.Scale = saved.scale
                            end
                        end
                    end
                end
            end
        end)
    end
    local editOverlayBar = nil
    local function cancelEditControlsMode()
        isEditingControls = false
        cleanupHudOverlays()
        if editControlsBtn then
            local lbl = editControlsBtn:FindFirstChildOfClass("TextLabel")
            if lbl then lbl.Text = (CurrentLang == "ES") and "Desbloquear Arrastre (Editar)" or "Unlock Dragging (Edit Controls)" end
            editControlsBtn.BackgroundColor3 = Color3.fromRGB(21, 21, 21)
        end
        if editOverlayBar then editOverlayBar.Visible = false end
        for name, pos in pairs(originalControlsLayout) do
            for _, b in ipairs(getBloxFruitsControlButtons()) do
                if b.Name == name then b.Position = pos end
            end
        end
        notifyToggle((CurrentLang == "ES") and "Edición HUD cancelada (Sin guardar)" or "HUD Edit Cancelled (Changes Discarded)", false)
    end

    local function setEditControlsMode(enabled)
        isEditingControls = enabled
        cleanupHudOverlays()
        if editControlsBtn then
            local lbl = editControlsBtn:FindFirstChildOfClass("TextLabel")
            if lbl then
                lbl.Text = enabled and ((CurrentLang == "ES") and "Bloquear y Guardar" or "Lock & Save Layout") or ((CurrentLang == "ES") and "Desbloquear Arrastre (Editar)" or "Unlock Dragging (Edit Controls)")
            end
            editControlsBtn.BackgroundColor3 = enabled and Color3.fromRGB(32, 32, 32) or Color3.fromRGB(19, 19, 19)
        end
        if not enabled then
            if editOverlayBar then editOverlayBar.Visible = false end
            saveControlsLayoutToFile()
            notifyToggle((CurrentLang == "ES") and "HUD Guardado con Éxito!" or "HUD Layout Locked & Saved!", true)
            return
        end
        if not editOverlayBar then
            local pGui = LocalPlayer:FindFirstChild("PlayerGui") or game:GetService("CoreGui")
            local sg = Instance.new("ScreenGui")
            sg.Name = "Spooky_HUDOverlay"
            sg.ResetOnSpawn = false
            sg.IgnoreGuiInset = true
            safeParent(sg)
            local bar = Instance.new("Frame", sg)
            bar.Name = "TopBanner"
            bar.Size = UDim2.new(0, 440, 0, 42)
            bar.Position = UDim2.new(0.5, -220, 0, 15)
            bar.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
            bar.BackgroundTransparency = 0.15
            bar.BorderSizePixel = 0
            Instance.new("UICorner", bar).CornerRadius = UDim.new(0, 8)
            local st = Instance.new("UIStroke", bar)
            st.Color = Color3.fromRGB(53, 53, 53)
            st.Thickness = 1.2
            local lbl = Instance.new("TextLabel", bar)
            lbl.Size = UDim2.new(0, 180, 1, 0)
            lbl.Position = UDim2.new(0, 12, 0, 0)
            lbl.BackgroundTransparency = 1
            lbl.Font = Enum.Font.GothamBold
            lbl.Text = (CurrentLang == "ES") and "Arrastre HUD Activo (PC / Touch)" or "HUD Drag Active (PC / Touch)"
            lbl.TextSize = 11.5
            lbl.TextColor3 = Color3.fromRGB(240, 240, 250)
            lbl.TextXAlignment = Enum.TextXAlignment.Left

            local cancelBtn = Instance.new("TextButton", bar)
            cancelBtn.Size = UDim2.new(0, 100, 0, 28)
            cancelBtn.Position = UDim2.new(1, -220, 0, 7)
            cancelBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
            cancelBtn.Text = (CurrentLang == "ES") and "Descartar" or "Discard"
            cancelBtn.TextColor3 = Color3.fromRGB(255, 200, 210)
            cancelBtn.Font = Enum.Font.GothamBold
            cancelBtn.TextSize = 11
            Instance.new("UICorner", cancelBtn).CornerRadius = UDim.new(0, 6)
            local cStk = Instance.new("UIStroke", cancelBtn)
            cStk.Color = Color3.fromRGB(48, 48, 48)
            cancelBtn.MouseButton1Click:Connect(cancelEditControlsMode)

            local doneBtn = Instance.new("TextButton", bar)
            doneBtn.Size = UDim2.new(0, 105, 0, 28)
            doneBtn.Position = UDim2.new(1, -114, 0, 7)
            doneBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
            doneBtn.Text = (CurrentLang == "ES") and "Guardar" or "Save & Lock"
            doneBtn.TextColor3 = Color3.fromRGB(240, 245, 255)
            doneBtn.Font = Enum.Font.GothamBold
            doneBtn.TextSize = 11
            Instance.new("UICorner", doneBtn).CornerRadius = UDim.new(0, 6)
            local dStk = Instance.new("UIStroke", doneBtn)
            dStk.Color = Color3.fromRGB(180, 195, 230)
            doneBtn.MouseButton1Click:Connect(function()
                setEditControlsMode(false)
            end)
            editOverlayBar = bar
        else
            editOverlayBar.Visible = true
        end

        local targetButtons = getBloxFruitsControlButtons()
        local overlayGui = editOverlayBar.Parent
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(800, 600)
        for _, btn in ipairs(targetButtons) do
            if not originalControlsLayout[btn.Name] then
                originalControlsLayout[btn.Name] = btn.Position
            end
            local posX = btn.AbsolutePosition.X
            local posY = btn.AbsolutePosition.Y
            local sizeW = math.max(btn.AbsoluteSize.X, 36)
            local sizeH = math.max(btn.AbsoluteSize.Y, 36)
            if posX <= 0 and posY <= 0 then
                if btn.Position.X.Scale > 0 or btn.Position.Y.Scale > 0 or btn.Position.X.Offset > 0 or btn.Position.Y.Offset > 0 then
                    posX = math.clamp(btn.Position.X.Scale * vp.X + btn.Position.X.Offset, 10, vp.X - 70)
                    posY = math.clamp(btn.Position.Y.Scale * vp.Y + btn.Position.Y.Offset, 10, vp.Y - 70)
                else
                    local defaultOffsets = {
                        ["Z"] = {x = -130, y = -190}, ["Skill_Z"] = {x = -130, y = -190},
                        ["X"] = {x = -70, y = -190},  ["Skill_X"] = {x = -70, y = -190},
                        ["C"] = {x = -130, y = -130}, ["Skill_C"] = {x = -130, y = -130},
                        ["V"] = {x = -70, y = -130},  ["Skill_V"] = {x = -70, y = -130},
                        ["F"] = {x = -190, y = -160}, ["Skill_F"] = {x = -190, y = -160},
                        ["Dash"] = {x = -190, y = -95},
                        ["Jump"] = {x = -70, y = -70},
                    }
                    local off = defaultOffsets[btn.Name] or {x = -100, y = -100}
                    posX = vp.X + off.x
                    posY = vp.Y + off.y
                end
            end
            local ov = Instance.new("TextButton", overlayGui)
            ov.Name = "Overlay_" .. btn.Name
            ov.Size = UDim2.new(0, sizeW, 0, sizeH)
            ov.Position = UDim2.new(0, posX, 0, posY)
            ov.BackgroundColor3 = Color3.fromRGB(16, 16, 16)
            ov.BackgroundTransparency = 0.35
            ov.BorderSizePixel = 0
            ov.Active = true
            ov.Selectable = false
            ov.ZIndex = 250
            local cleanName = btn.Name:gsub("ContextAction", ""):gsub("Button", ""):gsub("Mobile", "")
            if cleanName == "Jump" or btn.Name == "JumpButton" then cleanName = "Jump"
            elseif cleanName:find("Dash") then cleanName = "Dash"
            end
            if #cleanName > 9 then cleanName = cleanName:sub(1, 7) .. ".." end
            ov.Text = cleanName
            ov.TextColor3 = Color3.fromRGB(245, 240, 255)
            ov.TextSize = 11
            ov.Font = Enum.Font.GothamBold
            Instance.new("UICorner", ov).CornerRadius = UDim.new(0, 6)
            local ovStroke = Instance.new("UIStroke", ov)
            ovStroke.Color = Color3.fromRGB(160, 175, 215)
            ovStroke.Thickness = 1.2
            table.insert(hudOverlays, ov)

            local dragging = false
            local dragStart = nil
            local startBtnPos = nil
            local startOvPos = nil
            local c1 = ov.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    local mPos = UserInputService:GetMouseLocation()
                    dragStart = Vector3.new(mPos.X, mPos.Y, 0)
                    startBtnPos = btn.Position
                    startOvPos = ov.Position
                end
            end)
            local c2 = UserInputService.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local mPos = UserInputService:GetMouseLocation()
                    local curPos = Vector3.new(mPos.X, mPos.Y, 0)
                    local deltaX = curPos.X - dragStart.X
                    local deltaY = curPos.Y - dragStart.Y
                    btn.Position = UDim2.new(
                        startBtnPos.X.Scale,
                        startBtnPos.X.Offset + deltaX,
                        startBtnPos.Y.Scale,
                        startBtnPos.Y.Offset + deltaY
                    )
                    ov.Position = UDim2.new(
                        startOvPos.X.Scale,
                        startOvPos.X.Offset + deltaX,
                        startOvPos.Y.Scale,
                        startOvPos.Y.Offset + deltaY
                    )
                end
            end)
            local c3 = UserInputService.InputEnded:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
                    dragging = false
                    _G.Spooky_ControlsLayout[btn.Name] = _G.Spooky_ControlsLayout[btn.Name] or {}
                    _G.Spooky_ControlsLayout[btn.Name].scaleX = btn.Position.X.Scale
                    _G.Spooky_ControlsLayout[btn.Name].offsetX = btn.Position.X.Offset
                    _G.Spooky_ControlsLayout[btn.Name].scaleY = btn.Position.Y.Scale
                    _G.Spooky_ControlsLayout[btn.Name].offsetY = btn.Position.Y.Offset
                end
            end)
            table.insert(activeDragConns, c1)
            table.insert(activeDragConns, c2)
            table.insert(activeDragConns, c3)
        end
        notifyToggle((CurrentLang == "ES") and "HUD Desbloqueado! Arrastra los controles libremente (Touch / Mouse)." or "HUD Unlocked! Drag buttons freely (Touch / Mouse).", true)
    end

    local editCard = makeCard(HUDPage, "HUD Move", "Mover HUD", 74, 2)
    editControlsBtn = createActionButton(editCard, "Unlock Dragging", "Desbloquear", UDim2.new(0.48, -4, 0, 32), UDim2.new(0, 10, 0, 28), function()
        setEditControlsMode(not isEditingControls)
    end)

    createActionButton(editCard, "Reset Layout", "Restablecer", UDim2.new(0.48, -4, 0, 32), UDim2.new(0.5, 4, 0, 28), function()
        if isfile and isfile("RiftWtf_BF_ControlsLayout.json") and delfile then
            pcall(function() delfile("RiftWtf_BF_ControlsLayout.json") end)
        end
        _G.Spooky_ControlsLayout = {}
        for name, pos in pairs(originalControlsLayout) do
            for _, b in ipairs(getBloxFruitsControlButtons()) do
                if b.Name == name then b.Position = pos end
            end
        end
        for _, b in ipairs(getBloxFruitsControlButtons()) do
            local s = b:FindFirstChildOfClass("UIScale")
            if s then s.Scale = 1.0 end
        end
        notifyToggle((CurrentLang == "ES") and "Diseño HUD restablecido" or "HUD Layout Reset", true)
    end)

    local scaleCard = makeCard(HUDPage, "HUD Scale", "Escala HUD", 116, 82)
    createSlider(scaleCard, "Button Scale", "Escala de Botones", 0.50, 2.00, (_G.Spooky_ControlsLayout and _G.Spooky_ControlsLayout.globalScale) or 1.0, true, 0.05, "x", function(val)
        _G.Spooky_ControlsLayout.globalScale = val
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = val
        end
        saveControlsLayoutToFile()
    end, UDim2.new(0, 8, 0, 28))

    local bsW = UDim2.new(0.23, 0, 0, 26)
    createActionButton(scaleCard, "0.80x", "0.80x", bsW, UDim2.new(0, 8, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 0.80
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 0.80
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 0.80x", true)
    end)
    createActionButton(scaleCard, "1.00x", "1.00x (Def)", bsW, UDim2.new(0.25, 6, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 1.00
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 1.00
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 1.00x", true)
    end)
    createActionButton(scaleCard, "1.25x", "1.25x", bsW, UDim2.new(0.50, 4, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 1.25
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 1.25
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 1.25x", true)
    end)
    createActionButton(scaleCard, "1.50x", "1.50x", bsW, UDim2.new(0.75, 2, 0, 74), function()
        _G.Spooky_ControlsLayout.globalScale = 1.50
        for _, btn in ipairs(getBloxFruitsControlButtons()) do
            local s = btn:FindFirstChildOfClass("UIScale") or Instance.new("UIScale", btn)
            s.Scale = 1.50
        end
        saveControlsLayoutToFile()
        notifyToggle("Button Scale: 1.50x", true)
    end)
    loadControlsLayoutFromFile()
end
do
    local ControlPeoplePage = createScrollPage("ControlPeople_Page", 900)
