    local activeSky = nil
    local rainbowSkyThread = nil
    local origLightingProps = nil
    local origAtmosphereProps = nil
    local activeRainbowSky = nil
    local activeRainbowAtmosphere = nil

    local function enforceSkybox()
        if not FeatureStates["Skybox"] then return end
        if FeatureStates["RainbowSkybox"] then return end
        local sb = SKYBOXES[Settings.skyIdx]
        if sb and sb.bk then
            if not activeSky or activeSky.Parent ~= Lighting then
                if activeSky then activeSky:Destroy() end
                activeSky = Instance.new("Sky", Lighting)
                activeSky.Name = "Spooky_Skybox"
                activeSky.SkyboxBk = sb.bk
                activeSky.SkyboxDn = sb.dn
                activeSky.SkyboxFt = sb.ft
                activeSky.SkyboxLf = sb.lf
                activeSky.SkyboxRt = sb.rt
                activeSky.SkyboxUp = sb.up
            end
        end
    end

    local function stopRainbowSky()
        if rainbowSkyThread then
            pcall(function() task.cancel(rainbowSkyThread) end)
            rainbowSkyThread = nil
        end
        if activeRainbowSky then
            pcall(function() activeRainbowSky:Destroy() end)
            activeRainbowSky = nil
        end
        if activeRainbowAtmosphere then
            pcall(function() activeRainbowAtmosphere:Destroy() end)
            activeRainbowAtmosphere = nil
        end
        if origLightingProps then
            pcall(function()
                Lighting.Ambient = origLightingProps.Ambient
                Lighting.OutdoorAmbient = origLightingProps.OutdoorAmbient
                Lighting.ColorShift_Top = origLightingProps.ColorShift_Top
                Lighting.ColorShift_Bottom = origLightingProps.ColorShift_Bottom
            end)
            origLightingProps = nil
        end
        local atmo = Lighting:FindFirstChildOfClass("Atmosphere")
        if atmo and origAtmosphereProps then
            pcall(function()
                atmo.Color = origAtmosphereProps.Color
                atmo.Decay = origAtmosphereProps.Decay
            end)
            origAtmosphereProps = nil
        end
        if FeatureStates["Skybox"] then
            enforceSkybox()
        end
    end

    local function startRainbowSky()
        stopRainbowSky()
        origLightingProps = {
            Ambient = Lighting.Ambient,
            OutdoorAmbient = Lighting.OutdoorAmbient,
            ColorShift_Top = Lighting.ColorShift_Top,
            ColorShift_Bottom = Lighting.ColorShift_Bottom
        }
        local existingAtmo = Lighting:FindFirstChildOfClass("Atmosphere")
        if existingAtmo then
            origAtmosphereProps = {
                Color = existingAtmo.Color,
                Decay = existingAtmo.Decay
            }
        end

        if activeSky then
            pcall(function() activeSky:Destroy() end)
            activeSky = nil
        end

        activeRainbowSky = Instance.new("Sky")
        activeRainbowSky.Name = "Spooky_RainbowSky"
        activeRainbowSky.CelestialBodiesShown = true
        activeRainbowSky.SkyboxBk = "rbxassetid://16876541778"
        activeRainbowSky.SkyboxDn = "rbxassetid://16876543880"
        activeRainbowSky.SkyboxFt = "rbxassetid://16876546384"
        activeRainbowSky.SkyboxLf = "rbxassetid://16876548320"
        activeRainbowSky.SkyboxRt = "rbxassetid://16876550345"
        activeRainbowSky.SkyboxUp = "rbxassetid://16876552681"
        activeRainbowSky.Parent = Lighting

        local atmo = existingAtmo
        if not atmo then
            atmo = Instance.new("Atmosphere", Lighting)
            atmo.Name = "Spooky_RainbowAtmosphere"
            activeRainbowAtmosphere = atmo
        end

        rainbowSkyThread = task.spawn(function()
            local hue = 0
            while FeatureStates["RainbowSkybox"] and isCurrentSession() do
                hue = (hue + 0.006) % 1
                local rainbowColor = Color3.fromHSV(hue, 0.75, 1)
                local ambientColor = Color3.fromHSV(hue, 0.45, 0.9)
                local decayColor = Color3.fromHSV(hue, 0.85, 0.5)

                pcall(function()
                    Lighting.Ambient = ambientColor
                    Lighting.OutdoorAmbient = rainbowColor
                    Lighting.ColorShift_Top = rainbowColor
                    if atmo and atmo.Parent then
                        atmo.Color = rainbowColor
                        atmo.Decay = decayColor
                    end
                end)
                task.wait(0.06)
            end
        end)
    end

    FeatureCallbacks["RainbowSkybox"] = function(v)
        if v then
            startRainbowSky()
            notifyToggle("Rainbow Skybox: ENABLED", true)
        else
            stopRainbowSky()
            notifyToggle("Rainbow Skybox: DISABLED", false)
        end
    end

    FeatureCallbacks["Skybox"] = function(v)
        if v then
            if not FeatureStates["RainbowSkybox"] then
                enforceSkybox()
            end
        else
            if activeSky then activeSky:Destroy(); activeSky = nil end
        end
    end
    local CLOCK_TIMES = { 12.0, 18.2, 22.0, 0.5, 6.0, 9.0 }
    RunService.Heartbeat:Connect(function()
        if not FeatureStates["DayTime"] and not FeatureStates["Skybox"] then return end
        if FeatureStates["DayTime"] then
            local targetTime = CLOCK_TIMES[Settings.timeIdx] or 12.0
            if Lighting.ClockTime ~= targetTime then
                Lighting.ClockTime = targetTime
            end
        end
        if FeatureStates["Skybox"] and not FeatureStates["RainbowSkybox"] and activeSky and activeSky.Parent ~= Lighting then
            enforceSkybox()
        end
    end)
    local fxCC, fxBloom = nil, nil
    local function ensureShaders()
        if not fxCC then
            fxCC = Instance.new("ColorCorrectionEffect", Lighting)
            fxCC.Name = "Spooky_CC"
            fxBloom = Instance.new("BloomEffect", Lighting)
            fxBloom.Name = "Spooky_Bloom"
        end
    end
    local SHADER_PRESETS = {
        { contrast = 0.15, sat = 0.30, bright = 0.03, bloomI = 0.9 },
        { contrast = 0.18, sat = 0.22, bright = 0.05, bloomI = 1.2 },
        { contrast = 0.08, sat = 0.15, bright = 0.00, bloomI = 0.6 },
        { contrast = 0.22, sat = -0.05, bright = -0.02, bloomI = 1.1 },
        { contrast = 0.12, sat = 0.45, bright = 0.05, bloomI = 0.8 },
        { contrast = 0.14, sat = 0.30, bright = 0.02, bloomI = 1.3 },
        { contrast = 0.15, sat = 0.10, bright = -0.08, bloomI = 0.5 },
        { contrast = 0.10, sat = 0.20, bright = 0.02, bloomI = 1.0 },
    }
    FeatureCallbacks["ShadersVisual"] = function(v)
        if v then
            ensureShaders()
            local p = SHADER_PRESETS[Settings.shaderIdx] or SHADER_PRESETS[1]
            fxCC.Contrast = p.contrast
            fxCC.Saturation = p.sat
            fxCC.Brightness = p.bright
            fxCC.Enabled = true
            fxBloom.Intensity = p.bloomI
            fxBloom.Enabled = true
        else
            if fxCC then fxCC.Enabled = false end
            if fxBloom then fxBloom.Enabled = false end
        end
    end
    local COLOR_FILTERS = {
        { sat = 0, con = 0, bright = 0, tint = Color3.fromRGB(255, 255, 255) },
        { sat = 0.2, con = 0.15, bright = 0.02, tint = Color3.fromRGB(255, 225, 200) },
        { sat = -0.1, con = 0.2, bright = 0.05, tint = Color3.fromRGB(180, 215, 255) },
        { sat = -0.8, con = 0.4, bright = 0.2, tint = Color3.fromRGB(80, 255, 120) },
        { sat = -1.0, con = 0.3, bright = 0, tint = Color3.fromRGB(255, 255, 255) },
    }
    FeatureCallbacks["ColorFilter"] = function(v)
        ensureShaders()
        local cf = COLOR_FILTERS[Settings.filterIdx] or COLOR_FILTERS[1]
        if v then
            fxCC.Saturation = cf.sat
            fxCC.Contrast = cf.con
            fxCC.Brightness = cf.bright
            fxCC.TintColor = cf.tint
            fxCC.Enabled = true
        else fxCC.TintColor = Color3.fromRGB(255, 255, 255) end
    end
    local noObjectsOn = false
    local noObjLoopConn = nil
    local function hideEquippedWeapons()
        local char = LocalPlayer.Character
        if not char then return end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") or child:IsA("Model") or child:IsA("Accessory") then
                local name = string.lower(child.Name)
                if child:IsA("Tool") or name:find("sword") or name:find("blade") or name:find("guitar") or name:find("gun") or name:find("weapon") or name:find("melee") then
                    for _, part in ipairs(child:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.LocalTransparencyModifier = 1
                            part.Transparency = 1
                        elseif part:IsA("Decal") or part:IsA("Texture") then
                            part.Transparency = 1
                        elseif part:IsA("ParticleEmitter") or part:IsA("Beam") or part:IsA("Trail") then
                            part.Enabled = false
                        end
                    end
                end
            end
        end
    end
    local function restoreEquippedWeapons()
        local char = LocalPlayer.Character
        if not char then return end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") or child:IsA("Model") or child:IsA("Accessory") then
                for _, part in ipairs(child:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.LocalTransparencyModifier = 0
                        part.Transparency = 0
                    elseif part:IsA("Decal") or part:IsA("Texture") then
                        part.Transparency = 0
                    elseif part:IsA("ParticleEmitter") or part:IsA("Beam") or part:IsA("Trail") then
                        part.Enabled = true
                    end
                end
            end
        end
    end
    FeatureCallbacks["NoObject"] = function(v)
        noObjectsOn = v
        if noObjLoopConn then noObjLoopConn:Disconnect(); noObjLoopConn = nil end
        if v then
            noObjLoopConn = RunService.RenderStepped:Connect(function()
                if not noObjectsOn then return end
                hideEquippedWeapons()
            end)
        else
            restoreEquippedWeapons()
        end
    end
    local function isFruitObject(obj)
        if not obj or not obj.Parent then return false end
        local name = string.lower(obj.Name)
        if name:find("fruit") or name:find("fruta") then return true end
        if obj:FindFirstChild("Fruit") or obj:FindFirstChild("FruitName") or obj:FindFirstChild("EatRemote") or obj:GetAttribute("Fruit") then return true end
        if (obj:IsA("Tool") or obj:IsA("Model")) and name:find("-") then
            if obj:FindFirstChild("Handle") or obj:FindFirstChildOfClass("MeshPart") or obj:FindFirstChildOfClass("SpecialMesh", true) then
                return true
            end
        end
        return false
    end
    local function applyScaleToFruit(fruit, targetScale)
        if not fruit or not fruit.Parent then return end
        pcall(function()
            if fruit:IsA("Model") then
                if not fruit:GetAttribute("SpookyOrigScale") then
                    fruit:SetAttribute("SpookyOrigScale", fruit:GetScale() or 1)
                end
                local orig = fruit:GetAttribute("SpookyOrigScale") or 1
                fruit:ScaleTo(orig * targetScale)
            end
            for _, part in ipairs(fruit:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.CanCollide = false
                    part.Massless = true
                    if not fruit:IsA("Model") and part.Name == "Handle" then
                        if not part:GetAttribute("OrigPartSize") then
                            part:SetAttribute("OrigPartSize", part.Size)
                        end
                        part.Size = (part:GetAttribute("OrigPartSize") or Vector3.new(1,1,1)) * targetScale
                    end
                elseif part:IsA("SpecialMesh") and not fruit:IsA("Model") then
                    if not part:GetAttribute("OrigMeshScale") then
                        part:SetAttribute("OrigMeshScale", part.Scale)
                    end
                    part.Scale = (part:GetAttribute("OrigMeshScale") or Vector3.new(1,1,1)) * targetScale
                end
            end
        end)
    end
    local function restoreAllFruitScales()
    _G.restoreAllFruitScales = restoreAllFruitScales
        _G.Spooky_RestoreFruitScales = restoreAllFruitScales
        pcall(function()
            for _, item in ipairs(workspace:GetChildren()) do
                if isFruitObject(item) and item:IsA("Model") and item:GetAttribute("SpookyOrigScale") then
                    pcall(function() item:ScaleTo(item:GetAttribute("SpookyOrigScale")) end)
                end
            end
            local fruitFolder = workspace:FindFirstChild("Fruit") or workspace:FindFirstChild("Fruits") or workspace:FindFirstChild("Items")
            if fruitFolder then
                for _, item in ipairs(fruitFolder:GetChildren()) do
                    if isFruitObject(item) and item:IsA("Model") and item:GetAttribute("SpookyOrigScale") then
                        pcall(function() item:ScaleTo(item:GetAttribute("SpookyOrigScale")) end)
                    end
                end
            end
            local function restoreTool(tool)
                if not tool or not isFruitObject(tool) then return end
                if tool:IsA("Model") and tool:GetAttribute("SpookyOrigScale") then
                    pcall(function() tool:ScaleTo(tool:GetAttribute("SpookyOrigScale")) end)
                else
                    for _, part in ipairs(tool:GetDescendants()) do
                        if part:IsA("BasePart") and part:GetAttribute("OrigPartSize") then
                            part.Size = part:GetAttribute("OrigPartSize")
                        elseif part:IsA("SpecialMesh") and part:GetAttribute("OrigMeshScale") then
                            part.Scale = part:GetAttribute("OrigMeshScale")
                        end
                    end
                end
            end
            local char = LocalPlayer.Character
            if char then
                for _, tool in ipairs(char:GetChildren()) do
                    if tool:IsA("Tool") then restoreTool(tool) end
                end
            end
            local bp = LocalPlayer:FindFirstChild("Backpack")
            if bp then
                for _, tool in ipairs(bp:GetChildren()) do
                    if tool:IsA("Tool") then restoreTool(tool) end
                end
            end
        end)
    end
    local function scanAndScaleFruits(scale)
        for _, item in ipairs(workspace:GetChildren()) do
            if isFruitObject(item) then
                applyScaleToFruit(item, scale)
            end
        end
        local fruitFolder = workspace:FindFirstChild("Fruit") or workspace:FindFirstChild("Fruits")
        if fruitFolder then
            for _, item in ipairs(fruitFolder:GetChildren()) do
                if isFruitObject(item) then
                    applyScaleToFruit(item, scale)
                end
            end
        end
        local char = LocalPlayer.Character
        if char then
            for _, tool in ipairs(char:GetChildren()) do
                if tool:IsA("Tool") and isFruitObject(tool) then
                    applyScaleToFruit(tool, scale)
                end
            end
        end
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if bp then
            for _, tool in ipairs(bp:GetChildren()) do
                if tool:IsA("Tool") and isFruitObject(tool) then
                    applyScaleToFruit(tool, scale)
                end
            end
        end
    end
    task.spawn(function()
        while isCurrentSession() do
            task.wait(1.5)
            if FeatureStates["FruitSize"] and (Settings.fruitScale or 50) > 1 then
                scanAndScaleFruits(Settings.fruitScale or 50)
            end
        end
    end)
    FeatureCallbacks["FruitSize"] = function(v)
        if v then
            scanAndScaleFruits(Settings.fruitScale or 50)
        else
            restoreAllFruitScales()
        end
    end
    local originalFonts = {}
    local FONT_ENUMS = {
        Enum.Font.GothamBold, Enum.Font.FredokaOne, Enum.Font.Arcade, Enum.Font.Cartoon,
        Enum.Font.SciFi, Enum.Font.PermanentMarker, Enum.Font.Bodoni, Enum.Font.SourceSansBold
    }
    FeatureCallbacks["FontChanger"] = function(v)
        local chosenFont = FONT_ENUMS[Settings.fontIdx] or Enum.Font.GothamBold
        if v then
            for _, obj in ipairs(PlayerGui:GetDescendants()) do
                if (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) and not obj:IsDescendantOf(ScreenGui) then
                    if not originalFonts[obj] then originalFonts[obj] = obj.Font end
                    pcall(function() obj.Font = chosenFont end)
                end
            end
        else
            for obj, origFont in pairs(originalFonts) do
                pcall(function() obj.Font = origFont end)
            end
            originalFonts = {}
        end
    end
    FeatureCallbacks["DeleteShip"] = function(v)
        if v then
            local boats = workspace:FindFirstChild("Boats") or workspace:FindFirstChild("Ships")
            if boats then boats:ClearAllChildren() end
        end
    end
    FeatureCallbacks["DeltaExecutor"] = function(v)
        if v then
            task.spawn(function()
                -- remote loader removed
            end)
        end
    end
end
registerConnection(UserInputService.InputBegan:Connect(function(input, gpe)
    if gpe or isSimulatingKeys or (_G.IsSyntheticKey and _G.IsSyntheticKey(input.KeyCode)) then return end
    if UserInputService:GetFocusedTextBox() then return end
    if input.UserInputType == Enum.UserInputType.Keyboard then
        for _, entry in ipairs(PCKeybinds) do
            if entry.key and entry.key ~= "None" and (input.KeyCode == entry.key or input.KeyCode.Name == entry.key or (typeof(entry.key) == "EnumItem" and input.KeyCode == entry.key)) then
                if entry.id == "ToggleUI" then
                    if MAINUIframe then
                        if _G.SpookyToggleUI then _G.SpookyToggleUI(input) end
                    end
                elseif entry.mode == "Toggle" then
                    if toggleFeature then
                        toggleFeature(entry.id)
                    elseif FeatureStates[entry.id] ~= nil and setFeatureState then
                        setFeatureState(entry.id, not FeatureStates[entry.id])
                    end
                else
                    if entry.id == "MacroCombo" or entry.id == "PvPMacro" then
                        if (Spooky.IsMacroRunning and Spooky.IsMacroRunning()) and (isSimulatingKeys or (_G.IsSyntheticKey and (_G.IsSyntheticKey(input.KeyCode) or _G.IsSyntheticKey(entry.key)))) then

                        else
                            if Spooky.TryMacroInput then Spooky.TryMacroInput(input) end
                        end
                    elseif entry.id == "SwitchCamLock" then
                        if FeatureCallbacks["SwitchCamLock"] then
                            pcall(function() FeatureCallbacks["SwitchCamLock"](true) end)
                        end
                    elseif entry.run then
                        pcall(entry.run)
                    elseif FeatureCallbacks[entry.id] then
                        pcall(function() FeatureCallbacks[entry.id](true) end)
                    end
                    notifyToggle("Triggered: " .. (entry.name or entry.id), true)
                end
            end
        end
    end
end))
pcall(function()
    if isfile and isfile("RiftWtf_BF_AutoLoad_FullConfig.txt") and _G.Spooky_LoadFullConfig then
